insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-01-01', 'phase-01', 1, 'Your Workspace (before writing a single line of real code)', 'You cannot learn to code without a place to write it, run it, and save it. This stage exists so every topic after it has a working environment underneath it.', 16, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-01-02', 'phase-01', 2, 'Structure: HTML', 'HTML comes before CSS because you cannot style what doesn''t exist yet. HTML comes before JavaScript because you cannot manipulate a DOM that hasn''t been defined.', 10, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-01-03', 'phase-01', 3, 'Presentation: CSS', 'CSS depends entirely on HTML existing first. Ordered internally from syntax → box model → layout → responsiveness → visual polish, since each builds on the one before.', 18, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-01-04', 'phase-01', 4, 'Behavior: JavaScript (Full Sequence, dependency-ordered)', 'JavaScript comes after HTML/CSS because its most motivating use case (manipulating the page) needs a page to exist. Ordered in true dependency order — language core → functions → scope/execution → closures/this/memory → data structures → strings/numbers/dates → error handling → regex → OOP → iteration → meta-programming → modules → async → HTTP → DOM/browser → performance/security → functional patterns → architecture → algorithms → tooling/testing/debugging → engine internals/spec. Topics that could otherwise appear in more than one place (e.g. spread/rest appearing under both Functions and Advanced Operators) are merged at first occurrence.', 162, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-01-05', 'phase-01', 5, 'Adding Types: TypeScript', 'TypeScript only makes sense once JavaScript is solid — it''s a typed layer on top of JS, not a separate language. Intro concepts come first, then the full Mastery set from Phase 01b, each ordered so foundational type mechanics (generics, narrowing) precede the advanced techniques that combine them (conditional/mapped types, template literals).', 42, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-01-06', 'phase-01', 6, 'Data: SQL Fundamentals', 'SQL is intentionally placed after the full JS/TS language stack rather than earlier — it''s conceptually independent of JavaScript, and interleaving it earlier would split focus mid-language. By this point you also have enough programming maturity (data structures, objects) to map naturally onto relational concepts (tables ≈ arrays of objects, rows ≈ objects, columns ≈ keys).', 12, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-01-07', 'phase-01', 7, 'Collaboration & Code Quality', 'Everything in this final stage assumes you now have real, multi-file projects worth versioning, linting, and formatting properly — HTML/CSS pages, JS/TS scripts, and SQL schemas from Stages 2–6. This is why deeper Git workflows, commit hygiene, and tooling are saved for last rather than front-loaded in Stage 1, where you had nothing substantial to collaborate on yet.', 13, 6);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-02-01', 'phase-02', 1, 'React 18 (Foundation)', 'Everything else in Phase 02 sits on top of React. Next.js is a framework around React, not a replacement for it — so React must be solid, and deep, first.', 37, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-02-02', 'phase-02', 2, 'Next.js 15 App Router (Core Framework)', 'Requires all of Stage 1 — the App Router is React Server Components plus a file-system router, so nothing here works without React fundamentals, hooks, and Suspense already understood.', 35, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-02-03', 'phase-02', 3, 'App Router: Advanced Routing Features', 'All topics in this stage are App Router features layered on top of Stage 2''s routing model — none make sense without layouts, segments, and the caching model already understood.', 11.5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-02-04', 'phase-02', 4, 'Client-Side Concerns', 'Independent of the App Router internals in Stage 3 — these are client-side/browser concerns that fit better once you have real components and pages to apply them to.', 5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-02-05', 'phase-02', 5, 'Data Layer Integration', NULL, 5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-02-06', 'phase-02', 6, 'Deployment', 'Deliberately last. Deployment only matters once there''s a real, working app — learning Vercel configuration before pages, data fetching, and routing exist would be abstract and unmotivated.', 8.5, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-03-01', 'phase-03', 1, 'CSS Foundations (Beyond Phase 01''s CSS3 Basics)', 'Phase 01''s CSS3 stage covered the box model, flexbox, grid, and responsive basics. This stage picks up where that left off — the modern CSS features that Tailwind, theming, and design-token tooling all build on.', 7.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-03-02', 'phase-03', 2, 'Tailwind CSS (Utility-First Foundation)', 'Requires the cascade/@layer understanding from Stage 1 — Tailwind is built on cascade layers internally, and its config system uses CSS custom properties for theming.', 8, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-03-03', 'phase-03', 3, 'Class Composition Utilities', 'These three tools exist specifically to manage Tailwind utility classes at scale — none of them are useful without Tailwind (Stage 2\\) already in place, and each builds on the previous.', 5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-03-04', 'phase-03', 4, 'Component Libraries', 'Both libraries in this stage assume Tailwind (Stage 2\\) and the class-composition utilities (Stage 3\\) are already understood — shadcn/ui in particular is built directly from both.', 8, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-03-05', 'phase-03', 5, 'Forms & Validation', 'Forms are placed after component libraries (Stage 4\\) because real form UIs are typically built from shadcn/Radix inputs, not raw HTML elements — though the underlying form-state logic is library-agnostic.', 7, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-03-06', 'phase-03', 6, 'General-Purpose Utilities', 'These three libraries are independent of styling and forms — placed after Stage 5 simply because they''re commonly reached for while building the form/data-display logic that comes right after this phase, not because of any real dependency.', 3.5, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-03-07', 'phase-03', 7, 'Design Tokens & Alternative Styling Systems', 'Placed last deliberately — both topics here are either an extension of concepts already covered (Style Dictionary formalizes what CSS Custom Properties \+ theming already introduced) or a full alternative to the Tailwind approach (vanilla-extract), most meaningful as a comparison once Tailwind is already second nature.', 6, 6);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-04-01', 'phase-04', 1, 'Client State: Context''s Limits, Then Zustand', 'React Context was introduced generally in Phase 02\. This stage starts from where Context breaks down, then introduces the tool that fixes it.', 7, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-04-02', 'phase-04', 2, 'Server State: TanStack Query, Then tRPC', 'Server state (data that lives on a server and is merely cached on the client) is a fundamentally different problem from client state (Stage 1\\) — it needs caching, revalidation, and request deduplication, which is what this stage''s tools provide.', 15, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-04-03', 'phase-04', 3, 'State Machines', 'Conceptually independent of Stages 1–2, but placed after both because state machines are usually reached for once you''ve felt the pain of complex state logic that plain useState/Zustand/useReducer can''t cleanly express — that pain is easier to appreciate with Stage 1–2 experience already in hand.', 8, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-04-04', 'phase-04', 4, 'Rendering & Resilience Primitives (Applied Depth)', 'React.lazy, Suspense, and createPortal were already introduced at a conceptual level in Phase 02, Stage 1\. This stage doesn''t re-teach the mechanics — it applies them at real-project depth, now that Stage 2''s data-fetching layer exists to make Suspense-for-data meaningful.', 6.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-04-05', 'phase-04', 5, 'Browser Observation APIs', 'Independent of the state/data/rendering stages above — these are browser-native APIs for observing layout and viewport changes, placed here because their most common React use case (infinite scroll, responsive components) is more meaningful with the data-fetching layer (Stage 2\\) already available.', 4.5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-04-06', 'phase-04', 6, 'Virtualization & Profiling (Capstone)', 'Both topics require a real, data-populated, multi-feature app to be meaningful — placed last because they''re applied to everything built in Stages 1–5, not new concepts in isolation.', 6, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-05-01', 'phase-05', 1, 'Server Runtime & Framework', 'Everything in this phase runs on top of Node.js and, for routing, Express — both must be solid before anything else here makes sense.', 17, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-05-02', 'phase-05', 2, 'API Design & Hardening', 'Requires Express (Stage 1\\) — REST conventions are applied through Express routes, and every hardening middleware in this stage attaches to that same Express app.', 15, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-05-03', 'phase-05', 3, 'Testing the API', NULL, 3, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-05-04', 'phase-05', 4, 'Database Layer', 'Independent of Express/Node conceptually, but placed here because a real backend needs persistence, and the API/testing layer built in Stages 1–3 is what will consume this data.', 26.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-05-05', 'phase-05', 5, 'Authentication & Token Security', 'Requires the database layer (Stage 4\\) — auth needs somewhere to store users and their credentials. Internally reordered from the official list: HMAC-SHA256 moved ahead of JWT, since HS256 (HMAC-SHA256) is one of JWT''s standard signing algorithms — teaching JWT first would mean explaining "the token is signed" without the mechanism underneath it.', 16, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06-01', 'phase-06', 1, 'Unit & Component Testing', 'The foundation of the testing pyramid. Requires a real app with components and logic (Phases 01–05) to have anything meaningful to test.', 15.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06-02', 'phase-06', 2, 'End-to-End Testing', NULL, 7, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06-03', 'phase-06', 3, 'Continuous Integration', NULL, 8, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06-04', 'phase-06', 4, 'Containerization', 'Independent of testing/CI conceptually, but placed here because Docker images are what CI will build and what deployment (Stage 5\\) will run — this stage sits at the intersection.', 18, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06-05', 'phase-06', 5, 'Deployment & Exit A Polish', 'Deliberately last. Deployment needs a tested, containerized, CI-integrated app (Stages 1–4) to deploy. The CI badge (shields.io) is the final topic since it''s a status indicator for a pipeline that must already be working.', 6, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06b-01', 'phase-06b', 1, 'React Native Foundation', 'Requires React (Phase 02\\) as a direct prerequisite — React Native uses the same component/hooks model, with a different rendering target (native views instead of the DOM).', 16, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06b-02', 'phase-06b', 2, 'Storage & Secure Token Handling', 'Requires RN fundamentals and navigation (Stage 1\\) — a real app with multiple screens is what makes persistent storage meaningful.', 6, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06b-03', 'phase-06b', 3, 'Native Device Capabilities', 'Requires Expo (Stage 1, Topic 2\\) — most native capabilities are exposed through Expo''s SDK modules.', 8, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06b-04', 'phase-06b', 4, 'Performance & Internals', 'Requires a real app with lists and navigation (Stages 1–3) to have anything meaningful to profile or optimize.', 6.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-06b-05', 'phase-06b', 5, 'Shipping', 'Deliberately last. Requires a working, tested app (Stages 1–4) and EAS Build (Stage 1, Topic 2\\) as the build pipeline that makes submission possible.', 8, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-07-01', 'phase-07', 1, 'Manual HTTP Tooling', 'Requires a real API to hit (Phase 05\\) — these tools exist to inspect, test, and debug HTTP requests/responses by hand, before any documentation layer is added on top.', 6, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-07-02', 'phase-07', 2, 'API Documentation', 'Requires a real, stable API (Phase 05\\) and familiarity with inspecting requests/responses (Stage 1\\) — you can''t document an API accurately without having manually explored its behavior first.', 9, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-07-03', 'phase-07', 3, 'GraphQL (Alternative API Paradigm)', 'Placed last deliberately. Exit B''s own interview-prep checklist expects you to answer "REST vs GraphQL tradeoffs" — that comparison is only meaningful once REST (Phase 05\\) and its documentation ecosystem (Stage 2\\) are already solid. Learning GraphQL first would remove the contrast that makes it click.', 12, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-08-01', 'phase-08', 1, 'Array & String Scanning Techniques', 'The simplest pattern family — each operates directly on arrays/strings using nothing but the loop and indexing fundamentals from Phase 01\. No data structure beyond an array is required.', 14, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-08-02', 'phase-08', 2, 'Hashing', NULL, 4, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-08-03', 'phase-08', 3, 'Linear Structures: Stack & Queue', 'Both structures are prerequisites for Stage 4''s traversal algorithms — DFS is naturally expressed with a stack (or recursion, which uses the call stack implicitly), BFS requires a queue. This stage must come before Stage 4\.', 9, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-08-04', 'phase-08', 4, 'Traversal: BFS, DFS, and Trees', 'Directly requires the queue (Stage 3, Topic 8\\) for BFS and the stack/recursion model (Stage 3, Topic 6\\) for DFS — cannot be taught before those exist.', 14, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-08-05', 'phase-08', 5, 'Heap / Priority Queue', NULL, 4, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-08-06', 'phase-08', 6, 'Dynamic Programming', NULL, 14, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-08-07', 'phase-08', 7, 'Interview Meta-Skills', 'Requires actual DSA competence (Stages 1–6) to be meaningful — a communication framework or system design vocabulary is empty without real problems solved to apply it to.', 12, 6);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-09-01', 'phase-09', 1, 'Self-Hosted Caching Infrastructure', 'Requires PostgreSQL and a real backend (Phase 05\\) — caching only matters once there''s real query load and connection pressure to relieve.', 11.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-09-02', 'phase-09', 2, 'Hosted & Distributed Caching', 'Requires Redis fundamentals (Stage 1\\) — this stage is the caching-layer parallel to Phase 05''s PostgreSQL → Supabase/Neon progression: self-hosted concept first, hosted/managed alternative second.', 3.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-09-03', 'phase-09', 3, 'Transactional Email', 'Independent of the caching stages above — a new capability area. Ordered so the delivery mechanism (Resend) is understood before investing in a component-based templating system (React Email) that plugs into it.', 5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-09-04', 'phase-09', 4, 'Payments', 'Placed last deliberately — the most complex and highest-stakes topic in the phase, benefiting from the caching (Stage 1–2) and reliable-delivery concepts (Stage 3\\) already in place, since payment webhooks demand exactly that kind of reliability thinking.', 8, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-10-01', 'phase-10', 1, 'Request Context & Structured Logging', 'Requires a real backend (Phase 05\\) with real request traffic — logging and context tracing only matter once there''s something happening to log.', 6.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-10-02', 'phase-10', 2, 'Error Tracking & Uptime', 'Requires structured logging (Stage 1\\) as a complementary but distinct concept — logs answer "what happened," error tracking answers "what went wrong and who does it affect."', 5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-10-03', 'phase-10', 3, 'Log Aggregation & Observability Platforms', 'Requires structured logs to exist (Stage 1\\) — these platforms exist to collect, search, and visualize exactly that output at scale, which a single server''s local log files can''t do.', 10, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-10-04', 'phase-10', 4, 'Product Analytics Foundation', 'A distinct concern from infrastructure monitoring (Stages 1–3) — this is about user behavior, not system health. Independent of everything above, but grouped after it since it''s a separate observability axis, not a prerequisite.', 5.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-10-05', 'phase-10', 5, 'Analytics-Driven Features', 'All four topics require the PostHog foundation (Stage 4\\) — none of these features exist without an analytics platform and event pipeline already in place.', 8.5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-10-06', 'phase-10', 6, 'Compliance', NULL, 4, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-11-01', 'phase-11', 1, 'Real-Time Communication', 'Ordered by mechanism complexity — each topic''s limitations motivate the next. Requires a real deployed app (Phase 06\\) and backend (Phase 05\\) to build real-time features on top of.', 15, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-11-02', 'phase-11', 2, 'PostgreSQL Index Depth', 'Requires Phase 05''s PostgreSQL fundamentals — this stage goes deeper into exactly the index/EXPLAIN ANALYZE territory Phase 05 introduced at a basic level.', 9.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-11-03', 'phase-11', 3, 'Storage & Concurrency Internals', 'The deepest topics in the phase. Ordered so MVCC comes first (it explains what VACUUM cleans up), then WAL (which read replicas directly depend on for replication), then monitoring (most useful once there''s real concurrent/replicated activity to observe).', 13.5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-11-04', 'phase-11', 4, 'Search', 'A genuinely independent theme from Stages 1–3, ordered from PostgreSQL''s built-in option (needing nothing new infrastructure-wise) to increasingly dedicated, heavyweight search engines.', 16, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-01', 'phase-12', 1, 'LLM API Foundations', 'Requires a real backend (Phase 05\\) to call these APIs from server-side, and background/job infrastructure context (Phase 09''s Redis) that Stage 4 will build on. OpenAI is placed first as the first provider learned; Anthropic follows as the second, before anything compares or routes between them.', 8.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-02', 'phase-12', 2, 'Embeddings & Vector Storage', 'Requires OpenAI API access (Stage 1\\) for the embedding model itself, and Phase 05/11''s PostgreSQL depth as the storage layer these vectors live in.', 9.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-03', 'phase-12', 3, 'RAG (The Synthesis)', NULL, 12, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-04', 'phase-12', 4, 'SDK & Background Jobs', 'Requires RAG (Stage 3\\) to exist as real work worth simplifying (Vercel AI SDK) and queuing (BullMQ) — introducing these tools before there''s a real pipeline to apply them to would make them abstract.', 8, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-05', 'phase-12', 5, 'Claude-Specific Depth', 'Requires the Anthropic API (Stage 1, Topic 3\\) as the foundation — these three topics are all Claude-specific behavior on top of the basic Messages API already covered.', 5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-06', 'phase-12', 6, 'Structured Output & Multi-Model Routing', 'Both topics require both providers (Stage 1\\) to be genuinely understood — tool calling is commonly needed across either provider, and routing is meaningless with only one model to route to.', 6, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-07', 'phase-12', 7, 'Cost & Governance', 'Requires real multi-model usage (Stage 6\\) to have actual costs across providers worth tracking and governing — introducing cost tracking before there''s real usage would have nothing to measure.', 4, 6);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-12-08', 'phase-12', 8, 'Prompt Engineering & Evaluation', 'Requires real AI features to exist (RAG from Stage 3, tool calling from Stage 6\\) — both prompt engineering and evaluation are meaningfully practiced against real, built systems, not in the abstract. Evals are placed genuinely last since you need something built before you can evaluate it.', 9, 7);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-13-01', 'phase-13', 1, 'Client-Side Storage', 'Requires Phase 02''s localStorage/sessionStorage as the point of comparison — IndexedDB is what those simpler APIs can''t handle: large, structured, queryable client-side data.', 5.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-13-02', 'phase-13', 2, 'Parallelism', NULL, 4.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-13-03', 'phase-13', 3, 'Cross-Context Communication', NULL, 1.5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-13-04', 'phase-13', 4, 'Browser Rendering & Animation Internals', 'A cluster of APIs concerned with how and when the browser paints — ordered from the lowest-level timing primitive (rAF) to the most advanced/niche (CSS Houdini).', 7.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-13-05', 'phase-13', 5, 'Real-Time Collaboration: The Yjs Stack', 'The centerpiece of this phase, and the official curriculum''s designated Build in Public moment. Requires WebSockets and WebRTC (Phase 11\\) as transport context, and IndexedDB (Stage 1\\) as a persistence context — Yjs itself is transport- and storage-agnostic, and only makes sense once you understand what it''s being connected to.', 12.5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-13-06', 'phase-13', 6, 'Rich Text Editors', 'Moved from the official ordering — ProseMirror is taught before Tiptap, not after, since Tiptap is a wrapper built directly on top of ProseMirror. This follows the same raw-before-wrapper pattern used throughout this series.', 9, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-14-01', 'phase-14', 1, 'Load Testing', 'Requires a real, deployed app (Phase 06\\) — load testing has nothing to test against before then.', 8.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-14-02', 'phase-14', 2, 'Security Threat Model & Scanning', 'OWASP Top 10 is placed first in this stage deliberately — it''s the threat model everything else in this stage addresses. Learning ZAP, CSP, or JWT pinning before understanding what threats they mitigate would teach tool operation without the reasoning behind it.', 12.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-14-03', 'phase-14', 3, 'Secret Management', 'Ordered detection-before-prevention — establishing whether a leak has already happened (trufflehog) before setting up a mechanism to stop future ones (git-secrets), the same threat-first-then-tool logic used in Stage 2\.', 3, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-14-04', 'phase-14', 4, 'Automated Security Monitoring', 'A cluster of small, lightweight tools — most are single-purpose checks that build on context established earlier in this phase.', 4.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-14-05', 'phase-14', 5, 'Compliance', 'Requires the practical security measures from Stages 1–4 as context — compliance frameworks attest to controls that need to actually exist first; learning the framework before the practice would be abstract.', 5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-15-01', 'phase-15', 1, 'Build Tools', 'Foundational — everything else in this phase either analyzes what these tools produce (Stage 2\\) or measures the result of using them (Stage 3).', 6, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-15-02', 'phase-15', 2, 'Bundle Analysis', 'Three tools, each attached to a different build system — ordered by which build system context you already have: Next.js (Phase 02, long since known) first, Vite (Stage 1, just learned) second, and raw Rollup (the most general-purpose, underlying both Vite''s production build and usable standalone) last.', 3.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-15-03', 'phase-15', 3, 'Performance Auditing', NULL, 2.5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-15-04', 'phase-15', 4, 'CSS-in-JS', 'An independent theme from Stages 1–3. Runtime-based libraries (styled-components, Emotion) are taught before the zero-runtime alternative (Linaria) so the tradeoff Linaria addresses — CSS-in-JS ergonomics without runtime cost — is understood as a response to a real limitation, not learned in isolation.', 7.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-16-01', 'phase-16', 1, 'Cloud Object Storage', NULL, 4, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-16-02', 'phase-16', 2, 'Infrastructure as Code', 'Terraform doesn''t strictly require S3 (Stage 1), but S3 makes a concrete, already-understood resource to provision as a first real Terraform example rather than an abstract one.', 11.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-16-03', 'phase-16', 3, 'Kubernetes Core', 'Requires Docker (Phase 06\\) as a direct prerequisite — Kubernetes orchestrates containers, it doesn''t replace understanding what a container actually is.', 20, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-16-04', 'phase-16', 4, 'Kubernetes Ecosystem', 'All three topics require core Kubernetes concepts and kubectl (Stage 3\\) already in place — each is a specialized tool or resource type layered on top of that foundation.', 9.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-17-01', 'phase-17', 1, 'Caching & Optimistic Update Patterns', 'Requires Phase 09''s Redis work as the caching substrate these patterns are named strategies for, and Phase 04''s TanStack Query as the client-side context Optimistic Updates most commonly applies to.', 6.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-17-02', 'phase-17', 2, 'Database Concurrency Control', 'Requires Phase 05''s transaction fundamentals and Phase 11''s MVCC deep dive — these two locking strategies are different answers to the same underlying concurrent-write problem MVCC exists to manage.', 7, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-17-03', 'phase-17', 3, 'Distributed Transactions & Messaging Resilience', 'The largest cluster in the phase. Requires idempotency (Stage 2, Topic 6\\) as a hard prerequisite — every pattern here involves retries, and retries without idempotency cause duplicate side effects rather than fixing failures.', 11.5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-17-04', 'phase-17', 4, 'Architectural Styles', 'Both topics are broader architectural styles built from the messaging reliability patterns in Stage 3 — neither makes sense taught before Outbox and DLQ exist as the mechanisms that make them work in practice, not just in theory.', 7.5, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-17-05', 'phase-17', 5, 'Multi-Tenancy', NULL, 3.5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-17-06', 'phase-17', 6, 'Deployment Strategy & Resilience Validation', 'Requires a real, architecturally mature system (Stages 1–5) to deploy and test — both topics are about operating and validating what''s already been built, not new features in themselves.', 9.5, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-18-01', 'phase-18', 1, 'Package Publishing', NULL, 3, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-18-02', 'phase-18', 2, 'Decision-Making Practices', 'Foundational to everything that follows in this phase — Stage 4''s documentation artifacts are largely the written record of the practices introduced here.', 4.5, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-18-03', 'phase-18', 3, 'Engineering Process Practices', 'A cluster of process disciplines, mostly independent of each other, but all downstream of having a real, deployed, monitored system (Phases 05–17) to actually apply them to.', 10, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-18-04', 'phase-18', 4, 'Documentation Artifacts: Decisions & Architecture', 'These artifacts are downstream of Stage 2''s practices — the folder structure and files exist to hold the output of the ADR/RFC discipline, not as independent new concepts.', 4, 3);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-18-05', 'phase-18', 5, 'Documentation Artifacts: Operational', 'Each artifact in this stage draws its actual content from a specific earlier phase''s work — these are downstream summaries, not new material to learn.', 8.5, 4);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-18-06', 'phase-18', 6, 'Documentation Artifacts: Product & Personal', 'The two most independent artifacts in the phase — neither draws on a specific prior phase''s technical content the way Stage 5''s artifacts do.', 2.5, 5);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-19-01', 'phase-19', 1, 'API Practice', 'The only genuinely technical stage in this phase — placed first, trivial before real, as a warm-up before the career/community-focused stages that make up the rest of the phase.', 3.5, 0);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-19-02', 'phase-19', 2, 'Job & Talent Platforms', 'Requires a complete portfolio (effectively all of Phases 01–18) to have a profile worth putting on any of these platforms. Ordered niche-to-broad: the two India/startup-focused platforms first, LinkedIn last since its payoff specifically depends on the accumulated 16-month posting history Exit E''s own description assumes already exists.', 6, 1);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-19-03', 'phase-19', 3, 'Product Launch & Community', 'Requires a genuinely complete, demo-able product — ClientSync, after 18 phases of work — to have anything worth launching or discussing.', 5, 2);
insert into public.stages (id, phase_id, stage_number, title, description, estimated_hours, order_index) values ('stage-19-04', 'phase-19', 4, 'Technical Writing Platforms', 'dev.to has already been used informally throughout nearly every Build in Public section since Phase 06 — this stage is about formal platform mastery and audience-building, not the first introduction to posting there.', 3.5, 3);
