insert into public.topic_groups (id, topic_id, heading, order_index) values ('8bd8dd1e-9745-5fc6-b3ec-a97182e826cc', 'topic-17-001', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('8bd8dd1e-9745-5fc6-b3ec-a97182e826cc', 'The pattern by name — application code owns cache population, checking cache first and falling back to the source of truth on a miss', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('8bd8dd1e-9745-5fc6-b3ec-a97182e826cc', 'Why this is the most common caching pattern in practice — simple, cache and DB can diverge briefly, but the application controls exactly when and what to cache', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('8bd8dd1e-9745-5fc6-b3ec-a97182e826cc', 'Failure modes — a cache-aside system serving stale data during the window between a DB write and cache invalidation', 2);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('f702e734-9afe-5610-89ea-7f77000f833d', 'topic-17-002', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f702e734-9afe-5610-89ea-7f77000f833d', 'The pattern — every write goes through the cache layer first, which then writes to the underlying store, keeping cache and DB consistent by construction', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f702e734-9afe-5610-89ea-7f77000f833d', 'Tradeoff against cache-aside (1) — write latency increases (every write touches the cache), but read-after-write staleness risk decreases', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f702e734-9afe-5610-89ea-7f77000f833d', 'When write-through is worth the extra write latency — read-heavy workloads where consistency matters more than write speed', 2);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('bf62de2a-8d99-551f-b098-93a319f5a37b', 'topic-17-003', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('bf62de2a-8d99-551f-b098-93a319f5a37b', 'The pattern — updating the UI immediately based on an assumed-successful outcome, before the server actually confirms it', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('bf62de2a-8d99-551f-b098-93a319f5a37b', 'Rollback handling — reverting the optimistic UI state if the server ultimately rejects the operation (ties directly back to Phase 04''s TanStack Query mutation rollback mechanics)', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('bf62de2a-8d99-551f-b098-93a319f5a37b', 'Why this matters for perceived performance — the user sees instant feedback even though the real round-trip hasn''t completed', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('bf62de2a-8d99-551f-b098-93a319f5a37b', 'Risk surface — optimistic updates assuming success for operations that are actually likely to fail (e.g. anything touching Stage 2''s concurrency control) can create a confusing UX when the rollback happens', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('ade4ddbf-d701-5689-b898-39fd66e78d96', 'topic-17-004', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('ade4ddbf-d701-5689-b898-39fd66e78d96', 'Version-based conflict detection — attaching a version number (or timestamp) to a row, and rejecting a write if the version has changed since it was read', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('ade4ddbf-d701-5689-b898-39fd66e78d96', 'Why this is called "optimistic" — it assumes conflicts are rare and only pays the cost of detecting one when it actually happens', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('ade4ddbf-d701-5689-b898-39fd66e78d96', 'Implementation in Prisma (Phase 05) — a version column checked and incremented on update, application code handling the conflict when the check fails', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('ade4ddbf-d701-5689-b898-39fd66e78d96', 'When optimistic locking fits — low-contention scenarios where most writes don''t actually collide', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('de90b5d8-6ea1-5fd7-9241-5161c9799d4f', 'topic-17-005', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('de90b5d8-6ea1-5fd7-9241-5161c9799d4f', 'Lock-based conflict prevention — acquiring a lock (SELECT ... FOR UPDATE in PostgreSQL, Phase 05) before reading, preventing any other transaction from modifying the same row until the lock is released', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('de90b5d8-6ea1-5fd7-9241-5161c9799d4f', 'Why this is called "pessimistic" — it assumes conflicts are common enough that preventing them upfront is cheaper than detecting and retrying them', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('de90b5d8-6ea1-5fd7-9241-5161c9799d4f', 'Deadlock risk — two transactions each holding a lock the other needs, and why lock ordering discipline matters', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('de90b5d8-6ea1-5fd7-9241-5161c9799d4f', 'When pessimistic locking fits — high-contention scenarios (e.g. a limited-inventory checkout flow) where optimistic locking''s retry cost would be too high', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('3f712faf-441f-5401-937b-84c4ce1d299c', 'topic-17-006', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('3f712faf-441f-5401-937b-84c4ce1d299c', 'The core property — performing the same operation multiple times has the same effect as performing it once', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('3f712faf-441f-5401-937b-84c4ce1d299c', 'Why this matters for retries specifically — a network failure after a write succeeds but before the client receives confirmation is genuinely ambiguous; the client can only recover safely by retrying, and retrying safely requires idempotency', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('3f712faf-441f-5401-937b-84c4ce1d299c', 'Idempotency keys — a client-generated unique identifier attached to a request, letting the server recognize and safely ignore a duplicate (direct callback to Phase 09''s Razorpay webhook idempotency discussion)', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('3f712faf-441f-5401-937b-84c4ce1d299c', 'Where this already showed up earlier in the curriculum without being named — Phase 09''s webhook handling, and now the formal foundation for Stage 3''s Saga, Outbox, and DLQ patterns, all of which assume retryable, idempotent steps', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('1681e557-78b7-55ab-898e-f79692e0d561', 'topic-17-007', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('1681e557-78b7-55ab-898e-f79692e0d561', 'The problem — a business transaction spanning multiple services (no single database transaction can cover all of them, unlike Phase 05''s single-database ACID transactions)', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('1681e557-78b7-55ab-898e-f79692e0d561', 'Choreography vs orchestration — services reacting to each other''s events independently, vs a central coordinator directing each step', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('1681e557-78b7-55ab-898e-f79692e0d561', 'Compensating transactions — since there''s no rollback across services, failure requires explicitly undoing already-completed steps in reverse', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('1681e557-78b7-55ab-898e-f79692e0d561', 'Why each step must be idempotent (Stage 2, Topic 6) — a saga coordinator retrying a step after an ambiguous failure must not cause duplicate effects', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('7e4d7b72-5462-5c0d-94c6-f61fe961a2e3', 'topic-17-008', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('7e4d7b72-5462-5c0d-94c6-f61fe961a2e3', 'The problem it solves — reliably publishing an event as a consequence of a database write, when the write and the publish can''t be a single atomic operation across two different systems (the DB and the message broker)', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('7e4d7b72-5462-5c0d-94c6-f61fe961a2e3', 'The pattern — writing the event to an "outbox" table in the same database transaction as the actual data change, then a separate process reads and publishes from that table', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('7e4d7b72-5462-5c0d-94c6-f61fe961a2e3', 'Why this guarantees consistency — the event write and the data write either both commit or both roll back, since they''re the same PostgreSQL transaction (Phase 05)', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('7e4d7b72-5462-5c0d-94c6-f61fe961a2e3', 'Common use — implementing reliable saga (7) step completion events without a distributed transaction', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('5ddcdd0b-bd3a-5dbe-a19c-7efff543f415', 'topic-17-009', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('5ddcdd0b-bd3a-5dbe-a19c-7efff543f415', 'The pattern — after a message fails processing repeatedly (beyond a retry limit), routing it to a separate queue instead of retrying forever or silently dropping it', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('5ddcdd0b-bd3a-5dbe-a19c-7efff543f415', 'Why this matters operationally — a DLQ makes failures visible and inspectable instead of invisible (ties back to Phase 10''s monitoring/alerting stack — a DLQ with growing depth is exactly the kind of thing worth alerting on)', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('5ddcdd0b-bd3a-5dbe-a19c-7efff543f415', 'Reprocessing strategy — manually or automatically retrying DLQ messages once the underlying issue (a bug, an outage) is fixed', 2);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('a5a70be9-8944-5063-921e-48217e3686bd', 'topic-17-010', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('a5a70be9-8944-5063-921e-48217e3686bd', 'The pattern — tracking failures when calling an unreliable dependency, and "opening" the circuit (failing fast without even attempting the call) once a failure threshold is crossed', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('a5a70be9-8944-5063-921e-48217e3686bd', 'The three states — closed (normal operation), open (failing fast), half-open (cautiously testing if the dependency has recovered)', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('a5a70be9-8944-5063-921e-48217e3686bd', 'Why this prevents cascading failures — a struggling downstream service getting hammered with retries from every caller is often what turns a partial outage into a total one', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('a5a70be9-8944-5063-921e-48217e3686bd', 'Combining with idempotency (Stage 2, Topic 6) — once a circuit closes again, retried calls must be safe to actually retry', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('25912fd0-d657-5cd6-9c91-c07b6d232c7f', 'topic-17-011', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('25912fd0-d657-5cd6-9c91-c07b6d232c7f', 'Services communicating via events rather than direct synchronous calls — publishers don''t know or care who consumes an event', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('25912fd0-d657-5cd6-9c91-c07b6d232c7f', 'Loose coupling as the main benefit — and the corresponding cost: harder to trace a single business operation across many independently-reacting services', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('25912fd0-d657-5cd6-9c91-c07b6d232c7f', 'Event schema design and versioning — events are a long-lived contract between services, unlike an internal function signature that''s easy to change', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('25912fd0-d657-5cd6-9c91-c07b6d232c7f', 'Why this style needs Stage 3''s reliability patterns underneath it — an event-driven system without outbox-guaranteed publishing and DLQ-handled failures is one where events can silently go missing', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('f8b47da6-6cc2-5a3e-b869-acce1e6fb4ec', 'topic-17-012', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f8b47da6-6cc2-5a3e-b869-acce1e6fb4ec', 'The core split — a write model (commands) optimized for validating and applying changes, and a separate read model (queries) optimized for how data is actually displayed/queried', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f8b47da6-6cc2-5a3e-b869-acce1e6fb4ec', 'Why this can outperform a single shared model — the write model doesn''t need to support every query shape, and the read model can be denormalized however is fastest to read', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f8b47da6-6cc2-5a3e-b869-acce1e6fb4ec', 'Eventual consistency — the read model updates asynchronously as it consumes events (11) from the write side, meaning a query can briefly return stale data immediately after a write', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f8b47da6-6cc2-5a3e-b869-acce1e6fb4ec', 'When CQRS is worth the complexity — genuinely different read/write scaling needs or query shapes; explicitly not a default choice for most CRUD-shaped features', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('6eaa269f-ea16-5b2e-b523-5106294d1c56', 'topic-17-013', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('6eaa269f-ea16-5b2e-b523-5106294d1c56', 'Isolation strategies — separate databases per tenant, separate schemas per tenant, or shared schema with a tenant ID column, and the isolation/cost/operational-complexity tradeoff between them', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('6eaa269f-ea16-5b2e-b523-5106294d1c56', 'Row-level security for shared-schema multi-tenancy — enforcing tenant isolation at the database layer itself (ties back to Phase 09''s Supabase RLS discussion) rather than trusting every query to remember a WHERE tenant_id = ? clause', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('6eaa269f-ea16-5b2e-b523-5106294d1c56', 'Connection and resource considerations — how tenant count interacts with Phase 09''s PgBouncer connection pooling', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('6eaa269f-ea16-5b2e-b523-5106294d1c56', 'Tenant-aware caching — extending Stage 1''s caching patterns with tenant-scoped cache keys to avoid one tenant''s cached data leaking into another''s response', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('211154fb-6729-5e0c-a7bc-f686320f7032', 'topic-17-014', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('211154fb-6729-5e0c-a7bc-f686320f7032', 'The pattern — running two identical production environments (blue and green), deploying to the idle one, then switching traffic over once the new version is verified', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('211154fb-6729-5e0c-a7bc-f686320f7032', 'Why this enables near-zero-downtime deploys and instant rollback — switching traffic back to the previous environment is immediate if something''s wrong', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('211154fb-6729-5e0c-a7bc-f686320f7032', 'Implementing this on Kubernetes (Phase 16) — using Service selectors or Ingress rules to control which environment receives traffic', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('211154fb-6729-5e0c-a7bc-f686320f7032', 'Database migration considerations — blue-green deploys get complicated when a schema change (Phase 05) isn''t backward-compatible with the environment still serving traffic', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'topic-17-015', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'The core practice — deliberately injecting failure (killing a service, adding latency, dropping network connections) into a system to verify it degrades gracefully instead of catastrophically', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'Starting small — chaos experiments in a staging environment before ever considering production, and with a clear hypothesis about expected behavior before running one', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'What a chaos experiment actually validates — does the Circuit Breaker (Stage 3, Topic 10) actually open under real failure? Does a Saga (Stage 3, Topic 7) actually compensate correctly if a step fails mid-flight? Does the DLQ (Stage 3, Topic 9) actually catch what it''s supposed to?', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'Writing up results — documenting what was broken, what held, and what was fixed, which is directly the artifact this phase''s Build in Public section and Exit ★3''s portfolio checklist both call out', 3);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'Post: "Why I used the Saga pattern instead of a distributed transaction" — one architectural pattern (Stage 3, Topic 7), explained simply, not the whole phase at once.', 4);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'GitHub: add an ARCHITECTURE.md documenting the patterns used and why — the same documented-decisions discipline Phase 12''s Exit D caution already established for this curriculum.', 5);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('f308a747-fe8d-55a8-abb1-b1f7c0770a95', 'Where + when: dev.to, one post, end of phase.', 6);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('863e2e40-511a-58b7-a5a3-4d00f635bb66', 'topic-18-001', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('863e2e40-511a-58b7-a5a3-4d00f635bb66', 'The problem — coordinating version bumps and changelog entries across a package (or monorepo of packages) without manually tracking what changed since the last release', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('863e2e40-511a-58b7-a5a3-4d00f635bb66', 'Adding a changeset — a small markdown file describing a change and its semver impact (patch/minor/major), committed alongside the code change itself', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('863e2e40-511a-58b7-a5a3-4d00f635bb66', 'Consuming changesets — a release step that reads all pending changesets, bumps versions accordingly, and generates a changelog automatically', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('863e2e40-511a-58b7-a5a3-4d00f635bb66', 'Publishing workflow — combining Changesets with Phase 15''s tsup build step and Phase 06''s GitHub Actions to automate the actual npm publish', 3);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('863e2e40-511a-58b7-a5a3-4d00f635bb66', 'This is the direct mechanism behind this phase''s Build in Public goal — publishing a first real npm package', 4);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('b314d633-60e1-568f-9ee5-7d09890ed749', 'topic-18-002', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('b314d633-60e1-568f-9ee5-7d09890ed749', 'The format — context (what problem/situation prompted this), decision (what was chosen), consequences (what tradeoffs follow from it)', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('b314d633-60e1-568f-9ee5-7d09890ed749', 'Why ADRs matter more than comments or memory — a decision''s reasoning is often more valuable to a future reader than the decision itself, especially once circumstances have changed and someone''s questioning whether the original choice still makes sense', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('b314d633-60e1-568f-9ee5-7d09890ed749', 'What''s actually worth writing one for — significant, hard-to-reverse decisions (Phase 12''s Exit D caution about documenting pgvector vs Pinecone, Haiku vs GPT-4o is exactly ADR-shaped content), not every minor implementation choice', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('b314d633-60e1-568f-9ee5-7d09890ed749', 'Retroactively writing ADRs for major decisions already made across Phases 01–17 — this phase is a natural point to catch up the backlog, not just start going forward', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('79b01642-a182-5803-8bba-4c9fa0c55c96', 'topic-18-003', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('79b01642-a182-5803-8bba-4c9fa0c55c96', 'Structure — problem statement, proposed approach, alternatives considered, open questions for discussion', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('79b01642-a182-5803-8bba-4c9fa0c55c96', 'When an RFC is worth writing vs when a decision is small enough to just make and document via ADR (2) afterward', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('79b01642-a182-5803-8bba-4c9fa0c55c96', 'The lifecycle — an RFC that reaches consensus typically becomes the basis for one or more ADRs (2) once implemented', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('79b01642-a182-5803-8bba-4c9fa0c55c96', 'Solo-developer context — even without a team to actually comment on an RFC, writing one forces the same rigor of considering alternatives before committing, which matters for the kind of documented decision-making Exit ★3 (Phase 17) already flagged as a portfolio differentiator', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('8d5324d0-943b-5c7c-b3c2-0fab3725df6e', 'topic-18-004', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('8d5324d0-943b-5c7c-b3c2-0fab3725df6e', 'The four key metrics — deployment frequency, lead time for changes, change failure rate, time to restore service', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('8d5324d0-943b-5c7c-b3c2-0fab3725df6e', 'Why these specific four — they''re the metrics DORA''s research found actually correlate with high-performing engineering organizations, not an arbitrary dashboard', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('8d5324d0-943b-5c7c-b3c2-0fab3725df6e', 'Measuring them from your own pipeline — deployment frequency and lead time are readable directly from Phase 06''s GitHub Actions history; change failure rate and time to restore need incident tracking (foreshadows Topic 5 and the incidents/ artifact, Stage 4)', 2);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('94919e53-7cbe-5fed-8947-46e4d7518d98', 'topic-18-005', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('94919e53-7cbe-5fed-8947-46e4d7518d98', 'The blameless framing — analyzing what happened and why the system allowed it, not who made a mistake; the practice exists because blame-oriented reviews make people hide information rather than surface it', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('94919e53-7cbe-5fed-8947-46e4d7518d98', 'Structure — timeline of events, root cause analysis, contributing factors, action items with owners', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('94919e53-7cbe-5fed-8947-46e4d7518d98', 'Using Phase 14/17''s chaos engineering experiments as low-stakes practice material — you already have a real "incident" (something you deliberately broke) to write a genuine post-mortem about', 2);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('94919e53-7cbe-5fed-8947-46e4d7518d98', 'Directly feeds the incidents/ documentation artifact (Stage 4)', 3);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('c1bb5c7c-09ab-54b5-aa35-af532d711625', 'topic-18-006', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('c1bb5c7c-09ab-54b5-aa35-af532d711625', 'Distinguishing technical debt from "code I''d write differently today" — debt implies a deliberate or understood tradeoff, not just hindsight', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('c1bb5c7c-09ab-54b5-aa35-af532d711625', 'A lightweight tracking format — what was deferred, why, and what the cost of leaving it unaddressed actually is', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('c1bb5c7c-09ab-54b5-aa35-af532d711625', 'Directly feeds the TECH_DEBT.md documentation artifact (Stage 4)', 2);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('be0740fd-dc1e-5598-9c96-98eb36c7668e', 'topic-18-007', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('be0740fd-dc1e-5598-9c96-98eb36c7668e', 'Recording estimates against actuals — the only way to actually improve at estimation is comparing predictions to outcomes over time', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('be0740fd-dc1e-5598-9c96-98eb36c7668e', 'Common estimation failure patterns — optimism bias, ignoring integration/testing time, underestimating unfamiliar work', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('be0740fd-dc1e-5598-9c96-98eb36c7668e', 'Using this phase''s own official-vs-actual hour discrepancies (flagged throughout every deep doc in this series) as a live, concrete example of estimation drift worth reflecting on', 2);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('92e09bbc-e887-5b7e-b56b-6656ddb60de3', 'topic-18-008', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('92e09bbc-e887-5b7e-b56b-6656ddb60de3', 'Establishing what a review is actually checking for — correctness, readability, adherence to existing patterns, not just "does it work"', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('92e09bbc-e887-5b7e-b56b-6656ddb60de3', 'Self-review discipline in a solo-developer context — reviewing your own PR with the same rigor you''d apply to someone else''s, before merging', 1);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('34a01d4b-4e6c-5226-8fae-b37b83a80fcf', 'topic-18-009', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('34a01d4b-4e6c-5226-8fae-b37b83a80fcf', 'What a new engineer (or a future version of yourself, returning to the project after months away) actually needs to become productive quickly', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('34a01d4b-4e6c-5226-8fae-b37b83a80fcf', 'Structuring an onboarding path — which docs to read first, which parts of the codebase to explore, what NOT to worry about initially', 1);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('34a01d4b-4e6c-5226-8fae-b37b83a80fcf', 'The direct connection to Stage 4 — this practice is essentially designing the reading order for the documentation artifacts about to be built', 2);
insert into public.topic_groups (id, topic_id, heading, order_index) values ('ffdd1381-3fd7-5c48-96e8-d7133189732c', 'topic-18-010', NULL, 0) on conflict (id) do nothing;
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('ffdd1381-3fd7-5c48-96e8-d7133189732c', 'Numbered, sequential ADR files (0001-use-postgresql.md style naming) — a convention that preserves chronological decision history', 0);
insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('ffdd1381-3fd7-5c48-96e8-d7133189732c', 'Linking between related/superseding ADRs — architecture decisions evolve, and the record should show that evolution rather than silently overwriting old reasoning', 1);
