insert into public.topic_group_bullets (topic_group_id, content, order_index) values ('3f2367eb-f342-532d-9838-d619805d85b7', 'GitHub: a final README pass on ClientSync — this is explicitly called out as the actual artifact recruiters click through to, more than any individual phase''s work.', 3);
