insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0ac6fc35b8', 'stage-01-01', 'Dotfiles Time Capsule', 'easy', 'Build a personal dotfiles repository that configures your entire terminal + editor environment from scratch on a fresh machine. Includes a bootstrap.sh script that installs nvm, sets Node version, configures VS Code settings.json, keybindings, and a curated extension list via "code --install-extension", and sets up SSH key generation with a checklist prompt. Domain: developer tooling / DevOps. Why it’s real: every professional engineer eventually builds this, and you’ll actually reuse it.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-f212b07478', 'stage-01-01', 'New Machine, Ten Minutes', 'medium', 'Extend the dotfiles project into a single idempotent shell script that provisions a brand-new Ubuntu/macOS machine for full-stack development in under 10 minutes — installs Git, nvm, correct Node LTS, global CLI tools (pnpm, gh CLI), configures a global .gitignore, sets up commit signing with SSH keys, and verifies everything with a self-test script that prints pass/fail per component. Why it’s real: this is what onboarding scripts at real companies look like.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-58a1a828ac', 'stage-01-01', 'Team Onboarding Kit', 'hard', 'Package the above into a shareable CLI tool ("npx create-dev-environment") that asks interactive questions (shell preference, editor, GitHub username) and generates a personalized setup repo plus a rendered onboarding README with screenshots. Publish it as an npm package others could install. Why it’s real: this is a genuine open-source-worthy tool — portfolio-impressive because it is meta (a tool that builds tools).');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-e711092111', 'stage-01-02', 'Recipe Card, Zero CSS', 'easy', 'Build a single recipe page using only semantic HTML5 (article, section, figure, time, details) — no CSS at all. It must still be readable, accessible, and make logical sense structurally. Domain: food/lifestyle.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d5576db7e5', 'stage-01-02', 'Accessible Government Notice Board', 'medium', 'Recreate a public notice/announcements page (like a city council site) with correct heading hierarchy, ARIA landmarks, a data table of meeting minutes using proper caption/th-scope, and a downloadable-document list using semantically correct link text (no "click here"). Must pass a Lighthouse accessibility audit at 100. Domain: civic tech.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-345766bdce', 'stage-01-02', 'Structured Résumé That’s Also a Sitemap', 'hard', 'Build a résumé page using HTML microdata / Schema.org (itemscope, itemprop for Person, JobPosting history) so it’s machine-readable by search engines and could populate a rich search result. Validate with Google’s Rich Results Test. Domain: personal branding / SEO engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5d5c147716', 'stage-01-03', 'Print-Perfect Invoice', 'easy', 'Design an invoice that looks correct both on-screen and when printed (@media print), with page-break control, so a small business could literally print/PDF it for clients. Domain: business/finance tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-c6f9f22dc9', 'stage-01-03', 'CSS-Only Data Dashboard Skeleton', 'medium', 'Build a responsive analytics dashboard layout (sidebar, KPI cards, chart placeholders, table) using CSS Grid + Flexbox combined, fully responsive from 320px to 4K, with no JavaScript — including a CSS-only collapsible sidebar using the checkbox hack or :has(). Domain: SaaS/analytics.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4a015e4fa8', 'stage-01-03', 'Theatre Seat Map', 'hard', 'Build a fully CSS-driven interactive seat-selection map (like a cinema/concert booking UI) — hover states, sold/available/selected visual states, using CSS Grid for the seat layout and pure CSS (:checked, sibling selectors) for selection logic, no JS. Domain: ticketing/events. Why it’s real: real booking sites need exactly this pattern; doing it CSS-only proves deep selector mastery.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a0b758f9c8', 'stage-01-04', 'Command-Line Expense Tracker', 'easy', 'A Node.js CLI tool that tracks expenses in a local JSON file, using Maps/Sets for category dedup, robust try/catch with custom Error subclasses, and regex-based input validation. Domain: personal finance. Covers: language core, data structures, error handling, regex. A choose-your-own-adventure engine driven by a JSON story graph, using classes for Room/Player/Item, prototypal inheritance for enemy types, and regex command parsing ("go north", "take sword"). Domain: games/interactive fiction.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bfd8a4e8c8', 'stage-01-04', 'Log File Forensics Tool', 'medium', 'A Node CLI that ingests raw server log files, uses regex to extract structured events, aggregates with Maps, and flags anomalies using custom error classes for malformed lines. Domain: SRE/observability. A mini fluent query builder (db.users.where("age").gt(18).select("name")) using Proxy to intercept property access, Reflect for meta-operations, and generators for lazy result iteration. Domain: backend tooling. Covers: prototypes, classes, iterators/generators, symbols, meta-programming, Proxy, Reflect.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bbbcaa1de1', 'stage-01-04', 'Reactive State Store from Scratch', 'hard', 'Build a tiny Redux/Zustand-like state management library using Proxy for reactivity, Symbols for private internal keys, and a plugin system using meta-programming. Ship as an npm-installable package with tests. Domain: frontend infrastructure. Why it’s real: this is literally how real state libraries are built internally.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-19b12270e5', 'stage-01-04', 'Iterable Deck of Cards / Card Game Engine', 'medium', 'Model a deck of cards as a custom iterable (Symbol.iterator), build a generator-based shuffle/deal system, and implement Blackjack or War fully in the terminal. Domain: games.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-45dabe524a', 'stage-01-04', 'Weather-Aware Commute Planner', 'medium', 'A Node script that calls a real weather API and a geocoding API concurrently using Promise.all, handles partial failures with Promise.allSettled, retries with exponential backoff, and outputs a commute recommendation. Domain: productivity/logistics. Covers: modules, event loop, async, promises, HTTP/APIs.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-c99b0af6e8', 'stage-01-04', 'Rate-Limited API Aggregator', 'hard', 'A tool that fetches data from 3+ public APIs while respecting each one’s rate limit using a hand-written async queue/throttler, with correct microtask/macrotask ordering, and caches results. Domain: data engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0fe23aa058', 'stage-01-04', 'Live Order Status Simulator', 'medium', 'Simulate an e-commerce order pipeline (payment → packing → shipping → delivered) as async stages with realistic delays, custom event emitters, and retry logic on failure. Domain: e-commerce/logistics. A fully vanilla-JS Trello-style kanban board: native Drag and Drop API, localStorage persistence, keyboard accessibility, IntersectionObserver-based lazy rendering. Domain: productivity tools. Covers: DOM, events, forms, storage, browser APIs, observers, workers, binary data.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-c110c4bcd7', 'stage-01-04', 'Client-Side Image Compressor', 'hard', 'Users drag in images, compression/resizing happens client-side via Canvas + binary data (ArrayBuffer/Blob), the compression runs in a Web Worker so the UI never freezes, and results are downloadable — zero backend. Domain: media tooling / privacy-first apps. Why it’s real: this is how tools like Squoosh.app actually work.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-c8361a8e8c', 'stage-01-04', 'Multiplayer Cursor Presence Demo', 'hard', 'Using the BroadcastChannel API, multiple browser tabs of the "same user" see each other’s mouse cursors move in real time — groundwork for the real-time collaboration phase later in the roadmap. Domain: collaborative software.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-3bf081c0ca', 'stage-01-04', 'JS Performance Profiler Playground', 'hard', 'Build a page with 5 intentional performance bugs (memory leaks, unthrottled scroll listeners, layout thrashing, closure leaks, unbounded cache) then a fixed version, documenting before/after with Chrome DevTools Performance & Memory tabs. Domain: web performance engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-b9ee1e3aae', 'stage-01-04', 'Functional Data Pipeline Library', 'hard', 'Build your own functional utility library (pipe, compose, curry, memoize, immutable update helpers) from scratch, fully unit-tested, then use it to process a real CSV dataset end-to-end. Domain: data processing / dev tools. A single documented codebase implementing 8 classic design patterns (Observer, Factory, Singleton, Strategy, Decorator, Command, Module, Facade), each solving a real mini-problem, with tests and a written doc explaining when to use each. Domain: software architecture. Why it’s real: genuinely useful as a portfolio artifact demonstrating architectural maturity.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-017ebaa6dd', 'stage-01-05', 'Type-Safe Config Loader', 'easy', 'A small library that loads and validates environment-variable-based app config, using discriminated unions for different deploy environments and strict TypeScript to make invalid states unrepresentable. Domain: dev tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5a61b1a71a', 'stage-01-05', 'Generic Data Table Library', 'medium', 'Build a fully generic, reusable data-table utility (sort/filter/paginate) typed with generics so it works correctly for any row shape (DataTable<User>, DataTable<Order>) with full autocomplete and compile-time safety on column keys. Domain: frontend infrastructure.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-7d1683367c', 'stage-01-05', 'Typed API Client Generator', 'hard', 'Given an OpenAPI-like JSON schema, generate fully-typed TypeScript API client functions using mapped types, conditional types, and template literal types (e.g. typed route strings), plus a Zod runtime validator layer so types are enforced at compile time and runtime. Domain: API tooling / codegen. Why it’s real: this is essentially what openapi-typescript and tRPC do internally.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-7d0aa34c1e', 'stage-01-06', 'Library Fine Calculator, In Pure SQL', 'easy', 'Design a normalized schema (Books, Members, Loans) and write pure SQL queries (joins, aggregates) to calculate overdue fines, most-borrowed books, and member activity reports. Domain: civic/library systems.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d527b9c209', 'stage-01-06', 'E-commerce Analytics Query Pack', 'medium', 'Given a realistic multi-table e-commerce schema, write 15 real analytical queries a business would actually ask for: cohort retention, top products by margin, customers at risk of churn via window functions/RFM logic. Domain: e-commerce analytics.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-11322f4b03', 'stage-01-06', 'Query Optimization Challenge', 'hard', 'Given a deliberately slow, badly-indexed schema and slow queries, rewrite/optimize each (correct indexes, restructuring subqueries into joins/CTEs) and document before/after EXPLAIN plans and execution time. Domain: database performance.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9231b73590', 'stage-01-07', 'Open-Source-Style Contribution Simulation', 'easy', 'Take any earlier stage project and simulate a full open-source contribution workflow solo: feature branch, Conventional Commits, a PR description template, a CHANGELOG.md generated from commit history. Domain: OSS practice.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-30d130d43f', 'stage-01-07', 'Team Code Quality Gate', 'medium', 'Configure a shared ESLint + Prettier config as its own publishable npm package (@yourname/eslint-config) that multiple projects could extend, including at least one custom lint rule for a project-specific convention. Domain: engineering tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a33e21a1ac', 'stage-01-07', 'Git Archaeology Report', 'hard', 'Pick a real open-source repo, use git log, git blame, and git bisect to trace the history of a specific bug fix or feature through its evolution, and write a technical report, including reconstructing a rebase/merge scenario locally. Domain: software forensics.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a903fc4e0d', 'stage-02-01', 'Habit Tracker with Streaks', 'easy', 'A single-page habit tracker using function components, hooks (useState/useEffect), controlled forms, and localStorage persistence. Domain: personal wellness.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-83d1bfdfcb', 'stage-02-01', 'Multi-Step Job Application Wizard', 'medium', 'A polished multi-step form (resume upload, work history, review) using component composition patterns (compound components), error boundaries per step, and portals for a confirmation modal. Domain: HR tech / recruiting.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-faa6c7322d', 'stage-02-01', 'Concurrent Rendering Image Gallery', 'hard', 'A masonry image gallery that uses Suspense for image loading, startTransition for non-blocking filter/search updates, and an error boundary fallback per image tile. Includes a deliberate slow-network simulation to demonstrate concurrent rendering benefits visibly. Domain: media/photography platforms.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bdb28d25dd', 'stage-02-02', 'Local Business Directory', 'easy', 'A statically generated directory of local businesses (seeded JSON/CSV data) using file-based routing, dynamic segments, and generateStaticParams. Domain: local commerce.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-64a53f0513', 'stage-02-02', 'Newsroom CMS Front-End', 'medium', 'A news site pulling articles from a headless data source, mixing Server and Client Components correctly (interactive comment section as client, article body as server), using Server Actions for comment submission, and ISR for article freshness. Domain: media/publishing.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-3b19110b7a', 'stage-02-02', 'Multi-Tenant SaaS Marketing Site \+ Dashboard Shell', 'hard', 'A realistic SaaS product shell: public marketing pages (fully static, optimized metadata/SEO), an authenticated dashboard area using middleware for route protection, Route Handlers acting as a lightweight BFF, and a caching strategy documented per route (static / ISR / dynamic). Domain: B2B SaaS.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0f9067fba7', 'stage-02-03', 'Photo App with Modal Routes', 'medium', 'An Instagram-style photo grid where clicking a photo opens it in a modal (intercepting routes) but a direct URL visit renders the full page — correct back/forward browser behavior included. Domain: social/media. An admin panel using parallel routes to simultaneously render independent panels (e.g., analytics + recent activity + alerts) that load and error independently, plus route groups to separate authenticated vs public layouts. Domain: internal tools/admin.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0e3b18f604', 'stage-02-03', 'Selective Cache-Busting Content Platform', 'hard', 'A content platform where editors can trigger revalidatePath for a single article or revalidateTag for an entire content category, with a small internal "publish" UI that demonstrates surgical cache invalidation and a notFound() fallback for unpublished/deleted content. Domain: publishing/CMS.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a17d62ece4', 'stage-02-04', 'Persistent Shopping Cart', 'easy', 'A shopping cart that survives page reloads and tab closes using browser storage with a clean abstraction layer (not raw localStorage calls scattered everywhere). Domain: e-commerce.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-c3f632cd7a', 'stage-02-04', 'Non-Next.js SPA Router Migration Demo', 'medium', 'Take a small existing feature and implement it twice: once with Next.js file-based routing, once as a standalone SPA using React Router v6, documenting the API and mental-model differences (loaders, nested routes, navigation guards). Domain: educational/comparative engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-e559aa29aa', 'stage-02-05', 'Server-to-Client Hydration Demo Dashboard', 'medium', 'A dashboard that prefetches data on the server, dehydrates it, and hydrates a client-side query cache (HydrationBoundary) so the first paint is instant and subsequent interactions are fully client-cached. Domain: analytics/SaaS. Build the client-side data-fetching foundation (before the full offline sync work happens later in the roadmap) for a notes app: a documented conceptual comparison of fetch-based, SWR-style, and query-cache-based approaches, implemented as 3 small parallel prototypes of the same feature. Domain: productivity tools.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9f2d202504', 'stage-02-06', 'Portfolio Site, Two Ways', 'easy', 'Deploy the same static portfolio site to both Vercel and GitHub Pages, documenting configuration differences (base path, environment variables, build commands). Domain: personal branding.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5852aa1e22', 'stage-02-06', 'Edge-Personalized Landing Page', 'medium', 'A marketing landing page that uses a Vercel Edge Function to personalize content based on geolocation/headers (e.g., currency or language hint) with near-zero latency, benchmarked against a non-edge equivalent. Domain: marketing/growth. A photography/blog site using blur placeholders (plaiceholder) generated at build time, deployed on Vercel with documented Core Web Vitals before/after optimization. Domain: media/publishing.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-67e8561bd7', 'stage-03-01', 'Themeable Component Sandbox', 'easy', 'A small component gallery (buttons, cards, alerts) fully re-themeable at runtime via CSS Custom Properties, with a light/dark and a "high contrast" theme. Domain: design systems.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0931fab5df', 'stage-03-01', 'Legacy CSS Layering Refactor', 'medium', 'Take a deliberately messy, specificity-war-ridden stylesheet (provided or self-authored) and refactor it using @layer (reset, base, components, utilities, overrides) so cascade order becomes predictable and documented. Domain: engineering/refactoring. A small component library authored with strict BEM naming and CSS Modules for scoping, published as a usable style guide page (a mini Storybook-style catalog page built by hand) with documented naming conventions. Domain: design systems.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-cc3483d7a0', 'stage-03-02', 'Pricing Page, Pixel-Faithful', 'easy', 'Recreate a real SaaS pricing page layout using only Tailwind utilities, responsive at 3 breakpoints. Domain: SaaS marketing.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-c81eab41c2', 'stage-03-02', 'Custom Tailwind Design Token Theme', 'medium', 'Extend Tailwind’s config with a fully custom design token set (brand colors, spacing scale, typography scale) for a fictional client brand, then rebuild 5 components using only the custom tokens (no arbitrary values). Domain: agency/freelance work.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-b950a9961d', 'stage-03-02', 'Dashboard UI Kit, Utility-First', 'hard', 'A full admin dashboard UI (nav, cards, tables, forms, charts placeholders) built at production polish level using only Tailwind, with a documented approach for avoiding class-name bloat (extracted components, not @apply-everything). Domain: SaaS/enterprise tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-b0d4beb49e', 'stage-03-03', 'Conditional Class Playground', 'easy', 'A small set of components (badge, alert, button) with multiple visual states driven entirely by clsx-based conditional logic. Domain: design systems.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-dc88653dc5', 'stage-03-03', 'Merge-Safe Themeable Button', 'medium', 'A Button component that accepts a className override prop and correctly merges/overrides Tailwind classes using tailwind-merge (no visual bugs from conflicting utilities), tested against 10 tricky override cases.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9bdaf4c3f6', 'stage-03-03', 'CVA-Powered Component Library Core', 'hard', 'Build 6 components (Button, Badge, Alert, Input, Card, Tag) using Class Variance Authority for variant/size/state management, with full TypeScript prop inference from the CVA config. Domain: design systems / component libraries.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a7bb688341', 'stage-03-04', 'Accessible Custom Select', 'medium', 'Build a fully accessible custom dropdown/select using Radix UI primitives (keyboard nav, ARIA, focus trapping handled correctly) styled to match a custom brand, not default Radix look. Domain: accessibility engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-8d7ab1f0a0', 'stage-03-04', 'shadcn/ui-Based Admin Starter', 'medium', 'Assemble a small admin panel using shadcn/ui components (customized, not default theme) integrated with next-themes for dark mode, including a documented decision on which components were customized and why. Domain: SaaS/internal tools.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d494fc142a', 'stage-03-04', 'Multi-Brand Theming Demo', 'hard', 'One codebase that can render 3 completely different visual brands (different logos, colors, radii, fonts) at runtime by swapping a theme provider — combining Radix primitives, next-themes, and CSS variables. Domain: white-label SaaS / multi-tenant products.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-efa6c5e1a2', 'stage-03-05', 'Schema-Driven Dynamic Form Builder', 'hard', 'A form renderer that takes a Zod schema as input and dynamically renders the correct react-hook-form-powered fields (text, number, select, date) with validation derived entirely from the schema — no hardcoded field JSX per form. Domain: internal tooling / low-code platforms.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d1c0cb220c', 'stage-03-06', 'Event Countdown & Scheduling Widget', 'easy', 'A small widget showing "time until" and formatted relative dates using date-fns, correctly handling timezones. Domain: events/scheduling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-f5dadd6772', 'stage-03-06', 'Deduplicating Data Import Tool', 'medium', 'A CSV import utility that uses lodash-es for deep merging/grouping/deduplication logic on messy imported records, plus nanoid for generating stable client-side temp IDs before server save. Domain: data tooling/back-office.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-14e4b858d6', 'stage-03-07', 'Zero-Runtime Styled Component Library', 'hard', 'Rebuild 4 components from Stage 3/4 using vanilla-extract instead of Tailwind/CVA, compare bundle output and runtime cost, and write a comparison report (DX, performance, type safety) between utility-first and zero-runtime CSS-in-TS approaches. Domain: performance engineering / design systems.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-afba24719c', 'stage-04-01', 'Context Meltdown Demo', 'easy', 'Deliberately build a deeply nested component tree relying only on Context for frequently-changing state, profile the re-render cascade with React DevTools, then document exactly where and why it breaks down. Domain: educational / performance engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-11ed1f7454', 'stage-04-01', 'Multi-Store Zustand Task Manager', 'medium', 'A task/project manager using multiple focused Zustand stores (not one giant store), with selectors to prevent unnecessary re-renders, persisted to localStorage via Zustand middleware. Domain: productivity tools.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9fc329d2f1', 'stage-04-01', 'Undo/Redo Design Tool State Engine', 'hard', 'The state layer for a simple design/whiteboard tool (shapes, position, color) using Zustand with a custom undo/redo middleware (command history), demonstrating advanced store composition. Domain: creative tools.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-ae747e841a', 'stage-04-02', 'Paginated \+ Infinite Product Catalog', 'medium', 'A product listing using TanStack Query with both classic pagination and infinite scroll variants, optimistic updates for "add to wishlist," and proper cache invalidation on mutation. Domain: e-commerce. A full-stack todo app where the client calls the backend via tRPC with zero manual type duplication — renaming a backend field breaks the frontend build immediately, proving end-to-end type safety. Domain: full-stack tooling demonstration.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-c9a5687a44', 'stage-04-02', 'Real-Time-Feeling Dashboard via Query Polling \+ Optimistic UI', 'hard', 'A support-ticket dashboard where status changes feel instant via optimistic updates, with automatic rollback on server rejection, background refetching, and stale-time tuning documented per query type. Domain: customer support / SaaS.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-b22124f4f6', 'stage-04-03', 'Traffic Light & Turnstile State Machines', 'easy', 'Two classic finite state machines implemented in XState v5 to build fluency with the model before tackling something real. Domain: educational / systems modeling. A checkout flow (cart → shipping → payment → confirm) modeled explicitly as a state machine with guards (e.g., can’t proceed to payment without valid address) and visualized in Stately Studio, catching impossible states that a boolean-flag approach would allow. Domain: e-commerce.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d5af2281a2', 'stage-04-03', 'Video Upload Pipeline State Machine', 'hard', 'Model a video upload/processing pipeline (idle → uploading → processing → ready/failed, with retry and cancel) as a state machine with parallel states for "upload progress" and "processing progress" tracked independently. Domain: media platforms.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5ad8235004', 'stage-04-04', 'Route-Level Code Splitting Audit', 'medium', 'Take a multi-page app and apply React.lazy + Suspense at route boundaries, measuring bundle size and load time before/after with real numbers. Domain: performance engineering. A dashboard of independent widgets where each widget has its own Suspense boundary and its own react-error-boundary fallback, so one failing widget (simulated) never crashes the whole page — with a portal-based "widget detail" modal on click.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-ae38447f3c', 'stage-04-05', 'Scroll-Triggered Storytelling Page', 'medium', 'A scrollytelling landing page (like a data-journalism piece) where sections animate/reveal using Intersection Observer as the user scrolls. Domain: media/journalism.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-13f50d7945', 'stage-04-05', 'Responsive Chart Container System', 'medium', 'A set of chart containers that resize their internal SVG/canvas rendering correctly using ResizeObserver, avoiding the common bug of charts not resizing on sidebar collapse. Domain: analytics/dashboards.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bd252eafe6', 'stage-04-06', '100,000-Row Virtualized Table', 'hard', 'A data table that renders 100,000 rows smoothly using TanStack Virtual, with sorting/filtering that stays performant, profiled and documented with React DevTools Profiler flame charts before/after virtualization. Domain: enterprise data tools / fintech dashboards.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-47d3eb21a1', 'stage-04-06', 'Chat App Virtualized Message List', 'hard', 'A chat interface with a virtualized, variable-height message list (some messages have images, some are one line) that maintains correct scroll position when new messages arrive at the bottom. Domain: messaging/social.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-cb2987aeb4', 'stage-05-01', 'Raw Node HTTP File Server', 'easy', 'A file server built with zero frameworks using only the Node.js http module — routing, static file serving, and JSON responses hand-rolled — to understand what Express actually abstracts away. Domain: systems/infra fundamentals.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0cc28bbe59', 'stage-05-01', 'Bookstore REST API with Express', 'medium', 'A clean Express-based REST API (CRUD for books, authors, categories) with proper middleware layering, route organization, and centralized error handling. Domain: retail/inventory.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-821efab919', 'stage-05-01', 'Pluggable Middleware Pipeline Framework', 'hard', 'Build a tiny Express-compatible middleware pipeline from scratch (your own mini-framework mimicking app.use()/next()) to fully understand the middleware pattern, then reimplement one real feature (logging) both in your framework and in real Express side-by-side. Domain: framework/systems engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-532bd67129', 'stage-05-02', 'Public API with Rate Limiting & CORS Policy', 'medium', 'A small public-facing API (e.g., a quotes/jokes API) with a documented CORS policy, express-rate-limit tuned per endpoint tier (free vs authenticated), and async error handling via express-async-errors so no unhandled rejection crashes the server. Domain: public API products. A comment/review submission API where all HTML input is sanitized server-side with DOMPurify (server-side variant) before storage, with a deliberate XSS payload test suite proving the sanitization actually works. Domain: content platforms / trust & safety.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9bbc14121e', 'stage-05-02', 'Hardened Production API Checklist Implementation', 'hard', 'Take an existing API and harden it end-to-end: Helmet.js security headers, response compression, tuned CORS, rate limiting by IP and by API key, and a written security checklist with before/after header comparison (via curl -I). Domain: security engineering / SRE.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4107674be2', 'stage-05-03', 'Full Supertest Suite for the Bookstore API', 'medium', 'A comprehensive Supertest test suite for the Stage 1 Bookstore API covering happy paths, validation failures, auth-protected routes, and edge cases (empty body, malformed JSON, huge payloads). Domain: QA engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-11352f9681', 'stage-05-04', 'Normalized Multi-Tenant Schema Design', 'medium', 'Design and implement (via Prisma migrations) a normalized PostgreSQL schema for a multi-tenant SaaS (organizations, users, projects, roles) with correct foreign keys and cascade rules. Domain: B2B SaaS.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-f9ede5ef5f', 'stage-05-04', 'Serverless Postgres Comparison Project', 'medium', 'Deploy the same schema/API to both Supabase and Neon, documenting connection pooling differences, cold-start behavior, and pricing/scaling tradeoffs from hands-on testing. Domain: infrastructure decision-making.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-6fc86ab4fa', 'stage-05-04', 'Slow Query Detective Agency', 'hard', 'Given a seeded database with 1M+ rows and a set of deliberately slow endpoints, use EXPLAIN ANALYZE to diagnose each bottleneck, apply the correct fix (index, query restructure, N+1 fix via Prisma include), and document before/after query plans and timings. Domain: database performance engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-01ad9a6a27', 'stage-05-05', 'From-Scratch Password Auth', 'medium', 'A signup/login system built without an auth-as-a-service library: bcrypt for hashing, JWT access tokens, httpOnly refresh-token cookies with SameSite=Lax, and a documented token-rotation strategy. Domain: security engineering / any product needing custom auth. A small service that receives webhooks (simulate a payment provider) and verifies HMAC-SHA256 signatures before trusting the payload, including a deliberate test proving a tampered payload is rejected. Domain: payments/fintech infrastructure.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-22979c10c9', 'stage-05-05', 'jose-Based Multi-Audience Token System', 'hard', 'A token system using the jose library supporting multiple audiences (web client, mobile client, internal service-to-service) with different expiry/claims per audience, and a key-rotation mechanism (JWKS-style) so old tokens gracefully expire during a key rotation. Domain: platform/identity engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-10c2a602f7', 'stage-06-01', 'Fully-Tested Utility Library', 'easy', 'Take a utility library from an earlier phase and bring it to 100% meaningful coverage with Vitest, including edge cases, with a coverage report published via Codecov. Domain: dev tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-dafab4db17', 'stage-06-01', 'Mocked API Component Test Suite', 'medium', 'A React component suite (forms, data tables) tested with React Testing Library + @testing-library/user-event for realistic interactions, and MSW to mock network requests so tests never hit a real backend. Domain: frontend QA.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4aa10842e1', 'stage-06-01', 'Regression-Proof Checkout Flow Tests', 'hard', 'A full test suite for a multi-step checkout component (from Phase 4’s state machine work) covering every state transition, error path, and MSW-simulated payment failure, with coverage thresholds enforced in CI and tracked over time in Codecov. Domain: e-commerce QA engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-02e68e5be7', 'stage-06-02', 'Critical User Journey E2E Suite', 'medium', 'Playwright tests covering the 3 most critical user journeys of any earlier full-stack project (signup → login → core action), running against a real (test) database. Domain: QA engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a1d5b8a325', 'stage-06-02', 'Cross-Browser Visual Regression Suite', 'hard', 'Playwright tests that run across Chromium, Firefox, and WebKit, include visual snapshot comparisons for key pages, and are wired to fail CI on unexpected visual diffs. Domain: QA / design systems.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-f36c4a5c29', 'stage-06-03', 'Matrix-Tested Cross-Version CI', 'hard', 'A CI workflow using a build matrix to test a library across multiple Node.js versions and operating systems simultaneously, with a status badge reflecting real pass/fail state. Domain: open-source maintenance / library engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9b7305fd9e', 'stage-06-04', 'Multi-Stage Dockerized Full-Stack App', 'medium', 'Dockerize a full-stack app (Phase 5 backend + a frontend build) using multi-stage builds to keep the final image small, with a documented image-size before/after comparison. Domain: DevOps.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-2edad2fcb7', 'stage-06-04', 'Local Dev Environment via Docker Compose', 'medium', 'A docker-compose.yml that spins up the app, a Postgres database, and Redis together with one command, including healthchecks and proper service dependency ordering. Domain: developer experience / infra.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-76abd515b3', 'stage-06-04', 'Automated Image Publishing Pipeline', 'hard', 'A GitHub Actions workflow using docker/build-push-action to build and publish a versioned, tagged image to GitHub Container Registry on every merge to main, including a documented rollback procedure using a previous tag. Domain: DevOps / release engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-7f8d301fe2', 'stage-06-05', 'HTTP/2 Performance Verification', 'medium', 'Deploy the same app behind both HTTP/1.1 and HTTP/2 configurations (or verify Render’s default) and document real measured differences in multiplexed asset loading via browser waterfall charts. Domain: web performance / infra.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-2ffb973b83', 'stage-06b-01', 'Cross-Platform Habit Tracker', 'easy', 'Rebuild Phase 2’s habit tracker as a React Native + Expo app, documenting layout differences (Flexbox defaults differ from web) and navigation using React Navigation (stack + tabs). Domain: personal wellness / mobile.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-3c70935f1b', 'stage-06b-01', 'Recipe Browser with Deep Linking', 'medium', 'A recipe browsing app with nested navigation (stack inside tabs), deep linking support (opening a specific recipe from a shared URL), and platform-aware layout adjustments for notches/safe areas. Domain: lifestyle/food.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-393653c010', 'stage-06b-01', 'EAS-Built Multi-Environment App', 'hard', 'An app configured with separate dev/staging/production build profiles via EAS Build, each pointing to a different API environment, with a documented build-and-distribute workflow for internal testers. Domain: mobile release engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-63f8c43de1', 'stage-06b-02', 'Offline-First Grocery List', 'medium', 'A grocery list app that works fully offline using AsyncStorage, queues changes made offline, and syncs to a backend when connectivity returns, with conflict resolution for simultaneous edits. Domain: productivity / offline-first apps. A mobile login flow storing tokens in expo-secure-store (not AsyncStorage) with biometric-gated access to sensitive actions, and a documented threat-model comparison of AsyncStorage vs. secure-store. Domain: mobile security.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-09f416f7cc', 'stage-06b-03', 'Receipt Scanner Utility', 'medium', 'An app using the camera API to photograph receipts, request the correct permissions gracefully (with a fallback UI if denied), and save images locally. Domain: personal finance / utility apps. A reminders app sending real push notifications (via Expo push service) with platform-specific permission flows for iOS vs Android documented and handled distinctly. Domain: productivity.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0f0336fcc9', 'stage-06b-04', '10,000-Item Contact List', 'hard', 'A contacts app rendering a very large list using FlatList performance best practices (getItemLayout, windowing tuning) profiled before/after optimization. Domain: productivity / performance engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-1d1a45302c', 'stage-06b-04', 'Hermes vs JSC Benchmark Report', 'medium', 'Build a CPU-intensive screen (e.g., client-side image filtering) and benchmark its performance under the Hermes engine vs JSC, documenting startup time and runtime differences with real numbers. Domain: mobile performance engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-033954bde9', 'stage-06b-05', 'Zero-Downtime OTA Update Demo', 'hard', 'Ship a bug fix to a live-installed app using EAS Update (over-the-air) without requiring users to redownload from the store, with a before/after demonstration and a documented rollback plan if the OTA update itself is broken. Domain: mobile release engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-66025b7e9e', 'stage-07-01', 'Zero-GUI API Debugging Toolkit', 'easy', 'A personal collection of curl scripts (with a Makefile or shell aliases) that fully exercise every endpoint of an earlier project’s API, usable by teammates with no GUI tool installed. Domain: developer tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bf125db43a', 'stage-07-01', 'Shared Postman Collection with Environments', 'medium', 'A Postman collection for a full-stack project with dev/staging/prod environments, pre-request scripts for auth token refresh, and automated test assertions per request, exported and version-controlled alongside the code. Domain: API QA/tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-02ac546a28', 'stage-07-02', 'Auto-Generated OpenAPI Docs Site', 'medium', 'Write a complete OpenAPI 3.0 spec for an earlier project’s API by hand, render it with Swagger UI, and verify every documented example actually matches real API behavior (no doc drift). Domain: API developer experience.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-3599f18813', 'stage-07-02', 'Architecture Diagrams as Code', 'medium', 'Document a full-stack project’s system architecture (request flow, database relationships, deployment topology) entirely using Mermaid diagrams embedded in markdown, version-controlled alongside the code. Domain: technical documentation / architecture.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-cceee6eba6', 'stage-07-02', 'Public-Facing Developer Portal', 'hard', 'A polished, standalone documentation site for a public API combining OpenAPI-generated Swagger UI, hand-written getting-started guides, and Mermaid sequence diagrams showing common integration flows (e.g., OAuth handshake). Domain: developer relations / API products.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bbb8fd34c7', 'stage-07-03', 'Blog GraphQL API', 'medium', 'A GraphQL API (posts, authors, comments) with proper resolver structure, demonstrating the N+1 problem occurring naturally, then fixed with DataLoader-style batching. Domain: publishing/content. Implement the identical feature (a nested product/reviews/author data fetch) as both a REST endpoint and a GraphQL query, measuring over-fetching/under-fetching and request-count differences with real network data, and write a decision-framework document for when to choose each. Domain: API architecture.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9fab8774ef', 'stage-07-03', 'Federated Multi-Service GraphQL Gateway', 'hard', 'Split a schema across 2 independent services (e.g., Users service and Orders service) and compose them behind a single gateway, demonstrating schema federation concepts. Domain: microservices/API architecture.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0a679401e2', 'stage-08-01', 'Pattern Recognition Drill Set', 'easy', 'Solve and document 8 problems each for Two Pointers and Sliding Window (16 total) from a mix of easy/medium difficulty, with a personal "pattern recognition cheat sheet" written afterward describing the signal phrases that indicate each pattern.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a071d8d61a', 'stage-08-01', 'Binary Search Beyond Sorted Arrays', 'medium', 'Solve 6 problems that use binary search in non-obvious ways (search on answer space, rotated arrays, first/last occurrence), documenting the invariant maintained in each solution.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-be211f07e9', 'stage-08-01', 'Stock Trading Simulator via Kadane’s Variants', 'medium', 'Solve the full family of "best time to buy/sell stock" problems (I through IV) building from basic Kadane’s to the DP-augmented versions with transaction limits, with a written explanation of how each variant extends the last.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-6eb5b3c165', 'stage-08-03', 'Expression Evaluator', 'medium', 'Build a calculator that evaluates infix mathematical expressions with correct operator precedence and parentheses using a stack-based approach (shunting-yard or recursive descent), tested against 20 hand-crafted tricky expressions. Solve 6 monotonic stack problems (next greater element family, daily temperatures, largest rectangle in histogram), with a written template for recognizing when a monotonic stack applies.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-71d4d8020e', 'stage-08-04', 'Maze & Graph Explorer Toolkit', 'medium', 'Solve a set of grid-based BFS/DFS problems (number of islands, rotting oranges, word ladder) with a shared, reusable grid-traversal helper function. Implement every classic tree traversal (in/pre/post-order, level-order) both recursively and iteratively, plus tree construction from traversal pairs, serialization/deserialization, and LCA — packaged as a small reusable tree utility module with tests.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5f1358ea18', 'stage-08-04', 'Cycle Detection Across Data Structures', 'hard', 'Implement Floyd’s Cycle Detection (tortoise and hare) applied to 3 different contexts: a linked list, an implicit "functional graph" (array where value = next index), and duplicate-number detection — documenting the shared mathematical insight across all three.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bc49d2642c', 'stage-08-06', '1D DP Warm-Up Set', 'medium', 'Solve 6 classic 1D DP problems (climbing stairs, house robber, coin change, longest increasing subsequence) implementing each with both memoization (top-down) and tabulation (bottom-up), comparing code clarity and space usage. Solve 8 2D DP problems (unique paths, edit distance, longest common subsequence, 0/1 knapsack) with a written "DP state design" note for each: what does dp[i][j] represent, and why.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9f5c8669e8', 'stage-08-06', 'DP Optimization Showcase', 'hard', 'Take 3 of your 2D DP solutions and optimize their space complexity from O(n²) to O(n) using rolling arrays, documenting the transformation reasoning and benchmarking actual memory usage before/after on large inputs.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d3b9b2c6ed', 'stage-08-07', 'System Design Interview Playbook', 'hard', 'Produce full written system design solutions (with diagrams) for 4 classic prompts (URL shortener, rate limiter, news feed, chat system) following a consistent framework: requirements clarification, capacity estimation, high-level design, deep dive, bottleneck/scaling discussion. Domain: systems design / interview prep.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-17fb7a5749', 'stage-09-01', 'Cache-Aside API Layer', 'medium', 'Add Redis caching (via ioredis) to an earlier project’s read-heavy endpoints using the cache-aside pattern, with a documented cache-hit-rate measurement before/after and a sensible TTL/invalidation strategy per resource type. Domain: performance engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-04e908181b', 'stage-09-01', 'Connection Pool Exhaustion Lab', 'hard', 'Deliberately misconfigure PgBouncer to cause connection pool exhaustion under simulated load, observe and document the failure mode, then correctly configure pooling (transaction vs session mode) and prove the fix under the same load test. Domain: database infrastructure / SRE.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-f95cb6533d', 'stage-09-02', 'Serverless-Friendly Rate Limiter', 'medium', 'Implement API rate limiting using Upstash (Redis-over-HTTP, works from serverless/edge functions) with @upstash/ratelimit, comparing sliding-window vs fixed-window algorithms with real traffic simulation. Domain: API infrastructure.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-43bd57e2d4', 'stage-09-03', 'Branded Transactional Email System', 'medium', 'Build a full transactional email flow (welcome, password reset, receipt) using React Email for templates (so emails are built with real component reuse) and Resend for delivery, tested across multiple email clients for rendering consistency. Domain: product/growth engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-fa7b7c4ccd', 'stage-09-04', 'Subscription Billing System', 'hard', 'A full subscription billing integration with Razorpay: plan selection, checkout, webhook-based subscription-status sync (active/past-due/cancelled) back into your own database, and a customer-facing billing history page. Domain: fintech / SaaS billing. A one-time purchase flow (e.g., for a digital product) with Razorpay, including a documented refund process both via API and via the dashboard, and idempotent webhook handling so a duplicate webhook delivery never double-credits an order. Domain: e-commerce/fintech.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-6b567a3205', 'stage-10-01', 'Request-Traceable Logging System', 'medium', 'Add structured logging (pino) to an earlier API with a request ID propagated via AsyncLocalStorage through every log line of a request’s lifecycle, so any single request’s full log trail can be grepped by ID. Domain: observability / SRE.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-2934c8d50b', 'stage-10-01', 'Dual-Transport Logging Setup', 'medium', 'Configure winston with two transports (console for dev, file/JSON for production) and demonstrate log-level filtering (debug locally, warn+ in production) driven by environment config. Domain: observability.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-32a22c76a0', 'stage-10-02', 'Production Error Triage Dashboard', 'medium', 'Integrate Sentry into a full-stack app (both frontend and backend), including source maps for readable stack traces, user context attachment, and custom error grouping/tagging for a specific error-prone feature. Domain: SRE / observability. Set up UptimeRobot monitors for a deployed project’s critical endpoints and build a small public status page that reflects real uptime data. Domain: SRE / product trust.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5eb751c925', 'stage-10-03', 'Unified Observability Stack Comparison', 'hard', 'Ship the same application’s logs to 3 different platforms in parallel (e.g., Better Stack, Axiom, and Grafana Cloud + Loki) and write a hands-on comparison covering query experience, retention/pricing, and alerting capability. Domain: infrastructure decision-making.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-1ae9ca0711', 'stage-10-03', 'CloudWatch-Based AWS Monitoring Setup', 'medium', 'For any component deployed with AWS involvement, configure CloudWatch log groups, metric filters, and a basic alarm (e.g., error-rate spike) that would page a real on-call engineer. Domain: AWS/SRE.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5fd410a1fa', 'stage-10-05', 'Feature-Flagged A/B Pricing Experiment', 'hard', 'Run a real (or realistic simulated) A/B test on a pricing page using PostHog feature flags to split traffic, tracked through to a conversion event, with statistical significance discussed in a written results report. Domain: growth engineering / experimentation. Use funnel analysis and session recordings to identify the exact step where users abandon an onboarding flow, propose and implement a fix, then re-measure the funnel to validate improvement. Domain: product/UX engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-59a3c51326', 'stage-11-01', 'Peer-to-Peer Video Chat', 'hard', 'A 1:1 video call app using WebRTC with a signaling server (over WebSockets), including screen-share support and graceful handling of connection failures/ICE negotiation issues. Domain: communication tools.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-97c421fae3', 'stage-11-02', 'Materialized View Reporting Dashboard', 'medium', 'Build a reporting dashboard backed by materialized views for expensive aggregate queries (e.g., daily sales rollups), with a documented refresh strategy (scheduled vs on-demand) and a before/after query-time comparison vs. querying raw tables directly.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4a3c470b3f', 'stage-11-03', 'MVCC Behavior Demonstration Lab', 'hard', 'A hands-on demo (two concurrent psql sessions) that reproduces and documents MVCC behavior: a long-running transaction not seeing another session’s committed changes, then explains what VACUUM is cleaning up afterward, with pg_stat_activity screenshots showing the live transaction state.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-ecef5f690a', 'stage-11-03', 'Read Replica Lag Simulation', 'hard', 'Set up a primary + read replica PostgreSQL setup (locally via Docker), write to primary, read from replica, and deliberately induce and measure replication lag under write load, documenting a strategy for handling read-after-write consistency issues in application code.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5e2e6605fc', 'stage-11-04', 'Instant Search-As-You-Type with Meilisearch', 'medium', 'A product catalog with typo-tolerant, sub-50ms instant search using Meilisearch, including faceted filtering (category, price range) synced from the primary database. Domain: e-commerce.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-28f6055192', 'stage-11-04', 'Search Engine Bake-Off', 'hard', 'Index the identical dataset (e.g., 50k products) into Postgres full-text search, Typesense, and Elasticsearch, then benchmark query latency, relevance quality, and typo tolerance across all three with a written recommendation for different use-case scales. Domain: search infrastructure / platform engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-59901d6bd6', 'stage-12-01', 'Multi-Provider Prompt Playground', 'easy', 'A small internal tool that sends the same prompt to both the OpenAI API (GPT-4o) and the Anthropic API side-by-side, displaying responses, latency, and token usage for comparison. Domain: AI tooling / evaluation.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-3a2bebd59a', 'stage-12-01', 'Structured Support-Ticket Classifier', 'medium', 'A backend service that classifies incoming support tickets (category, urgency, sentiment) using an LLM API call, with proper error handling for API failures/timeouts and a fallback rule-based classifier if the API is unavailable. Domain: customer support automation.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-704aca4d00', 'stage-12-02', 'Semantic Duplicate Detector', 'medium', 'A tool that embeds a set of support tickets or forum posts (text-embedding-3-small) and finds semantic duplicates/near-duplicates using cosine similarity in pgvector, catching duplicates that keyword search would miss. Domain: content moderation / support tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a55130736c', 'stage-12-02', 'HNSW vs IVFFlat Benchmark', 'hard', 'Index the same 100k-vector embedding set with both IVFFlat and HNSW in pgvector, benchmarking query latency and recall accuracy tradeoffs at different index parameters, with a written recommendation document. Domain: vector search infrastructure.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-6c788a17b8', 'stage-12-03', 'Multi-Document Research Assistant with Chunking Strategy Comparison', 'hard', 'A RAG pipeline over a corpus of long-form documents (e.g., legal or research PDFs) that compares 3 different chunking strategies (fixed-size, semantic, sliding-window-with-overlap) on retrieval quality for the same question set, with a written evaluation report. Domain: legal-tech / research tooling.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-dff6ea5130', 'stage-12-04', 'Streaming AI Chat UI', 'medium', 'A chat interface using the Vercel AI SDK with true token-by-token streaming responses, stop/regenerate controls, and conversation history persistence. Domain: AI product UX. A system where users submit a batch of documents for AI summarization; jobs are queued in BullMQ (not processed synchronously in the request), with a Bull Board dashboard for monitoring job status, retries, and failures. Domain: AI infrastructure / batch processing.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-462bd47886', 'stage-12-05', 'Cost-Optimized Multi-Tier Support Bot', 'medium', 'A support bot that routes simple questions to a smaller/cheaper Claude model tier and escalates complex questions to a larger tier, with prompt caching applied to the large, static system prompt/knowledge base portion to cut repeated-request cost. Domain: AI cost engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-7057dafb9b', 'stage-12-06', 'Receipt-to-Structured-Data Extractor', 'medium', 'A tool that takes a photo/text of a receipt and uses tool calling to extract guaranteed-valid structured JSON (line items, totals, tax) validated against a schema, with a test suite of malformed/tricky receipts. Domain: fintech / expense automation.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-f65619107b', 'stage-12-06', 'Cost-Aware Multi-Model Router', 'hard', 'A routing layer that sends each incoming request to the cheapest model capable of handling it correctly (classified by a lightweight pre-check), falling back to a stronger model on low-confidence responses, with logged cost savings versus an always-use-the-best-model baseline. Domain: AI infrastructure / cost engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-de26f72dd2', 'stage-12-08', 'Prompt Version Control & Regression Suite', 'medium', 'A system prompt library with versioned prompts and an automated eval suite (a fixed set of test inputs with expected-quality criteria) that runs on every prompt change to catch regressions before deploying a new prompt version. Domain: AI engineering / MLOps.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5875c4e614', 'stage-12-08', 'Eval-Driven Support Bot Improvement Cycle', 'hard', 'Take the Stage 5 support bot, build a 30-example golden eval dataset with graded expected outputs, establish a baseline score, then iterate on the system prompt 3 times, re-running the eval each time and documenting the score progression and specific failure modes fixed. Domain: AI quality engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-cda9317d00', 'stage-13-01', 'Local-First Bookmark Manager with Sync', 'hard', 'A bookmark manager storing data primarily in IndexedDB with a background sync-to-server layer, handling the case where local and server data diverge while offline, including a documented conflict-resolution strategy. Domain: productivity tools.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-ea00aa186a', 'stage-13-02', 'CPU-Heavy Data Processing Without UI Freeze', 'medium', 'A tool that processes a large CSV/JSON file (parsing, aggregation) entirely inside a Web Worker using comlink for clean async communication, keeping the UI thread responsive throughout — with a visible before/after (UI freezes without the worker, doesn’t with it).');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-3271c192e5', 'stage-13-03', 'Cross-Tab Session Sync', 'medium', 'A demo app where logging out in one browser tab immediately logs the user out in all other open tabs of the same app, using the Broadcast Channel API. Domain: security/session management UX.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d02300f7ba', 'stage-13-04', 'Native Page Transition Gallery', 'hard', 'A multi-page image gallery using the View Transitions API for smooth native page-to-page morph animations (image expanding into a detail view), with a custom CSS Houdini paint worklet used for one decorative element (e.g., a custom-drawn border or background pattern). Domain: creative/media portfolios.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-b31a528800', 'stage-13-05', 'Offline-Capable Collaborative Doc with Peer Fallback', 'hard', 'A collaborative text document combining y-indexeddb (offline persistence), y-websocket (primary sync via a Hocuspocus server), and y-webrtc as a peer-to-peer fallback when the server is unreachable, demonstrating that edits made offline merge correctly once any sync path reconnects. Domain: collaborative software infrastructure.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-1a4460659d', 'stage-13-06', 'Notion-Style Block Editor', 'hard', 'A rich text editor built with Tiptap (on ProseMirror) supporting headings, lists, code blocks, and a custom block type you build yourself (e.g., an embeddable "callout" box), with full keyboard shortcuts and markdown-style input rules (typing "# " converts to a heading). Domain: productivity / content tools. Integrate Tiptap with Yjs for real-time collaborative rich-text editing with live cursors showing collaborator names/colors — a genuine Google-Docs-style editing experience built from open primitives. Domain: collaborative software.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-2db3c740c1', 'stage-14-01', 'API Breaking Point Report', 'medium', 'Use k6 to load-test an earlier project’s API, ramping virtual users until it breaks, and produce a written report identifying the exact bottleneck (CPU, DB connections, memory) with graphs. Domain: performance engineering / SRE. Run a distributed load test from multiple geographic regions using k6 Cloud, comparing latency experienced by users in different regions and documenting a CDN/edge-caching recommendation based on findings.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4fba65f2ca', 'stage-14-01', 'Realistic User-Behavior Load Simulation with Artillery', 'hard', 'Model a realistic multi-step user journey (browse → search → add to cart → checkout) as an Artillery scenario with weighted random behavior (not just hammering one endpoint), simulating a realistic traffic spike (e.g., a flash sale) and documenting system behavior under it.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d5f2f92b4a', 'stage-14-02', 'Automated Vulnerability Scanning Pipeline', 'medium', 'Integrate OWASP ZAP into a CI pipeline to automatically scan a staging deployment on every merge, failing the build on high-severity findings. Domain: DevSecOps.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-d9acd6864d', 'stage-14-02', 'Nonce-Based CSP Hardening', 'hard', 'Implement a strict, nonce-based Content Security Policy on a real app (no unsafe-inline), correctly generating a fresh nonce per request and wiring it through server-rendered script tags, verified with a CSP evaluator and a deliberate XSS-attempt test that gets blocked.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-5436f459bb', 'stage-14-03', 'Secret Leak Prevention Pipeline', 'medium', 'Configure trufflehog and git-secrets to scan every commit (locally via pre-commit hook and in CI) for accidentally committed secrets, with a deliberate test commit containing a fake API key that gets correctly blocked.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9a36d58a98', 'stage-14-04', 'Continuous Security Posture Dashboard', 'medium', 'A small internal report generator that runs securityheaders.com checks, CSP Evaluator, npm audit, and summarizes Dependabot alert status for a project into a single weekly security posture report. Domain: DevSecOps.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-aedccf94a8', 'stage-14-05', 'SOC 2 & GDPR Readiness Checklist Implementation', 'hard', 'Produce a real, project-specific SOC 2-informed security control checklist and GDPR data-handling checklist for an earlier project, then implement the 5 highest-priority gaps found (e.g., access logging, data export/deletion endpoints) rather than just documenting them. Domain: compliance / security engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-1661173654', 'stage-15-01', 'Framework-Free Vite App from Scratch', 'easy', 'Configure a Vite project from an empty folder (no create-vite scaffold) with TypeScript, path aliases, and environment variable handling, understanding every config option added. Domain: build tooling literacy.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4ba64769ae', 'stage-15-01', 'Dual-Format Publishable Library with tsup', 'medium', 'Take a utility library from Phase 1/4 and configure tsup to build it as both ESM and CJS output with generated type declarations, ready for real npm publishing. Domain: library authoring / open source.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9869a86739', 'stage-15-02', 'Bundle Size Audit & Diet', 'medium', 'Take a real project, run @next/bundle-analyzer (or vite-bundle-visualizer for non-Next projects), identify the 3 largest unnecessary dependencies or duplicated code, and reduce total bundle size by a documented, measurable percentage.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4be1ad1289', 'stage-15-04', 'Themeable Component Library, Three Ways', 'hard', 'Rebuild the same 4-component set using styled-components, Emotion, and Linaria (zero-runtime) respectively, then write a hands-on comparison of DX, runtime performance cost, and SSR complexity for each. Domain: frontend architecture decision-making.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-051dc32083', 'stage-16-01', 'Direct-to-S3 Upload System', 'medium', 'A file upload feature using pre-signed S3 URLs so large files upload directly from the browser to S3 (not proxied through your server), with upload progress tracking and correct bucket policy/CORS configuration. Domain: media/file storage infrastructure.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-7277dd242f', 'stage-16-02', 'Terraform Security Scan Gate', 'medium', 'Integrate tfsec into a CI pipeline that scans Terraform plans for security misconfigurations (e.g., a publicly-open security group) before allowing an apply, with a deliberately insecure resource that gets correctly blocked.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-08c1e8fc43', 'stage-16-03', 'Local Kubernetes Deployment', 'medium', 'Deploy a full-stack app (frontend + backend + database) to a local Kubernetes cluster using kind, with proper Deployments, Services, and ConfigMaps/Secrets, managed entirely via kubectl.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-4241833b12', 'stage-16-03', 'Zero-Downtime Rolling Update Demo', 'hard', 'Configure a Kubernetes Deployment with proper readiness/liveness probes and rolling update strategy, then deploy a breaking change and demonstrate (with live traffic during the deploy) that users experience zero downtime, followed by a deliberately bad deploy that gets automatically rolled back.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9485154d7f', 'stage-16-04', 'Auto-Scaling Load Demonstration', 'hard', 'Configure a Horizontal Pod Autoscaler on a deployed service, then load-test it (tying back to Phase 14’s k6 work) and record real pod-count scaling behavior as load increases and decreases.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-6ef619d18b', 'stage-16-04', 'Secure Secret Sync from Cloud Secret Manager', 'hard', 'Configure external-secrets to sync secrets from a cloud secret manager (or a compatible local equivalent) into Kubernetes Secrets automatically, so no secret is ever manually kubectl-applied or committed anywhere.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-9d22fa552e', 'stage-17-01', 'Optimistic Social Feed', 'medium', 'A social-media-style feed where likes/comments appear instantly (optimistic update) with correct rollback on simulated server rejection, backed by a cache-aside and a write-through caching strategy compared side-by-side on two different data types in the same app.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-25ee0faeb0', 'stage-17-02', 'Idempotent Payment Retry Handler', 'hard', 'A payment processing endpoint that safely handles duplicate/retried requests (e.g., a client retrying after a timeout) using an idempotency key, proven with a test that fires the same request 10 times concurrently and confirms only one charge occurs.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-cbb235ac97', 'stage-17-03', 'Order Fulfillment Saga', 'hard', 'Model a multi-step order fulfillment process (charge payment → reserve inventory → schedule shipping) as a Saga with proper compensating transactions for each step, demonstrated by deliberately failing the shipping step and proving payment gets correctly refunded and inventory released.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-bfb7563497', 'stage-17-03', 'Resilient Event-Driven Order Pipeline', 'hard', 'The same order pipeline rebuilt using the Outbox pattern (to guarantee at-least-once event publishing alongside the DB transaction), a Dead Letter Queue for messages that repeatedly fail processing, and a Circuit Breaker around a flaky downstream shipping-provider API call.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-0d27271d7f', 'stage-17-04', 'CQRS-Based Reporting System', 'hard', 'Split a write-heavy transactional data model from a read-optimized reporting model using CQRS — writes go through a normalized command model, reads are served from a denormalized, eventually-consistent query model — with documented consistency-lag behavior.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-80001e5d1d', 'stage-17-05', 'Row-Level Multi-Tenant SaaS Data Layer', 'hard', 'Implement multi-tenancy for a SaaS app using a shared-database, row-level isolation strategy (tenant_id on every table + enforced query scoping), with a deliberate test proving one tenant can never see another tenant’s data even under a crafted malicious query attempt.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-2fac35da9b', 'stage-17-06', 'Chaos Engineering Game Day', 'hard', 'Run a real chaos engineering exercise against one of your deployed systems: deliberately kill a service instance, inject network latency, or fail a dependency mid-request, and document what broke, what didn’t, and what you fixed afterward. Domain: SRE / resilience engineering.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-daeb84025f', 'stage-18-01', 'Semantic-Release-Ready Open Source Package', 'medium', 'Publish a real npm package (one of your earlier utility libraries) with Changesets managing version bumps and changelogs, wired into CI so merging a changeset automatically publishes a new version. Domain: open source maintenance.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-67db97ba64', 'stage-18-02', 'Architecture Decision Record Backfill', 'medium', 'Go back through 3 major decisions made earlier in this roadmap (e.g., "why Zustand over Redux," "why row-level multi-tenancy over schema-per-tenant") and write proper retroactive ADRs for each, following a consistent template (context, decision, consequences, alternatives considered).');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-8131d692fa', 'stage-18-02', 'RFC for a Real Architecture Change', 'medium', 'Write a full RFC proposing a genuine architectural change to one of your existing projects (e.g., migrating from REST to GraphQL, or adding multi-region support), including alternatives considered and a rollout plan, as if presenting to a real engineering team.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-16d09161ac', 'stage-18-03', 'Personal DORA Metrics Tracker', 'medium', 'A small tool/dashboard that tracks your own deployment frequency, lead time for changes, change failure rate, and time to restore across this roadmap’s projects, pulled from real Git/CI history, not estimated.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-a085e11876', 'stage-18-03', 'Blameless Post-Mortem for a Real Bug', 'medium', 'Write a full blameless post-mortem for a real bug or outage you caused somewhere in this roadmap (there will be one), following a proper template: timeline, impact, root cause, contributing factors, and concrete action items.');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-1bf677eb24', 'stage-19-02', 'Portfolio-to-Application Pipeline', 'medium', 'A polished, professional profile presence across Wellfound, Instahyre, and LinkedIn, each tailored to its audience (startup-focused vs. broad), all linking back to a coherent personal portfolio site showcasing this roadmap’s best 4–5 capstone projects with real metrics (not just screenshots).');
insert into public.stage_projects (id, stage_id, name, difficulty, description) values ('proj-09b1f3abdb', 'stage-19-04', 'Technical Deep-Dive Article Series', 'medium', 'Write and publish 3 genuinely useful technical articles (on dev.to and cross-posted to Hashnode) documenting real, hard-won lessons from this roadmap — e.g., "What actually breaks when you load-test a Node API," "I built the same feature with REST and GraphQL, here’s the real difference" — not generic tutorials.');
