insert into public.stage_exercises (id, stage_id, description) values ('ex-55f4e5dfe3', 'stage-18-03', 'Calculate your own deployment frequency and lead time for changes from real Git history of one project.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-9818c6a781', 'stage-18-03', 'Write a blameless post-mortem for a real incident, ensuring the language focuses on systems/process, not individual blame.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-62d44dd7c8', 'stage-18-03', 'Create a Technical Debt Tracking log for one project and prioritize the top 5 items by impact vs. effort.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-dbe8b5c347', 'stage-18-03', 'Track estimated vs. actual time for 5 tasks from this roadmap and write a short reflection on your estimation accuracy.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-4ffcaf92b6', 'stage-18-03', 'Write a short Code Review Conventions doc reflecting standards you’ve actually been applying to your own PRs.');
