insert into public.stage_exercises (id, stage_id, description) values ('ex-1b10c88cea', 'stage-19-01', 'Use JSONPlaceholder to quickly prototype a CRUD UI before wiring it to a real backend, and note how much faster it made early iteration.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-53d72b017d', 'stage-19-02', 'Write 3 different one-paragraph professional summaries, each tailored for Wellfound (startup/mission framing), LinkedIn (broad network framing), and a direct cold-outreach email.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-7d3ecabecf', 'stage-19-02', 'Audit your own LinkedIn/Wellfound profile against 3 real job postings you’d actually want, and rewrite your headline/summary to close the gaps.');
