insert into public.stage_exercises (id, stage_id, description) values ('ex-d7a9ce7f83', 'stage-19-03', 'Post a genuine build-in-public update about one of your projects to Indie Hackers or a relevant community Slack, and engage with resulting feedback.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-5ad406dd80', 'stage-19-04', 'Write one article explaining a genuinely hard bug you fixed somewhere in this roadmap, including the debugging process, not just the fix.');
insert into public.stage_exercises (id, stage_id, description) values ('ex-f258b4a5d6', 'stage-19-04', 'Publish the same article to both dev.to and Hashnode and compare engagement/audience differences.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-01', 'phase-01', 'DevScribe', 'A Personal Developer Journal & Snippet Manager', 'Build a complete, deployable application that: is scaffolded with a proper dotfiles-provisioned dev environment (Stage 1); has full semantic, accessible HTML structure (Stage 2); is responsively styled with hand-written CSS Grid/Flexbox, no framework (Stage 3); implements all core logic in strict TypeScript compiled from scratch, covering async data fetching from a raw Node http server, custom iterators for browsing entries, a Proxy-based reactive UI updater, Web Worker-based full-text search indexing, and IndexedDB or a JSON file store for persistence (Stages 4–5); uses a real SQL database (SQLite is fine) with a normalized schema for entries/tags/snippets and at least 3 non-trivial analytical queries (Stage 6); and is version-controlled with clean Conventional Commit history, a CONTRIBUTING.md, linting, and a documented Git workflow (Stage 7). Deliverable: a working local-first journal/snippet app plus a written architecture doc explaining every technical decision. Domain: developer productivity tools. Why it matters: this project alone demonstrates command of the entire JS/TS/SQL/Git foundation without leaning on any framework crutch.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-02', 'phase-02', 'CivicBoard', 'A Server-Rendered Local Government Issue Tracker', 'A full Next.js 15 App Router application where citizens report local issues (potholes, broken streetlights) and track status. Combines: static public pages for browsing resolved/open issues (ISR), a Server Action-powered report submission form, an authenticated admin dashboard behind middleware with parallel routes (queue / map view / stats), intercepting routes for a "quick view" issue modal, edge-personalized location defaults, and a deployed, benchmarked production build on Vercel with documented caching strategy per route. Domain: civic tech. Why it matters: this is a realistic, socially useful full-stack Next.js app that exercises nearly every App Router feature in one coherent product rather than in isolation.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-03', 'phase-03', 'Atlas', 'A Production-Grade, Multi-Brand Design System', 'Build a documented, installable component library (published as a local/private npm package) combining: a token pipeline (Style Dictionary) as the single source of truth, Tailwind and vanilla-extract both wired to consume those tokens, Radix-based accessible primitives styled with CVA, dark mode and multi-brand theming via next-themes/CSS variables, a schema-driven dynamic form system using react-hook-form \+ Zod, and a hand-built documentation/catalog page showing every component in every variant and theme. Domain: design systems / platform engineering. Why it matters: design systems are one of the highest-leverage, most portfolio-impressive artifacts a front-end engineer can build — this project proves you can architect one, not just consume one.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-04', 'phase-04', 'Pulse', 'A Real-Time Support Ticket Dashboard', 'A support-ticket triage dashboard combining every Phase 4 concept: Zustand for UI-local state (filters, selected ticket), TanStack Query \+ tRPC for fully type-safe server state with optimistic status updates and rollback, an XState machine governing the ticket lifecycle (new → assigned → in-progress → resolved → reopened) with guards preventing invalid transitions, Suspense \+ error boundaries per panel so one broken widget never takes down the dashboard, Intersection/ResizeObserver-driven responsive charts, and a virtualized ticket list handling 50,000+ rows without jank, profiled and documented. Domain: customer support / SaaS operations tooling. Why it matters: this is a realistic "senior front-end engineer" artifact — the kind of dashboard that separates people who know individual libraries from people who can architect a resilient, performant system out of them.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-05', 'phase-05', 'Ledger', 'A Secure Multi-Tenant Expense-Approval API', 'A production-grade backend for a B2B expense-approval SaaS: hand-rolled Express architecture with layered middleware, a normalized multi-tenant PostgreSQL schema (via Prisma) supporting organizations/roles/approval chains, hardened with Helmet/CORS/rate-limiting/sanitization, a from-scratch JWT \+ httpOnly refresh-token auth system with rotation, HMAC-signed webhook endpoints for a simulated payment provider, comprehensive Supertest coverage (happy paths, auth failures, tampered webhooks), and a documented EXPLAIN ANALYZE-driven performance pass on the top 3 slowest endpoints under seeded load. Domain: fintech / B2B SaaS. Why it matters: this is a genuinely defensible "I built a secure backend" portfolio piece — covering real auth, real multi-tenancy, real hardening, not a tutorial CRUD app.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-06', 'phase-06', 'Shipwright', 'A Fully CI/CD-Automated, Containerized SaaS Deployment Pipeline', 'Take any earlier full-stack project (Phase 5’s "Ledger" is a good candidate) and build the complete professional delivery pipeline around it: Vitest \+ React Testing Library \+ MSW unit/component coverage with enforced thresholds, a Playwright E2E suite covering critical journeys across 3 browsers with visual regression checks, a multi-stage Dockerfile and docker-compose local dev environment, a full GitHub Actions pipeline (parallel lint/typecheck/test/E2E jobs, matrix-tested, cached, auto-publishing tagged images to GHCR on merge), and a live production deployment on Render with real status/coverage badges in the README. Domain: DevOps / release engineering. Why it matters: this is the artifact that proves you can ship software professionally, not just write it — the single most common gap between bootcamp-level and production-level engineers.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-06b', 'phase-06b', 'Nomad', 'An Offline-First Field Reporting App', 'A mobile app for field workers (e.g., inspectors, delivery drivers) who often lack connectivity: photo capture with camera permissions handled gracefully, offline-first data entry via AsyncStorage with a sync queue and conflict resolution on reconnect, secure token storage via expo-secure-store, push notifications for assignment updates, a FlatList-based large history view tuned for performance, multi-environment EAS build profiles, and a full store-submission-ready asset package plus at least one OTA update shipped to a test build. Domain: field service / logistics mobile tooling. Why it matters: offline-first, secure, store-ready mobile apps are a distinct and valuable skill set from web development — this proves end-to-end mobile shipping competence.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-07', 'phase-07', 'OpenGateway', 'A Fully Documented, Dual-Paradigm Public API Product', 'Take an existing backend (Phase 5’s "Ledger" works well) and ship it as a genuine API product: a complete hand-written OpenAPI 3.0 spec rendered via Swagger UI, Mermaid-diagrammed architecture and auth-flow documentation, a parallel GraphQL interface over the same data exposing at least one N+1-fixed resolver, a curated Postman collection with environments and auto-refreshing auth, and a written REST-vs-GraphQL decision document explaining which consumers should use which interface and why. Domain: developer platforms / API products. Why it matters: documenting and exposing an API well is a distinct, high-value skill from building it — this proves you can make your work usable by other engineers, not just functional.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-08', 'phase-08', 'Interview-Ready', 'A Personal DSA + System Design Reference System', 'Build a personal, structured knowledge base (could be a static site generated from markdown, tying back to Phase 1– 3 skills) cataloging: every pattern from Stages 1–6 with your own annotated solutions and a "recognize this pattern when..." cheat sheet per category, 4 fully written system design case studies with Mermaid architecture diagrams (tying back to Phase 7), and a log of at least 10 timed, REACTO-framework mock interviews with self-critique notes. Domain: career preparation / technical knowledge management. Why it matters: the artifact itself (a searchable, well-organized personal reference) is arguably more valuable long-term than any single solved problem — and building it forces genuine synthesis rather than passive practice.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-09', 'phase-09', 'Meridian', 'A Caching-Optimized SaaS Billing Backend', 'Extend Phase 5’s "Ledger" (or a similar backend) with: Redis cache-aside caching on the highest-traffic read endpoints with measured hit-rate improvements, PgBouncer correctly configured for connection pooling under load, Upstash-based edge-compatible rate limiting on public endpoints, a full React Email \+ Resend transactional email suite (welcome/receipt/billing-alert), and a complete Razorpay subscription billing integration with idempotent, signature-verified webhook handling syncing subscription state into the database. Domain: SaaS infrastructure / fintech. Why it matters: caching, email, and payments are the unglamorous plumbing every real SaaS product needs — getting them right (idempotency, cache invalidation, webhook security) is what separates hobby projects from production systems.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-10', 'phase-10', 'Watchtower', 'A Full Observability & Analytics Platform for a Production App', 'Wrap a complete observability and analytics layer around an earlier full-stack project: AsyncLocalStorage-propagated structured logging (pino) shipped to a real aggregation platform (Grafana Cloud \+ Loki), Sentry error tracking with source maps on both frontend and backend, UptimeRobot-backed public status page, full PostHog funnel instrumentation from landing to conversion with an active feature-flagged A/B experiment, session-recording-driven UX fixes with before/after funnel data, and a GDPR-compliant consent system that actually gates tracking. Domain: SRE / product analytics / privacy engineering. Why it matters: shipping a feature is half the job; knowing whether it works, why it breaks, and whether users actually use it is the other half — this project proves that operational maturity.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-11', 'phase-11', 'Concourse', 'A Real-Time Collaborative Marketplace with Enterprise-Grade Search', 'A live marketplace/auction-style platform combining: WebSocket-based real-time bidding with room-scoped broadcasts and an SSE-based public "live activity feed," a PostgreSQL schema tuned with composite and partial indexes validated via EXPLAIN ANALYZE, materialized-view-backed seller analytics dashboards, documented MVCC/replication behavior from a local primary+replica setup, and Elasticsearch-powered faceted, typo-tolerant listing search benchmarked against a Postgres full-text fallback. Domain: marketplace / e-commerce infrastructure. Why it matters: real-time interactivity and fast, relevant search are the two hardest-to-fake capabilities in consumer products — this project proves you can build both on solid database fundamentals, not just bolt on a SaaS widget.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-12', 'phase-12', 'Sage', 'A Cost-Governed, Eval-Tested RAG Support Platform', 'A complete production-pattern AI support platform: a documentation-grounded RAG pipeline (pgvector, chunking strategy chosen via comparison testing, citation tracking), a cost-optimized multi-tier Claude routing layer with prompt caching on the static knowledge base, tool-calling-based structured ticket extraction validated with Zod, BullMQ-queued background processing for bulk document ingestion with a Bull Board monitoring dashboard, a real-time AI cost dashboard with hard budget enforcement per organization, and a versioned prompt library backed by an automated golden-dataset eval suite that must pass before any prompt change ships. Domain: enterprise AI / support automation. Why it matters: this is what separates "called an LLM API" from "built a production AI system" — grounding, cost control, and evaluation discipline are the actual hard parts.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-13', 'phase-13', 'Confluence Lite', 'A Real-Time Collaborative Document Workspace', 'A Notion/Google-Docs-style collaborative workspace: a Tiptap-based rich text editor with custom block extensions, fully wired to Yjs for real-time collaborative editing (y-websocket primary sync via a Hocuspocus server, y-indexeddb for offline persistence, y-webrtc as a peer-to-peer fallback), live cursor presence, cross-tab session sync via Broadcast Channel, CPU-heavy operations (e.g., full-document search indexing) offloaded to a Web Worker via comlink so typing never lags, and smooth View-Transitions-powered navigation between documents. Domain: collaborative productivity software. Why it matters: real-time collaborative editing is one of the most technically demanding categories of web application — building a working version from open primitives (not a SaaS embed) is a genuine senior-level achievement.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-14', 'phase-14', 'Bastion', 'A Load-Tested, Security-Hardened Production Audit', 'A full offensive-and-defensive audit of an earlier full-stack project: k6 and Artillery load tests establishing real breaking points and p99 latency under realistic traffic simulation, a documented OWASP Top 10 self-audit with real vulnerabilities found and fixed, a nonce-based strict CSP and JWT algorithm pinning implemented and verified, automated secret scanning wired into CI, a continuous security-header/dependency-audit reporting pipeline, and a GDPR-compliant data export/deletion implementation backed by a written SOC 2-informed access control policy. Domain: application security / SRE. Why it matters: this is the project that proves you don’t just build features — you can find out where your own system breaks and where it’s vulnerable, and actually fix it, which is precisely what separates confident production engineers from tutorial-followers.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-15', 'phase-15', 'Featherweight', 'A Bundle-Size-Obsessed Component Library', 'Publish a small, genuinely optimized component library: authored and bundled with tsup (dual ESM/CJS \+ types), a documented before/after bundle-size reduction case study using bundle analyzers, a CI pipeline enforcing a Lighthouse performance budget on the accompanying demo site, and a written comparative report on styled-components vs. Emotion vs. Linaria implementations of the same components with real measured runtime cost differences. Domain: frontend performance / library engineering. Why it matters: most engineers never measure what their styling/build choices actually cost; this project builds the habit of verifying performance claims with real numbers instead of assumptions.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-16', 'phase-16', 'Foundry', 'A Fully Terraform-and-Kubernetes-Managed Production Platform', 'Take an earlier full-stack project and rebuild its entire infrastructure as code: S3 pre-signed direct uploads for media, all cloud resources defined in Terraform with tfsec-gated CI and Terraform Cloud remote state, the application itself packaged as a Helm chart deployed to Kubernetes with readiness/liveness probes enabling zero-downtime rolling updates, a Horizontal Pod Autoscaler validated under real k6 load, and external-secrets syncing all credentials so nothing sensitive is ever manually applied. Domain: platform engineering / DevOps infrastructure. Why it matters: this is genuine platform-engineer-level work — reproducible, auditable infrastructure is what lets a team scale past "it works on the one server I set up manually."');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-17', 'phase-17', 'Resilient Commerce', 'A Distributed, Multi-Tenant Order Platform', 'A multi-tenant e-commerce order platform combining every pattern in this phase: optimistic-locked inventory and idempotent payment handling preventing overselling and double-charges, a Saga-orchestrated fulfillment pipeline with the Outbox pattern for reliable event publishing, a Circuit Breaker and Dead Letter Queue protecting against a flaky shipping provider, an event-driven notification system decoupled via pub/sub, a CQRS-split reporting layer for seller analytics, strict row-level multi-tenant data isolation proven under adversarial testing, and a blue-green deployment pipeline validated with a real chaos engineering game day. Domain: e-commerce / distributed systems. Why it matters: this is the single most architecturally advanced project in the entire roadmap — it proves genuine distributed-systems thinking, not just feature-building.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-18', 'phase-18', 'Glasshouse', 'A Fully Documented, Publishable Engineering Portfolio Project', 'Take your single most impressive project from anywhere in this roadmap and bring its engineering craft to a publishable standard: a Changesets-managed, auto-published package extracted from its reusable internals, a complete ADR history and RFC for its next proposed evolution, real DORA metrics pulled from its Git/CI history, a blameless post-mortem for a genuine incident, and the full documentation set (ARCHITECTURE.md, DECISIONS.md, PERFORMANCE.md, SECURITY.md, MONITORING.md, OPERATIONS.md, TECH\\\_DEBT.md, PRODUCT\\\_DECISIONS.md) written to a standard where a stranger engineer could fully onboard and operate it without ever talking to you. Domain: engineering craft / technical leadership. Why it matters: documentation and process discipline is what makes an individual’s work into an organization’s asset — this is the artifact that signals senior/staff-level maturity, not just coding ability.');
insert into public.capstones (id, phase_id, name, title, description) values ('capstone-19', 'phase-19', 'Launch', 'A Complete Public Engineering Presence', 'Synthesize the entire roadmap into a real public footprint: a portfolio site (built with everything learned in Phases 1–3) showcasing your 5 strongest capstones with real architecture docs linked in, a genuine Product Hunt launch of your best project with measured traction, a 3-part technical article series published across dev.to and Hashnode documenting real lessons learned (load testing failures, security findings, architectural tradeoffs — not tutorials), and tailored, live profiles on LinkedIn/Wellfound/Instahyre driving toward real conversations. Domain: career development / developer relations. Why it matters: an extraordinary body of technical work that nobody knows about has zero career leverage — this final phase converts 1,159.5 hours of deep engineering work into a visible, credible, discoverable professional presence.');
