insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-01-tiffinos', 0, 'TiffinOS', 'Tiffin Service Management Platform', 'India has ~500,000 home-based tiffin/dabba services. A typical operator manages 50–200 customers, 2–3 delivery boys, daily menus, dietary preferences, subscription pauses, UPI payments, and monthly renewals — entirely on WhatsApp and paper. Swiggy and Zomato don''t solve this. They compete with it.', 'Amma running a tiffin service from her kitchen in Koramangala, Bangalore. 80 customers. 2 delivery boys. Currently: WhatsApp groups, handwritten ledger, GPay screenshots in an album.', 'Nothing affordable. NoBrokerHood and similar apps are for housing societies. Zoho is too heavy. Tiffin operators don''t know what SaaS is — they need something that feels like WhatsApp but runs their business.', 'Subscription management + route optimization + WhatsApp-native notifications + UPI recurring billing in one tool priced at ₹499/month.', ARRAY['Customer subscription management (start, pause, resume, cancel)','Daily menu upload with photo (customers see it via web link)','Delivery boy mobile PWA with offline support','Route optimization (which buildings to hit in which order per area)','UPI/Razorpay subscription with auto-renewal','Monthly statement generation per customer']::text[], ARRAY['Dietary preference engine — no onion, no garlic, Jain, diabetic — auto-flags when menu conflicts with customer preference','WhatsApp Business API integration — delivery confirmation, payment reminder, menu of the day — all via WhatsApp without the operator doing anything manually','Delivery proof — delivery boy clicks photo at doorstep, timestamped, geo-tagged, sent to customer automatically','Subscription health dashboard — churn rate, average subscription length, peak pause months, revenue forecast','Customer self-service portal — customer logs in, pauses their own subscription, changes address, views their own payment history','Multi-branch support — operator with 2 kitchens in different areas manages both from one dashboard','P&L per month — ingredients cost (manual input) vs revenue = profit margin per month']::text[], '[{"feature": "PWA with offline delivery boy app", "phase": "Phase 13 (IndexedDB + Web Workers)"}, {"feature": "WhatsApp Business API", "phase": "Phase 07 (API documentation + webhooks)"}, {"feature": "Route optimization", "phase": "Phase 08 (DSA \u2014 graph traversal)"}, {"feature": "Razorpay subscriptions", "phase": "Phase 09"}, {"feature": "Real-time delivery tracking", "phase": "Phase 11 (WebSockets)"}, {"feature": "Multi-tenant (per tiffin service)", "phase": "Phase 17 (multi-tenancy pattern)"}, {"feature": "Churn prediction", "phase": "Phase 12 (AI)"}]'::jsonb, '₹499/month per tiffin service. 100 customers = ₹49,900 MRR. Land and expand.', 'Walk into any residential area in Bangalore and ask who delivers tiffin. Every apartment complex has 2–3. Offer free first month.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-02-batchiq', 1, 'BatchIQ', 'Coaching Institute Management System', 'India has 1.5 million coaching institutes. 90% are small (10–500 students). They manage batches, attendance, fee collection, test scores, and parent communication on Excel, WhatsApp, and paper registers. Extramarks and similar tools cost ₹2–5 LPA and are built for large institutes. Small coaching institutes have nothing.', 'A JEE coaching teacher in Rajajinagar, Bangalore running 3 batches of 40 students each. Collects fees manually. Tracks attendance on a register. WhatsApps test scores to parents individually.', 'Extramarks, Teachmint (shut down free tier), ClassPlus. All either too expensive or too feature-bloated for small operators.', 'A lightweight, affordable (₹999/month) institute manager that a single teacher can set up in one afternoon.', ARRAY['Batch and student management','Attendance marking (teacher marks per class)','Fee collection tracker with defaulter list','Test score entry and report card generation','Automated WhatsApp/SMS to parents on fee due, test results, attendance']::text[], ARRAY['AI weak topic detector — based on 3+ test scores, identifies which chapters a student consistently underperforms in and surfaces this to teacher and parent','Batch scheduler with conflict detection — teacher tries to schedule Physics batch on Monday 5 PM but already has Chemistry at that time — system blocks and suggests alternatives','Fee defaulter escalation flow — 7 days overdue: WhatsApp reminder. 15 days: call reminder task assigned to admin. 30 days: batch access restricted automatically','Parent portal — parent sees child''s attendance %, test scores, fee due date, upcoming exams — no WhatsApp needed','Study material distribution — teacher uploads PDF notes, only students in that batch can access — not shared publicly','Performance prediction — based on test score trajectory and attendance, predicts which students are at risk of failing the final exam (logistic regression, not deep ML)','Teacher salary calculator — if teacher is paid per class taken, system calculates monthly salary based on attendance register','Exam countdown dashboard — visible to students: days left to JEE/NEET, daily study targets']::text[], '[{"feature": "Batch access control (RBAC)", "phase": "Phase 05 (auth + roles)"}, {"feature": "AI weak topic detection", "phase": "Phase 12 (embeddings + analysis)"}, {"feature": "Conflict detection algorithm", "phase": "Phase 08 (DSA \u2014 interval scheduling)"}, {"feature": "Automated WhatsApp flow", "phase": "Phase 07 (webhooks)"}, {"feature": "Parent portal (multi-tenant)", "phase": "Phase 17"}, {"feature": "PDF upload + access control", "phase": "Phase 16 (AWS S3)"}, {"feature": "Predictive performance", "phase": "Phase 12 (AI)"}]'::jsonb, '₹999/month per institute. Freemium: up to 30 students free. Upsell: AI features at ₹1,999/month.', 'Every residential neighbourhood has 3–5 tuition centres. Walk in. Show a live demo. Offer free setup.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-03-queuemd', 2, 'QueueMD', 'Clinic Queue and Patient Management System', '80% of small private clinics in India still use paper tokens. Patients arrive, get a number, sit for 2–3 hours with no idea of their position. The clinic has no data on wait times, peak hours, or no-shows. Practo solves this for large clinics. Small single-doctor clinics (which are everywhere) have nothing.', 'Dr. Sharma running a general physician clinic in Indiranagar. 40–60 patients per day. Paper token system. Receptionist manually calls out numbers. No data. No visibility for patients.', 'Practo (expensive, complex), Lybrate (patient-facing booking, not clinic management). Nothing lightweight for the operator side.', 'A ₹799/month system that replaces the paper token with a real-time queue, WhatsApp updates to patients, and a dashboard the doctor can glance at between consultations.', ARRAY['Digital token issuance (patient scans QR at reception or walks in)','Real-time queue display (TV mode for waiting area)','Doctor console (see queue, call next, mark done, skip)','WhatsApp notification when patient is 3 numbers away','Basic patient record (name, phone, reason for visit)','Daily analytics (patients seen, avg wait time, peak hour)']::text[], ARRAY['AI triage — patient enters symptoms at check-in, system estimates priority (routine/urgent/emergency) and suggests queue position to receptionist','Appointment slots + walk-in hybrid — some slots reserved for pre-booked, rest for walk-ins — balanced queue management','Patient history — returning patients linked by phone number, doctor sees last 5 visits in one click','No-show prediction — based on past data, flags patients who historically no-show and automatically overbooks those slots','Multi-doctor routing — clinic has 2 doctors, patient selects doctor or gets auto-assigned based on queue load','Prescription builder — doctor types diagnosis + medicines, system generates a printable prescription (with clinic letterhead) — not meant to replace EMR, just the paper prescription','Lab result upload — patient''s blood test PDF uploaded, linked to their record, sent to their WhatsApp','Monthly clinic report — total patients, revenue estimate (if fee is tracked), busiest days, most common complaints']::text[], '[{"feature": "Real-time queue (WebSockets)", "phase": "Phase 11"}, {"feature": "TV mode display (PWA)", "phase": "Phase 13"}, {"feature": "AI triage scoring", "phase": "Phase 12"}, {"feature": "No-show prediction", "phase": "Phase 12"}, {"feature": "WhatsApp notifications", "phase": "Phase 07"}, {"feature": "Patient history (search)", "phase": "Phase 11 (Meilisearch)"}, {"feature": "S3 for lab reports", "phase": "Phase 16"}]'::jsonb, '₹799/month per clinic. Hardware upsell: pre-configured Raspberry Pi with queue display software (₹4,999 one-time).', 'Stand outside any clinic and wait. Talk to the receptionist, not the doctor. Offer to set it up free for 30 days.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-04-taxstack', 3, 'TaxStack', 'Freelancer GST + TDS + Advance Tax Manager', 'Indian freelancers (developers, designers, consultants) earning ₹5–50 LPA face a compliance nightmare: GST on services (18%), TDS deducted by clients (10%), quarterly advance tax payments, Form 26AS reconciliation, ITR filing. ClearTax solves the filing. Nobody solves the year-round tracking and estimation.', 'A freelance developer in Bangalore earning ₹8 LPA from 4 clients. Gets TDS deducted by 2 of them, not the other 2. Has GST registration. Files ITR but always panics in March trying to reconstruct the year.', 'ClearTax (filing, not tracking), Tally (overkill), Excel (manual, error-prone).', 'A real-time tracker that shows you exactly what you owe and when, auto-generates your GST invoices, and tells you how much to set aside every month.', ARRAY['Client-wise income tracking (per payment received)','TDS deduction logging per client per payment','GST invoice generator (proper format: GSTIN, HSN code, reverse charge flag)','Advance tax calculator with quarterly deadlines','Annual tax estimate (income tax slab + surcharge)','Form 26AS upload and auto-reconcile against your records']::text[], ARRAY['AI expense categorizer — upload bank statement, AI tags each expense as business/personal and identifies deductible items (internet, laptop, software subscriptions)','Monthly set-aside calculator — "this month you earned ₹85,000. Set aside ₹18,700 for taxes. Here''s the breakdown."','TDS mismatch detector — client says they deducted 10% but 26AS shows 5% — system flags and generates a reconciliation report to send client','Quarterly advance tax reminder flow — 15 days before due date: email + dashboard alert with exact amount to pay and Challan 280 instructions','Multi-year comparison — side by side: income, TDS, GST paid, advance tax, final ITR demand — years 2024 vs 2025 vs 2026','Client profitability analysis — Client A pays ₹50k/month but always delays (cash flow impact). Client B pays ₹30k/month on day 1. Real effective rate after delay cost.','Contract to invoice pipeline — upload contract PDF, AI extracts payment milestones, auto-schedules invoice generation dates','ITR data export — generates a pre-filled data sheet compatible with what your CA needs for ITR filing — not filing itself, just the clean data']::text[], '[{"feature": "AI expense categorizer", "phase": "Phase 12 (tool calling + structured extraction)"}, {"feature": "Form 26AS parsing", "phase": "Phase 12 (document RAG)"}, {"feature": "PDF invoice generation", "phase": "Phase 05 (backend)"}, {"feature": "Quarterly reminder scheduler", "phase": "Phase 09 (BullMQ)"}, {"feature": "Contract milestone extraction", "phase": "Phase 12 (AI)"}, {"feature": "Multi-year analytics", "phase": "Phase 10 (PostHog + custom charts)"}]'::jsonb, '₹299/month. Target: 10,000 Indian freelancers = ₹29,90,000 MRR. Very achievable with dev.to + Twitter content about Indian freelancer taxes.', 'Post on IndiaFreelancer subreddit, Indie Hackers India Slack, Twitter with "built a GST tracker for freelancers." You''ll have 50 beta signups same day.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-05-societyos', 4, 'SocietyOS', 'Apartment Society Management Platform', 'India has ~1,00,000 registered housing societies (RWAs). Societies of 50–300 flats manage maintenance collection, visitor entry, parking, complaints, emergency broadcasts, and vendor payments — mostly on WhatsApp groups and Excel. NoBrokerHood exists but is bloated, expensive, and requires a sales process.', 'The secretary of a 120-flat apartment complex in Whitefield, Bangalore. Collects maintenance manually. Manages a WhatsApp group of 120 people where every complaint goes to everyone. Vendor payments tracked on paper.', 'NoBrokerHood (expensive), MyGate (hardware required for gate), ApartmentADDA (heavy). Nothing self-serve and affordable.', 'A self-hostable or ₹2,999/month SaaS that a society secretary can set up without a sales call.', ARRAY['Flat-wise resident directory','Monthly maintenance billing and payment tracking (Razorpay)','Maintenance complaint system (raise, assign, resolve, close)','Visitor pre-approval (resident generates QR, security scans at gate)','Society fund ledger (income vs expenses)','Emergency broadcast (all residents get WhatsApp/SMS instantly)']::text[], ARRAY['SLA tracking on complaints — plumbing complaint must be resolved in 48 hrs — system auto-escalates to committee if not','Vendor performance rating — every vendor (electrician, plumber, security agency) rated by residents after each job — aggregate score visible to committee','Parking slot allocation engine — flat A has 2 cars but only 1 slot allocated. Waiting list management. Temporary visitor parking with time expiry.','Utility meter reading tracker — security enters meter readings on mobile, system calculates water/electricity charges per flat','Committee voting system — propose a motion (install CCTV at gate), all residents vote via app, result auto-published','Defaulter escalation — maintenance unpaid for 60 days: auto-restrict amenity access (gym, clubhouse), auto-generate legal notice template','Annual general meeting (AGM) module — agenda builder, attendance tracking, minutes recorder, resolution publisher','Insurance and AMC tracker — lift AMC expires in 30 days — system alerts committee 60 days in advance']::text[], '[{"feature": "QR code visitor gate pass", "phase": "Phase 05 (JWT one-time tokens)"}, {"feature": "Real-time emergency broadcast", "phase": "Phase 11 (WebSockets)"}, {"feature": "SLA tracking engine", "phase": "Phase 09 (BullMQ scheduled jobs)"}, {"feature": "Voting system (conflict-free)", "phase": "Phase 13 (Yjs for concurrent state)"}, {"feature": "Multi-tenant per society", "phase": "Phase 17"}, {"feature": "Vendor rating search", "phase": "Phase 11 (Meilisearch)"}, {"feature": "Utility calculations", "phase": "Phase 08 (DSA \u2014 calculation engine)"}]'::jsonb, '₹2,999/month per society. 100 societies = ₹2,99,900 MRR. Enterprise: self-hosted license for large builders managing multiple complexes.', 'Every gated community has an RWA WhatsApp group. Find any resident, ask who the secretary is. Offer to set it up free for their society.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-06-llmeter', 5, 'LLMeter', 'AI API Cost Intelligence Platform', 'Developers and companies using OpenAI, Anthropic, Gemini, Groq, and Mistral across multiple projects have zero unified visibility into what they''re spending, what''s generating value, and where they''re wasting money. The providers show total usage. Nothing shows you cost per feature, per user, per team, or per experiment.', 'A CTO at a 20-person startup using Claude for document summarization, GPT-4o for customer support, and Haiku for classification. Gets $4,000/month in combined bills. Has no idea which of those three is worth it.', 'Provider dashboards (show total only), LangSmith (observability, not cost intelligence), Helicone (logging, not analytics). Nothing that does cost attribution + ROI analysis + model optimization.', 'A unified cost intelligence layer that sits between your app and the AI APIs, attributes cost to features/users/experiments, and tells you exactly where to cut.', ARRAY['SDK wrapper (replace openai.chat.completions.create with llmeter.create)','Unified dashboard across OpenAI + Anthropic + Google + Groq','Cost attribution by project, feature, user ID, and custom tags','Budget alerts with hard cutoffs (stop calling API when budget hit)','Model comparison (same prompt, 3 models, cost vs quality score)']::text[], ARRAY['Automatic circuit breaker — feature X has spent 80% of its weekly budget by Tuesday. System automatically downgrades from GPT-4o to Haiku for that feature until Sunday reset — zero engineer intervention','Prompt optimization engine — takes your prompt, runs it through a compression pipeline, finds the shortest version that produces equivalent output — shows token reduction and cost saving estimate','A/B test dashboard — route 50% of traffic to GPT-4o, 50% to Claude Sonnet. After 1,000 calls, shows cost per call, latency, and human-rated quality score side by side','Token budget enforcer — automatically truncates context window when approaching limit instead of failing — configurable truncation strategy (trim oldest messages, trim middle, summarize)','Anomaly detection — daily spend suddenly 3x normal. System alerts immediately, shows which feature caused it, provides 1-click rollback to last known config','ROI calculator — "AI support bot handled 1,200 tickets this month at $340. Average human support cost per ticket is $8. You saved $9,260."','Shared cost attribution for agencies — agency managing 10 client AI budgets. Each client sees only their own usage. Agency sees all.','Weekly digest — every Monday: what you spent, what changed, what to optimize this week. Sent to Slack.']::text[], '[{"feature": "SDK wrapper (npm package)", "phase": "Phase 18 (Changesets + publishing)"}, {"feature": "Circuit breaker pattern", "phase": "Phase 17"}, {"feature": "A/B testing engine", "phase": "Phase 10 (PostHog)"}, {"feature": "BullMQ budget reset jobs", "phase": "Phase 09"}, {"feature": "Anomaly detection", "phase": "Phase 12 (AI analysis)"}, {"feature": "Multi-tenant per agency client", "phase": "Phase 17"}, {"feature": "Real-time cost dashboard", "phase": "Phase 11 (WebSockets)"}]'::jsonb, 'Free: 1 project, 1 model. Pro: ₹1,999/month (unlimited projects). Agency: ₹9,999/month (multi-client). The npm package has 0 cost to distribute — every install is a potential paid user.', 'Post on Hacker News: "Show HN: I built a cost intelligence layer for LLM APIs." Dev Twitter. Indie Hackers. You''ll get users same day.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-07-vaultenv', 6, 'VaultEnv', 'Team Secret and Environment Variable Manager', 'Managing .env files across a team is a disaster. Secrets get shared over Slack. .env files get committed to Git accidentally. Staging and production configs drift apart silently. A new developer onboards and spends 2 days collecting env vars from 4 different people. 1Password and Doppler exist but are expensive. dotenv-vault is basic.', 'A 5-person startup team. 3 environments (local, staging, production). 40+ env vars. Currently: a shared Notion doc with secrets in plain text, several Slack "hey what''s the DATABASE_URL for staging?" messages per week.', 'Doppler ($10/user/month), Infisical (open source but complex to self-host), 1Password Secrets Manager (expensive). Nothing simple, affordable, and self-serve.', 'A zero-knowledge encrypted secret manager with a CLI, Git hook integration, and team access controls — priced at ₹999/month flat, not per seat.', ARRAY['Zero-knowledge encryption (server never sees plaintext secrets)','Per-environment vaults (local, staging, production)','Team access controls (admin, developer, read-only)','CLI tool: vaultenv pull --env staging syncs to local .env','Web UI for managing and updating secrets','Access logs (who accessed what, when)']::text[], ARRAY['Git hook auto-installer — vaultenv init in your repo installs a pre-commit hook that scans for accidentally staged secrets and blocks the commit','Secret drift detection — staging has DATABASE_URL but production doesn''t. System surfaces the diff and blocks deployment until acknowledged','Automatic secret rotation — for supported services (PostgreSQL, Redis, Stripe test keys), system rotates secrets on a schedule and pushes new values to all environments automatically','Temporary secret sharing — generate a one-time link that reveals a specific secret for 24 hours — for sharing with contractors without giving vault access','GitHub Actions native integration — vaultenv inject --env production in your CI workflow injects secrets as environment variables without them ever touching a file','Secret usage tracking — which secrets are actually being used? Which ones haven''t been accessed in 90 days? (candidates for cleanup)','Breach alerting — monitors HaveIBeenPwned API and known credential leak databases for your domain — alerts if any secret pattern matches known leaked credentials','Import from existing sources — paste a .env file, import from AWS Secrets Manager, import from Doppler — zero-friction migration']::text[], '[{"feature": "Zero-knowledge encryption", "phase": "Phase 14 (security deep dive)"}, {"feature": "CLI npm package", "phase": "Phase 18 (package publishing)"}, {"feature": "Git hook integration", "phase": "Phase 01 (Git internals)"}, {"feature": "Automatic rotation scheduler", "phase": "Phase 09 (BullMQ)"}, {"feature": "GitHub Actions integration", "phase": "Phase 06"}, {"feature": "Secret drift detection", "phase": "Phase 08 (DSA \u2014 diff algorithm)"}, {"feature": "Audit logs", "phase": "Phase 12 (AsyncLocalStorage + pino)"}]'::jsonb, '₹999/month flat (not per seat). Open-source core, paid for hosted version. Self-hosted enterprise license: ₹49,999/year. The CLI npm package drives discovery.', 'Post on dev.to: "I built a free alternative to Doppler." Every developer team has this problem. GitHub README drives organic installs.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-08-meetmind', 7, 'MeetMind', 'Meeting Intelligence and Action Item Pipeline', 'Knowledge workers spend 30–40% of their time in meetings. 60% of action items decided in meetings never get done — because nobody wrote them down properly, nobody owns them, and nobody follows up. Tools like Otter.ai transcribe. Nobody closes the loop from transcript to tracked, assigned, completed action.', 'An engineering manager at a 30-person startup. 8 meetings/week. After each meeting, manually WhatsApps action items to the team. By Thursday, has forgotten what was decided on Monday. Retros constantly surface "things fell through the cracks."', 'Otter.ai (transcription only), Fireflies.ai (transcription + basic summaries), Notion AI (summarizes but doesn''t assign or track). Nobody does the full pipeline: transcript → action item → owner assignment → deadline → tracking → completion.', 'A pipeline that turns a meeting recording or transcript into tracked, owned, deadline-bound action items synced to wherever your team works (Linear, Jira, Notion, Slack).', ARRAY['Upload recording (MP4/MP3) or paste transcript','AI extraction: summary, decisions made, action items, owner, deadline','Speaker attribution (who owns which action)','Action item tracker with status (pending, in progress, done)','Integration: push to Linear, Jira, Notion, or Slack','Weekly digest: which actions are overdue, which are complete']::text[], ARRAY['Recurring meeting health tracker — same meeting happens every Monday. System tracks: are last week''s action items done before this week''s meeting starts? Generates a "meeting health score" over time.','Decision register — separate from action items, maintains a searchable log of every decision made in every meeting — "when did we decide to use PostgreSQL over MongoDB?" — search and find the exact meeting, minute, and reasoning','Commitment accountability — person X has 12 open action items assigned, 4 overdue. Before your next 1:1 with them, system surfaces this automatically.','Meeting cost calculator — 8 people in a 1-hour meeting. Average salary ₹20 LPA. This meeting cost ₹9,600. Was it worth it?','Auto-agenda builder — for recurring meetings, builds this week''s agenda from: unresolved last week''s action items + topics submitted by team + standing items','Conflict detector — two different meetings made contradictory decisions. AI flags: "Meeting A on Monday decided X. Meeting B on Wednesday decided the opposite. Resolve before proceeding."','Voice memo support — record a quick voice note after an informal hallway conversation. System transcribes and extracts action items same pipeline.','AI meeting coach — after 20 meetings, identifies your patterns: meetings you run have 40% more action items completed vs industry average. Or: your meetings average 67 minutes, your action items average 12 per meeting — suggesting overcrowded agendas.']::text[], '[{"feature": "Whisper API transcription", "phase": "Phase 12 (AI)"}, {"feature": "Action item extraction (tool calling)", "phase": "Phase 12"}, {"feature": "Linear/Jira/Notion integration", "phase": "Phase 07 (API documentation + webhooks)"}, {"feature": "Recurring meeting scheduler", "phase": "Phase 09 (BullMQ)"}, {"feature": "Decision register search", "phase": "Phase 11 (Meilisearch)"}, {"feature": "Real-time collaboration on agenda", "phase": "Phase 13 (Yjs)"}, {"feature": "Meeting cost calculator", "phase": "Phase 08 (DSA)"}]'::jsonb, '₹799/month per team (up to 10 people). ₹1,999/month for 10–50. Enterprise custom. Freemium: 5 meetings/month free.', 'Post on ProductHunt and IndieHackers. Every startup founder has this problem. Cold email 20 engineering managers on LinkedIn with "I built a meeting → action item pipeline."');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-09-offerlens', 8, 'OfferLens', 'Salary Negotiation and Offer Intelligence Platform', 'Indian developers consistently underearn by 20–40% because they don''t negotiate, don''t know market rates, and don''t know how to counter-offer. Glassdoor has stale data. Levels.fyi is US-focused. AmbitionBox is noisy. Nobody aggregates India-specific real-time compensation data and turns it into a negotiation playbook.', 'A developer in Bangalore with 2 years of experience getting their first SDE-2 offer. Offered ₹18 LPA. Has no idea if that''s good. Googles frantically. Gets confused. Accepts because they''re scared to negotiate.', 'Glassdoor (stale, not India-specific), AmbitionBox (crowdsourced, noisy, company-level not role-level), Levels.fyi (US-centric). No negotiation assistance anywhere.', 'An India-specific offer intelligence platform that tells you your real market rate and gives you the exact words to negotiate.', ARRAY['Offer input form (company, role, YOE, city, current comp, offered comp)','Market rate comparison (percentile ranking against real offers)','Counter-offer generator (exact email text, configurable tone)','ESOP/RSU calculator (current valuation → your equity worth today + 4-year vest)','Total compensation normalizer (base + bonus + equity + benefits → single number)','Offer deadline extension request template']::text[], ARRAY['Real-time salary crowd-source — anonymous offer submissions from the community build the database. Better data = better accuracy. Incentive: submit yours to see others.','Company-specific negotiation intelligence — "Razorpay almost always counters the first counter. Their band for SDE-2 in Bangalore goes up to ₹28 LPA. Start your counter at ₹26." — sourced from anonymized community submissions.','Competing offer leverage calculator — you have Offer A at ₹18 LPA and Offer B at ₹21 LPA. Shows you exactly how to use B to negotiate A up: script, timing, framing.','Cost of living adjusted comparison — Offer in Mumbai at ₹22 LPA vs Bangalore at ₹20 LPA vs Hyderabad at ₹18 LPA — real purchasing power after rent, taxes, and cost of living.','Negotiation outcome tracker — community logs: "asked for ₹26, they came back at ₹24, settled at ₹25.5." Builds a dataset of what actually works at each company.','Walk-away number calculator — inputs: current salary, EMI obligations, savings target, lifestyle expenses → minimum acceptable offer. Never negotiate without knowing your floor.','Exploding offer detector — "offer expires in 24 hours" — system tells you: this is a pressure tactic, here is the script to ask for an extension, here is the success rate of this ask at this company.','Post-offer checklist — variable pay structure, notice period buyout, joining bonus clawback clause, ESOP cliff — system flags non-obvious clauses to read carefully.']::text[], '[{"feature": "Counter-offer generator (AI)", "phase": "Phase 12 (Claude tool calling)"}, {"feature": "Salary data crowdsource", "phase": "Phase 05 (PostgreSQL + auth)"}, {"feature": "ESOP calculator", "phase": "Phase 08 (DSA \u2014 financial math)"}, {"feature": "Anonymized data aggregation", "phase": "Phase 14 (security \u2014 anonymization)"}, {"feature": "Real-time percentile ranking", "phase": "Phase 11 (PostgreSQL aggregations)"}, {"feature": "Community submissions search", "phase": "Phase 11 (Meilisearch)"}]'::jsonb, 'Free for offer input and basic comparison. ₹499 one-time for negotiation playbook (counter-offer email, scripts, company-specific intel). ₹199/month for ongoing tracking across multiple offers. B2B: sell anonymized aggregate data to recruiters (₹9,999/month).', 'Post on r/developersIndia, r/CSCareerQuestionsIndia. Tweet "I built a salary negotiation tool specifically for Indian developers." You''ll get 200 signups in 24 hours — this is a universally felt pain point.');
insert into public.advanced_projects (id, order_index, name, tagline, problem, who_exactly, what_exists, the_gap, core_features, advanced_features, skill_mapping, monetization, first_users) values ('adv-project-10-hirekit', 9, 'HireKit', 'AI Interview Design Platform for Hiring Managers', 'Most technical interviews in India are badly designed. Hiring managers copy-paste LeetCode problems without understanding what they test, ask generic HR questions, and evaluate inconsistently — two interviewers at the same company score the same candidate completely differently. Companies make bad hires because the interview doesn''t measure what the job actually requires.', 'An engineering manager at a 40-person startup who has to interview 5 SDE-1 candidates this week. Spends 2 hours writing questions the night before each interview. No rubric. No structured evaluation. Compares candidates based on gut feeling.', 'Greenhouse (ATS, not interview design), Lever (same), HackerRank (coding tests only, not full interview kit). No tool that helps design the full interview loop and standardize evaluation.', 'An AI-powered interview kit generator that turns a JD into a complete, structured interview loop with questions, rubrics, and candidate comparison — taking the prep time from 2 hours to 10 minutes.', ARRAY['JD parser (paste JD, extracts required skills, experience level, responsibilities)','Interview kit generator (DSA round, technical round, system design round, behavioural round)','Per-question evaluation rubric (what a 1/2/3/4/5 answer looks like)','Interviewer scorecard (filled in real-time during interview)','Candidate comparison dashboard (structured, not gut feeling)','Interview kit sharing with co-interviewers']::text[], ARRAY['Bias detection engine — interviewer A consistently scores women lower on system design. Interviewer B scores IIT candidates higher on behavioural regardless of answer quality. System flags statistical anomalies.','Question difficulty calibration — AI estimates difficulty of each question for the target level (SDE-1 vs SDE-2). Flags if your SDE-1 interview has too many SDE-3 questions.','Skill coverage heatmap — your interview kit tests React 4 times but never tests PostgreSQL despite it being in the JD. Visual gap analysis.','Debrief facilitator — after all interviews done, system generates a structured debrief agenda: here are the areas where interviewers disagreed, here are questions to resolve the disagreement.','Historical predictors — after 20+ hires, system identifies which interview signals actually predicted job performance (based on 6-month performance review data you input). Surfaces: "candidates who scored 4+ on system design have 80% chance of exceeding expectations at 6 months."','Candidate experience score — optional: candidate fills anonymous feedback after interview. Company gets aggregate score on interviewer quality, question clarity, and overall experience.','Interview question bank — company builds their own question library over time. Tag by skill, level, type. Search and reuse. Never write a new question from scratch.','Offer vs reject explainer — generates a structured, legally defensible explanation for reject decisions — useful for companies that want to give feedback or protect against disputes.']::text[], '[{"feature": "JD parser (AI extraction)", "phase": "Phase 12 (tool calling)"}, {"feature": "Bias detection (statistical)", "phase": "Phase 10 (analytics + PostHog)"}, {"feature": "Question difficulty calibration", "phase": "Phase 12 (AI scoring)"}, {"feature": "Real-time collaborative scorecard", "phase": "Phase 13 (Yjs)"}, {"feature": "Historical predictor analysis", "phase": "Phase 12 (AI + pgvector embeddings)"}, {"feature": "Question bank search", "phase": "Phase 11 (Meilisearch)"}, {"feature": "RBAC (interviewer vs admin)", "phase": "Phase 05"}]'::jsonb, '₹2,999/month per company (up to 5 active job roles). ₹7,999/month for unlimited roles. Enterprise: ₹49,999/year with ATS integration. Freemium: 1 active role, 3 kits/month.', 'Cold email 20 engineering managers at Bangalore startups with "I''ll build your interview kit for your next role for free." They say yes. You get real feedback. You get testimonials. You get paying customers.
