update public.topics set stage_id = 'stage-01-04', heading_number = 54, intro = 'Not new material — this is a deliberate recap checkpoint pulling together let/const, arrow functions, template literals, destructuring, modules, classes, promises, async/await, optional chaining, nullish coalescing, BigInt, and dynamic import, all of which were taught individually above. Placed last in the JS stage as a consolidation pass before moving to TypeScript.' where id = 'topic-01-054';
