update public.topics set stage_id = 'stage-02-02', heading_number = 16, intro = 'Fetch itself is a Web/JS standard, but placed here rather than in Phase 01 because Next.js extends it with its own caching options — learning it in isolation first would teach the wrong mental model for this framework.' where id = 'topic-02-016';
update public.topics set stage_id = 'stage-02-03', heading_number = 17, intro = 'Simplest advanced routing feature — pure organizational syntax, no new rendering behavior.' where id = 'topic-02-017';
