update public.topics set stage_id = 'stage-02-03', heading_number = 21, intro = 'Requires the caching model (Stage 2, Topic 10\\) — revalidation only makes sense once you understand what''s being cached and why.' where id = 'topic-02-021';
update public.topics set stage_id = 'stage-02-03', heading_number = 22, intro = 'Same family as revalidatePath (21), placed immediately after — tag-based revalidation is the more granular alternative once path-based revalidation is understood.' where id = 'topic-02-022';
