update public.topics set stage_id = 'stage-02-05', heading_number = 25, intro = 'Not an explicit line item in the original topic list, but required conceptual grounding before Hydration (26) makes sense — added here rather than assumed.' where id = 'topic-02-025';
update public.topics set stage_id = 'stage-02-05', heading_number = 26, intro = 'Requires Server/Client boundaries (Stage 2, Topic 9\\) and the data-fetching library context (25) — this is the mechanism for passing server-fetched data into client-side cache without a refetch.' where id = 'topic-02-026';
