update public.topics set stage_id = 'stage-03-01', heading_number = 3, intro = 'Independent of custom properties/@layer — a different scoping strategy (build-time class name hashing) worth understanding before comparing it to Tailwind''s utility-first approach.' where id = 'topic-03-003';
update public.topics set stage_id = 'stage-03-01', heading_number = 4, intro = 'A naming methodology, not a tool — placed here because it''s most relevant when writing vanilla CSS or CSS Modules class names, and understanding it clarifies why utility-first CSS (next stage) was a reaction against this approach.' where id = 'topic-03-004';
