update public.topics set stage_id = 'stage-03-03', heading_number = 6, intro = 'Simplest of the three — a conditional classname joiner. Entry point into this stage.' where id = 'topic-03-006';
update public.topics set stage_id = 'stage-03-03', heading_number = 7, intro = 'Requires clsx (6) conceptually — solves a problem clsx alone doesn''t: conflicting Tailwind utilities (e.g. two different padding classes) don''t override each other predictably by string concatenation alone.' where id = 'topic-03-007';
