update public.topics set stage_id = 'stage-03-07', heading_number = 18, intro = 'Placed last — a zero-runtime CSS-in-JS alternative to Tailwind''s utility-first approach. Most valuable as a comparison once Tailwind (Stage 2\\) is deeply understood, so the tradeoffs are meaningful rather than abstract.' where id = 'topic-03-018';
