update public.topics set stage_id = 'stage-04-04', heading_number = 10, intro = 'Mechanically covered already (Phase 02, Stage 1, Topic 6). Here: real modal/toast system implementation, now that Zustand (Stage 1\\) exists to manage which portals are open.' where id = 'topic-04-010';
update public.topics set stage_id = 'stage-04-05', heading_number = 11, intro = NULL where id = 'topic-04-011';
update public.topics set stage_id = 'stage-04-05', heading_number = 12, intro = 'Same API family as Intersection Observer (11) — observes size instead of visibility.' where id = 'topic-04-012';
update public.topics set stage_id = 'stage-04-06', heading_number = 13, intro = 'Requires Intersection Observer concepts (11) as a mental model, and TanStack Query''s infinite queries (Stage 2, Topic 3\\) as the typical data source for a virtualized list of unknown/large length.' where id = 'topic-04-013';
update public.topics set stage_id = 'stage-04-06', heading_number = 14, intro = 'Placed last deliberately — profiling is most valuable once there''s a real app with the patterns from every prior stage (Context, Zustand, Query, Suspense, virtualization) to actually measure and compare.' where id = 'topic-04-014';
update public.topics set stage_id = 'stage-05-01', heading_number = 1, intro = NULL where id = 'topic-05-001';
update public.topics set stage_id = 'stage-05-01', heading_number = 2, intro = 'Requires Node''s http model (Topic 1\\) to appreciate what Express abstracts away.' where id = 'topic-05-002';
update public.topics set stage_id = 'stage-05-02', heading_number = 3, intro = NULL where id = 'topic-05-003';
update public.topics set stage_id = 'stage-05-02', heading_number = 4, intro = 'Directly addresses the gap flagged at the end of Stage 1''s Express error-handling section — async route handlers that throw don''t automatically reach Express''s error middleware without this.' where id = 'topic-05-004';
update public.topics set stage_id = 'stage-05-02', heading_number = 5, intro = 'Requires Express middleware model (Stage 1, Topic 2\\) — CORS is applied as middleware.' where id = 'topic-05-005';
update public.topics set stage_id = 'stage-05-02', heading_number = 6, intro = NULL where id = 'topic-05-006';
update public.topics set stage_id = 'stage-05-02', heading_number = 7, intro = 'Requires Express middleware (Stage 1\\) — applied per-route or app-wide to prevent abuse.' where id = 'topic-05-007';
update public.topics set stage_id = 'stage-05-02', heading_number = 8, intro = 'Requires request body handling (Stage 1, Topic 2\\) — sanitizing user-submitted content before storage or before it''s ever rendered as HTML.' where id = 'topic-05-008';
update public.topics set stage_id = 'stage-05-02', heading_number = 9, intro = NULL where id = 'topic-05-009';
update public.topics set stage_id = 'stage-05-03', heading_number = 10, intro = 'Requires a real Express API with routes and middleware (Stages 1–2) — there''s nothing to test until then.' where id = 'topic-05-010';
update public.topics set stage_id = 'stage-05-04', heading_number = 11, intro = 'The largest single topic in this phase — genuine database fundamentals, not just SQL syntax (which Phase 01 already covered at a basic level).' where id = 'topic-05-011';
update public.topics set stage_id = 'stage-05-04', heading_number = 12, intro = 'Requires PostgreSQL fundamentals (11) — an ORM only makes the SQL you already understand more convenient; learning it first would hide what''s actually happening.' where id = 'topic-05-012';
update public.topics set stage_id = 'stage-05-04', heading_number = 13, intro = 'Requires PostgreSQL fundamentals (11) — Supabase is hosted Postgres plus additional services layered on top.' where id = 'topic-05-013';
update public.topics set stage_id = 'stage-05-04', heading_number = 14, intro = 'Same family as Supabase (13) — another hosted Postgres platform, placed immediately after for direct comparison.' where id = 'topic-05-014';
update public.topics set stage_id = 'stage-05-04', heading_number = 15, intro = 'Requires real queries to analyze — needs PostgreSQL (11) and ideally Prisma (12) or raw SQL usage already in place, since this topic is about diagnosing queries you''ve already written.' where id = 'topic-05-015';
update public.topics set stage_id = 'stage-05-05', heading_number = 16, intro = NULL where id = 'topic-05-016';
update public.topics set stage_id = 'stage-05-05', heading_number = 17, intro = 'Moved ahead of JWT (18) from the official ordering — this is the cryptographic primitive JWT''s HS256 algorithm is built on.' where id = 'topic-05-017';
update public.topics set stage_id = 'stage-05-05', heading_number = 18, intro = 'Requires bcrypt (16) for the login flow that precedes token issuance, and HMAC-SHA256 (17) to understand what HS256 signing actually does.' where id = 'topic-05-018';
update public.topics set stage_id = 'stage-05-05', heading_number = 19, intro = 'Requires JWT concepts (18) — jose is a modern, standards-compliant implementation library, relevant here specifically because it''s Edge-Runtime compatible (ties to Phase 02''s Middleware/Edge Runtime, unlike some older JWT libraries that depend on Node-only crypto APIs).' where id = 'topic-05-019';
update public.topics set stage_id = 'stage-05-05', heading_number = 20, intro = 'Requires JWT (18) — this is where the token actually gets stored, addressing the localStorage/XSS problem flagged in Topic 18''s security considerations.' where id = 'topic-05-020';
update public.topics set stage_id = 'stage-05-05', heading_number = 21, intro = 'Requires httpOnly cookies (20) — SameSite is a cookie attribute, meaningless without a cookie-based auth flow already in place.' where id = 'topic-05-021';
update public.topics set stage_id = 'stage-06-01', heading_number = 1, intro = 'Test runner — must exist before anything else in this stage, since every other tool here either extends it or runs inside it.' where id = 'topic-06-001';
update public.topics set stage_id = 'stage-06-01', heading_number = 2, intro = 'Requires Vitest (1) as the runner — RTL provides the rendering and query APIs that run inside Vitest''s test blocks.' where id = 'topic-06-002';
update public.topics set stage_id = 'stage-06-01', heading_number = 3, intro = 'Requires RTL (2) as the base — user-event replaces RTL''s built-in fireEvent with more realistic event sequences.' where id = 'topic-06-003';
update public.topics set stage_id = 'stage-06-01', heading_number = 4, intro = 'Requires component tests with user interactions (2, 3\\) — MSW exists to mock the network calls those interactions trigger (TanStack Query/tRPC calls from Phase 04).' where id = 'topic-06-004';
update public.topics set stage_id = 'stage-06-01', heading_number = 5, intro = 'Requires actual tests to exist (1–4) — coverage reports on what those tests do and don''t exercise.' where id = 'topic-06-005';
update public.topics set stage_id = 'stage-06-01', heading_number = 6, intro = 'Requires v8 coverage output (5) — Codecov is a hosted service for tracking and visualizing that output over time.' where id = 'topic-06-006';
update public.topics set stage_id = 'stage-06-02', heading_number = 7, intro = 'Conceptually distinct from Stage 1 — E2E tests exercise the whole running app (frontend \+ backend \+ database) rather than isolated components, so this naturally follows once the pieces being tested end-to-end already exist across Phases 01–05.' where id = 'topic-06-007';
update public.topics set stage_id = 'stage-06-03', heading_number = 8, intro = 'Requires tests to exist (Stages 1–2) — CI''s entire purpose is running those tests automatically; there''s nothing to automate before they exist.' where id = 'topic-06-008';
update public.topics set stage_id = 'stage-06-04', heading_number = 9, intro = NULL where id = 'topic-06-009';
update public.topics set stage_id = 'stage-06-04', heading_number = 10, intro = 'Requires Docker fundamentals (9) — Compose orchestrates multiple containers that Docker alone runs one at a time.' where id = 'topic-06-010';
update public.topics set stage_id = 'stage-06-04', heading_number = 11, intro = 'Requires Docker images to exist (9) — GHCR is where those images get pushed to be pulled by a deployment target.' where id = 'topic-06-011';
update public.topics set stage_id = 'stage-06-04', heading_number = 12, intro = 'Sits at the direct intersection of GitHub Actions (8) and Docker/GHCR (9, 11\\) — this action automates building and pushing a Docker image as a CI step.' where id = 'topic-06-012';
update public.topics set stage_id = 'stage-06-05', heading_number = 13, intro = 'Requires Docker (9) — Render deploys directly from a Dockerfile or a pushed image (GHCR, Topic 11).' where id = 'topic-06-013';
update public.topics set stage_id = 'stage-06-05', heading_number = 14, intro = 'Placed alongside deployment since it''s a hosting/transport-layer concern most relevant once a real app is being served in production.' where id = 'topic-06-014';
update public.topics set stage_id = 'stage-06-05', heading_number = 15, intro = 'Last topic in the phase — this is literally the "green CI badge" from Exit A''s checklist, and it depends on GitHub Actions (8) already passing reliably before there''s anything honest to badge.' where id = 'topic-06-015';
update public.topics set stage_id = 'stage-06b-01', heading_number = 1, intro = NULL where id = 'topic-06b-001';
update public.topics set stage_id = 'stage-06b-01', heading_number = 2, intro = 'Requires RN fundamentals (1) — Expo is the tooling and managed workflow built around React Native; there''s nothing to build until basic RN concepts exist.' where id = 'topic-06b-002';
update public.topics set stage_id = 'stage-06b-01', heading_number = 3, intro = 'Requires RN fundamentals (1) — React Navigation is RN''s routing library, conceptually parallel to Phase 02''s App Router but for a screen-stack model instead of URLs.' where id = 'topic-06b-003';
update public.topics set stage_id = 'stage-06b-01', heading_number = 4, intro = 'Requires Flexbox from Phase 03''s CSS stage as the point of comparison — this section is entirely about where RN''s implementation diverges from web CSS.' where id = 'topic-06b-004';
update public.topics set stage_id = 'stage-06b-02', heading_number = 5, intro = 'RN''s equivalent to Phase 02''s localStorage/sessionStorage, but asynchronous by design since RN has no synchronous storage API.' where id = 'topic-06b-005';
update public.topics set stage_id = 'stage-06b-02', heading_number = 6, intro = 'Requires Expo (2) specifically — this is an Expo module. Placed directly after AsyncStorage (5) since both are storage mechanisms, but this one is for sensitive data specifically.' where id = 'topic-06b-006';
update public.topics set stage_id = 'stage-06b-03', heading_number = 7, intro = NULL where id = 'topic-06b-007';
update public.topics set stage_id = 'stage-06b-03', heading_number = 8, intro = 'Requires native API usage (7) — platform differences most often surface exactly where native capabilities are involved.' where id = 'topic-06b-008';
update public.topics set stage_id = 'stage-06b-04', heading_number = 9, intro = 'RN''s equivalent to Phase 04''s TanStack Virtual — the same underlying problem (don''t render offscreen items), solved with RN''s built-in list component.' where id = 'topic-06b-009';
update public.topics set stage_id = 'stage-06b-04', heading_number = 10, intro = 'Placed alongside FlatList as a performance topic — Hermes is the JS engine RN apps run on, optimized specifically for mobile startup time and memory.' where id = 'topic-06b-010';
update public.topics set stage_id = 'stage-06b-04', heading_number = 11, intro = 'The most advanced/internals-focused topic in the phase — requires general RN architecture familiarity (Stages 1–3) and Hermes (10) as context, since the New Architecture changes how JS communicates with native code.' where id = 'topic-06b-011';
update public.topics set stage_id = 'stage-06b-05', heading_number = 12, intro = NULL where id = 'topic-06b-012';
update public.topics set stage_id = 'stage-06b-05', heading_number = 13, intro = 'Genuinely last — over-the-air updates only make sense for an app that''s already published (Topic 12\\) and installed on real devices.' where id = 'topic-06b-013';
update public.topics set stage_id = 'stage-07-01', heading_number = 1, intro = 'The most primitive tool in this stage — a command-line HTTP client. Placed first because Postman and Insomnia are graphical abstractions over exactly what curl does directly.' where id = 'topic-07-001';
update public.topics set stage_id = 'stage-07-01', heading_number = 2, intro = 'Requires curl (1) conceptually — Postman is the same request/response model with a GUI, collections, and environment management layered on top.' where id = 'topic-07-002';
update public.topics set stage_id = 'stage-07-01', heading_number = 3, intro = 'Same category as Postman (2) — a lighter-weight alternative GUI HTTP client, placed immediately after for direct comparison.' where id = 'topic-07-003';
update public.topics set stage_id = 'stage-07-02', heading_number = 4, intro = NULL where id = 'topic-07-004';
update public.topics set stage_id = 'stage-07-02', heading_number = 5, intro = 'Directly depends on OpenAPI 3.0 (4) — Swagger UI renders a spec as an interactive, browsable documentation page; it has nothing to render without a spec already written.' where id = 'topic-07-005';
update public.topics set stage_id = 'stage-07-02', heading_number = 6, intro = 'Independent of OpenAPI/Swagger mechanically, but placed here since architecture diagrams naturally complement API documentation for a portfolio README.' where id = 'topic-07-006';
update public.topics set stage_id = 'stage-07-03', heading_number = 7, intro = NULL where id = 'topic-07-007';
update public.topics set stage_id = 'stage-08-01', heading_number = 1, intro = NULL where id = 'topic-08-001';
update public.topics set stage_id = 'stage-08-01', heading_number = 2, intro = 'A specialized two-pointer variant (1) — both pointers move in the same direction, maintaining a "window" between them.' where id = 'topic-08-002';
update public.topics set stage_id = 'stage-08-01', heading_number = 3, intro = 'Independent of two pointers/sliding window mechanically, but grouped here as another foundational array-scanning technique operating on sorted data.' where id = 'topic-08-003';
update public.topics set stage_id = 'stage-08-01', heading_number = 4, intro = 'The simplest possible dynamic programming pattern — placed here as the capstone of array scanning, and a deliberate bridge into Stage 6''s full DP treatment.' where id = 'topic-08-004';
update public.topics set stage_id = 'stage-08-02', heading_number = 5, intro = 'Requires comfort with array iteration (Stage 1\\) — this stage adds a second data structure (hash map) to track information across a single pass.' where id = 'topic-08-005';
update public.topics set stage_id = 'stage-08-03', heading_number = 6, intro = NULL where id = 'topic-08-006';
update public.topics set stage_id = 'stage-08-03', heading_number = 7, intro = 'A specialized stack technique — direct extension of Topic 6, so it must follow it.' where id = 'topic-08-007';
update public.topics set stage_id = 'stage-08-03', heading_number = 8, intro = 'FIFO structure, placed after stack since it''s needed immediately by Stage 4''s BFS — this is the direct prerequisite for that topic.' where id = 'topic-08-008';
update public.topics set stage_id = 'stage-08-04', heading_number = 9, intro = NULL where id = 'topic-08-009';
update public.topics set stage_id = 'stage-08-04', heading_number = 10, intro = 'A tree is a special-case graph — this section directly applies BFS/DFS (9) to the tree-specific traversal orders.' where id = 'topic-08-010';
update public.topics set stage_id = 'stage-08-04', heading_number = 11, intro = 'Requires traversal comfort (9, 10\\) — this is a specialized technique for detecting cycles in linked structures, conceptually related to Two Pointers (Stage 1, Topic 1\\) but applied to pointer-based traversal rather than array indices.' where id = 'topic-08-011';
update public.topics set stage_id = 'stage-08-05', heading_number = 12, intro = 'Placed after traversal (Stage 4\\) since heap-based problems often combine with graph traversal (e.g. Dijkstra-style shortest path, not explicitly listed but a natural next step), and with the frequency-count patterns from Stage 2 for top-K style problems.' where id = 'topic-08-012';
update public.topics set stage_id = 'stage-08-06', heading_number = 13, intro = 'The largest single topic in the phase (58h official). Builds on recursion (Phase 01\\) and directly on Kadane''s Algorithm (Stage 1, Topic 4\\) as a first taste of the core DP insight: solving a problem in terms of smaller subproblems.' where id = 'topic-08-013';
update public.topics set stage_id = 'stage-08-07', heading_number = 14, intro = NULL where id = 'topic-08-014';
update public.topics set stage_id = 'stage-08-07', heading_number = 15, intro = 'Placed last deliberately — this synthesizes not just this phase''s DSA content, but the entire stack built across Phases 01–07 (React/Next.js, state management, backend/database/auth, testing/CI/CD, API design). Nothing before this point could support a system design conversation.' where id = 'topic-08-015';
update public.topics set stage_id = 'stage-09-01', heading_number = 1, intro = NULL where id = 'topic-09-001';
update public.topics set stage_id = 'stage-09-01', heading_number = 2, intro = 'Requires Redis (1) to exist — ioredis is the Node.js client that connects to it; there''s nothing to connect to without Redis running.' where id = 'topic-09-002';
update public.topics set stage_id = 'stage-09-01', heading_number = 3, intro = 'A distinct infrastructure concern from Redis — connection pooling for PostgreSQL (Phase 05), not caching. Placed here to finish the self-hosted infrastructure thread before moving to hosted alternatives in Stage 2\.' where id = 'topic-09-003';
update public.topics set stage_id = 'stage-09-02', heading_number = 4, intro = 'Requires Redis (Stage 1, Topic 1\\) as the concept being offered as a managed service.' where id = 'topic-09-004';
update public.topics set stage_id = 'stage-09-02', heading_number = 5, intro = 'Directly depends on Upstash (4) — this library implements rate limiting on top of Upstash''s Redis. Conceptually extends Phase 05''s express-rate-limit (in-memory, single-instance) to a distributed, serverless-compatible version.' where id = 'topic-09-005';
update public.topics set stage_id = 'stage-09-03', heading_number = 6, intro = NULL where id = 'topic-09-006';
update public.topics set stage_id = 'stage-09-03', heading_number = 7, intro = 'Requires a sending mechanism (Resend, 6\\) to plug into — React Email produces the HTML template; Resend is what actually delivers it.' where id = 'topic-09-007';
update public.topics set stage_id = 'stage-09-04', heading_number = 8, intro = NULL where id = 'topic-09-008';
update public.topics set stage_id = 'stage-10-01', heading_number = 1, intro = 'Node.js''s built-in mechanism for maintaining context across async calls — placed first because structured logging (2, 3\\) is far more useful when every log line can be correlated to a single request.' where id = 'topic-10-001';
update public.topics set stage_id = 'stage-10-01', heading_number = 2, intro = 'Requires AsyncLocalStorage (1) conceptually — pino''s real value shows up once every log line carries consistent request-scoped context.' where id = 'topic-10-002';
update public.topics set stage_id = 'stage-10-01', heading_number = 3, intro = 'Same category as pino (2) — an alternative structured logging library, placed immediately after for direct comparison.' where id = 'topic-10-003';
update public.topics set stage_id = 'stage-10-02', heading_number = 4, intro = NULL where id = 'topic-10-004';
update public.topics set stage_id = 'stage-10-02', heading_number = 5, intro = 'The simplest tool in this stage — external, black-box uptime monitoring, independent of everything else in the phase.' where id = 'topic-10-005';
update public.topics set stage_id = 'stage-10-03', heading_number = 6, intro = NULL where id = 'topic-10-006';
update public.topics set stage_id = 'stage-10-03', heading_number = 7, intro = 'Same category as Better Stack (6) — placed immediately after for direct comparison.' where id = 'topic-10-007';
update public.topics set stage_id = 'stage-10-03', heading_number = 8, intro = 'Broader than pure log aggregation (6, 7\\) — a full observability platform combining metrics, logs, and traces.' where id = 'topic-10-008';
update public.topics set stage_id = 'stage-10-03', heading_number = 9, intro = 'Requires Grafana Cloud context (8) — Loki is specifically Grafana''s log aggregation system, designed to integrate directly with Grafana dashboards.' where id = 'topic-10-009';
update public.topics set stage_id = 'stage-10-03', heading_number = 10, intro = 'Another full observability platform, same family as Grafana Cloud (8) — placed here as a direct comparison point.' where id = 'topic-10-010';
update public.topics set stage_id = 'stage-10-03', heading_number = 11, intro = 'Platform-specific (AWS) rather than general-purpose — placed last in this cluster since it''s most relevant only if the deployment target is AWS specifically, unlike the platform-agnostic tools above.' where id = 'topic-10-011';
update public.topics set stage_id = 'stage-10-04', heading_number = 12, intro = NULL where id = 'topic-10-012';
update public.topics set stage_id = 'stage-10-04', heading_number = 13, intro = 'Requires PostHog (12) to connect to — the client-side SDK, the more common starting point since most product events originate from user interactions in the browser.' where id = 'topic-10-013';
update public.topics set stage_id = 'stage-10-04', heading_number = 14, intro = 'Requires PostHog (12), placed after posthog-js (13) since server-side event tracking is typically added once client-side tracking is already established.' where id = 'topic-10-014';
update public.topics set stage_id = 'stage-10-05', heading_number = 15, intro = 'Requires PostHog (Stage 4\\) as the platform providing this capability.' where id = 'topic-10-015';
update public.topics set stage_id = 'stage-10-05', heading_number = 16, intro = 'Requires Feature Flags (15) as the underlying mechanism — A/B tests are typically implemented as a flag with variant assignment plus tracked outcomes.' where id = 'topic-10-016';
update public.topics set stage_id = 'stage-10-05', heading_number = 17, intro = 'Requires events flowing in from Stage 4 — funnels are built from a sequence of tracked events.' where id = 'topic-10-017';
update public.topics set stage_id = 'stage-10-05', heading_number = 18, intro = 'Requires PostHog (Stage 4\\) — an independent feature grouped here with the other analytics-driven capabilities.' where id = 'topic-10-018';
update public.topics set stage_id = 'stage-10-06', heading_number = 19, intro = 'Deliberately last. You need to know exactly what you''re collecting (Stages 4–5: events, session recordings, feature flag assignments) before you can build accurate, honest consent management around it — this can''t meaningfully come first.' where id = 'topic-10-019';
update public.topics set stage_id = 'stage-11-01', heading_number = 1, intro = 'The simplest real-time mechanism — one-directional, server-to-client, over plain HTTP. Placed first as the baseline before bidirectional communication is introduced.' where id = 'topic-11-001';
update public.topics set stage_id = 'stage-11-01', heading_number = 2, intro = 'Directly motivated by SSE''s one-directional limitation (1) — WebSockets provide full bidirectional communication over a single persistent connection.' where id = 'topic-11-002';
update public.topics set stage_id = 'stage-11-01', heading_number = 3, intro = 'Requires WebSockets (2) as the typical signaling mechanism — WebRTC needs an out-of-band channel to negotiate a peer-to-peer connection before that connection exists, and WebSockets is the standard way to build that signaling channel.' where id = 'topic-11-003';
update public.topics set stage_id = 'stage-11-02', heading_number = 4, intro = 'The default and most common PostgreSQL index type — deepens Phase 05''s "add an index" knowledge into how it actually works.' where id = 'topic-11-004';
update public.topics set stage_id = 'stage-11-02', heading_number = 5, intro = 'Requires B-Tree understanding (4) — composite indexes are still B-Trees, just built across multiple columns.' where id = 'topic-11-005';
update public.topics set stage_id = 'stage-11-02', heading_number = 6, intro = 'Requires B-Tree fundamentals (4) — a natural extension after composite indexes (5), indexing a filtered subset of rows instead of the whole table.' where id = 'topic-11-006';
update public.topics set stage_id = 'stage-11-02', heading_number = 7, intro = 'Independent of the index topics above, but grouped in this stage as another query-performance tool that needs PostgreSQL query fundamentals (Phase 05\\) already in place.' where id = 'topic-11-007';
update public.topics set stage_id = 'stage-11-03', heading_number = 8, intro = 'Foundational to this entire stage — explains how PostgreSQL handles concurrent reads and writes without locking readers out, which is the mechanism VACUUM (9) exists to maintain.' where id = 'topic-11-008';
update public.topics set stage_id = 'stage-11-03', heading_number = 9, intro = 'Directly depends on MVCC (8) — VACUUM exists specifically to reclaim the dead tuples MVCC''s versioning model creates. This topic is meaningless without 8 already understood.' where id = 'topic-11-009';
update public.topics set stage_id = 'stage-11-03', heading_number = 10, intro = 'Placed after VACUUM since Read Replicas (11), which directly depends on WAL, needs to come next — this ordering keeps the WAL → Replicas dependency chain unbroken.' where id = 'topic-11-010';
update public.topics set stage_id = 'stage-11-03', heading_number = 11, intro = 'Directly depends on WAL (10) — replication works by streaming the WAL to a replica and replaying it there.' where id = 'topic-11-011';
update public.topics set stage_id = 'stage-11-03', heading_number = 12, intro = 'A monitoring view, placed last in this stage since it''s most useful once there''s real concurrent activity and replication (9–11) to actually observe.' where id = 'topic-11-012';
update public.topics set stage_id = 'stage-11-04', heading_number = 13, intro = 'Uses PostgreSQL itself (Phase 05, Stage 2 in this phase) — the natural first stop since it requires no new infrastructure.' where id = 'topic-11-013';
update public.topics set stage_id = 'stage-11-04', heading_number = 14, intro = 'Requires PostgreSQL FTS (13) as the baseline it''s being compared against — a dedicated, lightweight search engine.' where id = 'topic-11-014';
update public.topics set stage_id = 'stage-11-04', heading_number = 15, intro = 'Same category as Meilisearch (14) — placed immediately after for direct comparison.' where id = 'topic-11-015';
update public.topics set stage_id = 'stage-11-04', heading_number = 16, intro = 'The most complex and heavyweight option — placed last as the "when you actually need the big guns" capstone, once the lighter alternatives (13–15) and their limits are understood.' where id = 'topic-11-016';
update public.topics set stage_id = 'stage-12-01', heading_number = 1, intro = NULL where id = 'topic-12-001';
update public.topics set stage_id = 'stage-12-01', heading_number = 2, intro = 'Requires the OpenAI API (1) as the interface it''s accessed through — this section is about the specific model''s characteristics, not a new API surface.' where id = 'topic-12-002';
update public.topics set stage_id = 'stage-12-01', heading_number = 3, intro = 'A second, independent provider — placed after OpenAI (1) so the two can be genuinely compared once both are understood, rather than learning one in isolation.' where id = 'topic-12-003';
update public.topics set stage_id = 'stage-12-02', heading_number = 4, intro = 'Requires the OpenAI API (Stage 1, Topic 1\\) as the access mechanism — embeddings are just another API call, conceptually, but the output (a vector) is a fundamentally different kind of data than a chat completion.' where id = 'topic-12-004';
update public.topics set stage_id = 'stage-12-02', heading_number = 5, intro = 'Requires embeddings (4) to have vectors worth storing, and Phase 05/11''s PostgreSQL depth as the database these vectors are stored in.' where id = 'topic-12-005';
update public.topics set stage_id = 'stage-12-02', heading_number = 6, intro = 'Requires pgvector (5) to exist first — this is one of two index types pgvector supports for making similarity search fast at scale.' where id = 'topic-12-006';
update public.topics set stage_id = 'stage-12-02', heading_number = 7, intro = 'Same family as IVFFlat (6) — an alternative vector index type, placed immediately after for direct comparison.' where id = 'topic-12-007';
update public.topics set stage_id = 'stage-12-03', heading_number = 8, intro = 'The largest single topic in the phase (24h official) — genuinely requires everything in Stages 1–2: an LLM API to generate from, embeddings to represent text semantically, and pgvector with a real index to retrieve efficiently.' where id = 'topic-12-008';
update public.topics set stage_id = 'stage-12-04', heading_number = 9, intro = 'Deliberately placed after raw API usage (Stage 1\\) and RAG (Stage 3), not before — understanding the raw mechanics first means the SDK is recognized as a convenience wrapper unifying OpenAI/Anthropic calls, not treated as unexplained magic.' where id = 'topic-12-009';
update public.topics set stage_id = 'stage-12-04', heading_number = 10, intro = 'Requires Redis (Phase 09\\) as its backing store, and a real async workload — RAG''s embedding/indexing pipeline (Stage 3\\) is exactly the kind of long-running, retry-needing work that justifies a job queue.' where id = 'topic-12-010';
update public.topics set stage_id = 'stage-12-04', heading_number = 11, intro = 'Directly depends on BullMQ (10) — a visual dashboard for a queue system that must already exist.' where id = 'topic-12-011';
update public.topics set stage_id = 'stage-12-05', heading_number = 12, intro = NULL where id = 'topic-12-012';
update public.topics set stage_id = 'stage-12-05', heading_number = 13, intro = 'Requires the Anthropic API (Stage 1, Topic 3\\) — a Claude-specific reasoning feature.' where id = 'topic-12-013';
update public.topics set stage_id = 'stage-12-05', heading_number = 14, intro = 'Requires API fundamentals from both providers (Stage 1\\) to be understood — prompt caching applies to both OpenAI and Anthropic, though it''s frequently discussed in an Anthropic context.' where id = 'topic-12-014';
update public.topics set stage_id = 'stage-12-06', heading_number = 15, intro = 'Requires LLM API fundamentals (Stage 1\\) — typically simplified in practice by the Vercel AI SDK (Stage 4, Topic 9), though understanding the raw mechanism first matters.' where id = 'topic-12-015';
update public.topics set stage_id = 'stage-12-06', heading_number = 16, intro = 'Requires both OpenAI (Stage 1, Topics 1–2) and Anthropic (Stage 1, Topic 3; Stage 5\\) to be understood well enough to make a real routing decision between them — this cannot come before both provider tracks exist.' where id = 'topic-12-016';
update public.topics set stage_id = 'stage-12-07', heading_number = 17, intro = NULL where id = 'topic-12-017';
update public.topics set stage_id = 'stage-12-07', heading_number = 18, intro = 'Requires cost tracking (17) as the data source — you can''t enforce a budget without first measuring actual usage.' where id = 'topic-12-018';
update public.topics set stage_id = 'stage-12-08', heading_number = 19, intro = 'Could arguably be introduced earlier, but real prompt engineering skill benefits from having already built RAG (Stage 3\\) and tool calling (Stage 6\\) — there''s more to actually engineer prompts around once those systems exist.' where id = 'topic-12-019';
update public.topics set stage_id = 'stage-12-08', heading_number = 20, intro = 'Genuinely last — requires real, built AI features (RAG from Stage 3, tool calling from Stage 6, prompts from Topic 19\\) to evaluate. Evaluation is meaningless without something to measure.' where id = 'topic-12-020';
update public.topics set stage_id = 'stage-13-01', heading_number = 1, intro = NULL where id = 'topic-13-001';
update public.topics set stage_id = 'stage-13-01', heading_number = 2, intro = 'Directly depends on IndexedDB (1) — idb is a small Promise-based wrapper around the same raw API, removing the callback/event boilerplate.' where id = 'topic-13-002';
update public.topics set stage_id = 'stage-13-02', heading_number = 3, intro = 'Independent of Stage 1 — background thread execution, foundational for offloading expensive work off the main thread.' where id = 'topic-13-003';
update public.topics set stage_id = 'stage-13-02', heading_number = 4, intro = 'Directly depends on Web Workers (3) — comlink is an RPC-style wrapper that removes the manual postMessage/onmessage boilerplate.' where id = 'topic-13-004';
update public.topics set stage_id = 'stage-13-03', heading_number = 5, intro = 'Grouped after Workers (Stage 2\\) since both are fundamentally about communication between separate execution contexts — workers talk to the main thread, Broadcast Channel lets tabs/windows talk to each other.' where id = 'topic-13-005';
update public.topics set stage_id = 'stage-13-04', heading_number = 6, intro = 'Moved ahead of View Transitions API (7) from the official ordering — rAF is the foundational timing primitive that browser rendering concepts build on, including conceptually informing what View Transitions does under the hood.' where id = 'topic-13-006';
update public.topics set stage_id = 'stage-13-04', heading_number = 7, intro = 'Same timing-API family as rAF (6) — scheduling work during idle time instead of every animation frame.' where id = 'topic-13-007';
update public.topics set stage_id = 'stage-13-04', heading_number = 8, intro = 'Requires the rendering-pipeline timing concepts from rAF (6) as context, even though View Transitions is a much higher-level, declarative API.' where id = 'topic-13-008';
update public.topics set stage_id = 'stage-13-04', heading_number = 9, intro = 'The most advanced and niche topic in this cluster — placed last since it requires comfort with the browser''s rendering pipeline (6–8) to be meaningful.' where id = 'topic-13-009';
update public.topics set stage_id = 'stage-13-05', heading_number = 10, intro = NULL where id = 'topic-13-010';
update public.topics set stage_id = 'stage-13-05', heading_number = 11, intro = 'Directly depends on Yjs (10) and WebSockets (Phase 11\\) — one of two transport providers for syncing a Y.Doc between peers.' where id = 'topic-13-011';
update public.topics set stage_id = 'stage-13-05', heading_number = 12, intro = 'Same category as y-websocket (11) — the second transport provider, using WebRTC (Phase 11\\) for peer-to-peer sync instead of a central relay.' where id = 'topic-13-012';
update public.topics set stage_id = 'stage-13-05', heading_number = 13, intro = 'Requires both Yjs (10) and IndexedDB (Stage 1, Topic 1\\) — this is a persistence provider, not a transport provider, storing the CRDT state locally for offline access.' where id = 'topic-13-013';
update public.topics set stage_id = 'stage-13-05', heading_number = 14, intro = 'Requires Yjs and its transport providers (10–13) to be understood — Hocuspocus is a production-ready backend server framework built specifically around Yjs, wrapping the concepts from y-websocket (11) into something deployable.' where id = 'topic-13-014';
update public.topics set stage_id = 'stage-13-06', heading_number = 15, intro = 'The low-level toolkit — placed first because Tiptap (16) is built directly on top of it, and understanding the primitive first means Tiptap is recognized as a convenience layer, not treated as the whole picture.' where id = 'topic-13-015';
update public.topics set stage_id = 'stage-13-06', heading_number = 16, intro = 'Directly built on ProseMirror (15) — a higher-level, extension-based API over the same underlying document model.' where id = 'topic-13-016';
update public.topics set stage_id = 'stage-14-01', heading_number = 1, intro = NULL where id = 'topic-14-001';
update public.topics set stage_id = 'stage-14-01', heading_number = 2, intro = 'Directly depends on k6 (1) — the hosted platform for running the same k6 scripts at larger scale with better result visualization.' where id = 'topic-14-002';
update public.topics set stage_id = 'stage-14-01', heading_number = 3, intro = 'Same category as k6 (1) — an alternative load testing tool, placed immediately after for direct comparison.' where id = 'topic-14-003';
update public.topics set stage_id = 'stage-14-02', heading_number = 4, intro = 'The conceptual foundation for the rest of this stage — every other topic here is a specific tool or mitigation for one or more items on this list.' where id = 'topic-14-004';
update public.topics set stage_id = 'stage-14-02', heading_number = 5, intro = 'Requires OWASP Top 10 (4) as the conceptual framework it scans against — ZAP''s findings only make sense once you know what category of issue each one maps to.' where id = 'topic-14-005';
update public.topics set stage_id = 'stage-14-02', heading_number = 6, intro = 'A specific mitigation for XSS (an OWASP Top 10 item, 4\\) — requires that context, and builds directly on Phase 05''s Helmet.js, which sets basic CSP headers without the nonce refinement covered here.' where id = 'topic-14-006';
update public.topics set stage_id = 'stage-14-02', heading_number = 7, intro = 'A specific mitigation for an authentication vulnerability class (OWASP Top 10, 4\\) — requires Phase 05''s JWT knowledge directly, since this topic is about a specific flaw in naive JWT verification.' where id = 'topic-14-007';
update public.topics set stage_id = 'stage-14-03', heading_number = 8, intro = NULL where id = 'topic-14-008';
update public.topics set stage_id = 'stage-14-03', heading_number = 9, intro = 'The preventive counterpart to trufflehog (8) — placed after it since establishing whether a leak already exists matters before setting up prevention going forward.' where id = 'topic-14-009';
update public.topics set stage_id = 'stage-14-04', heading_number = 10, intro = 'Requires Nonce-Based CSP (Stage 2, Topic 6\\) and Phase 05''s Helmet.js — there''s nothing meaningful to check until real security headers exist to grade.' where id = 'topic-14-010';
update public.topics set stage_id = 'stage-14-04', heading_number = 11, intro = 'A narrower, CSP-specific tool — directly follows securityheaders.com (10) and the Nonce-Based CSP work (Stage 2, Topic 6).' where id = 'topic-14-011';
update public.topics set stage_id = 'stage-14-04', heading_number = 12, intro = NULL where id = 'topic-14-012';
update public.topics set stage_id = 'stage-14-04', heading_number = 13, intro = 'Same category as Dependabot (12) — a manual/CI-triggered check rather than an always-on automated PR bot.' where id = 'topic-14-013';
update public.topics set stage_id = 'stage-14-05', heading_number = 14, intro = NULL where id = 'topic-14-014';
update public.topics set stage_id = 'stage-14-05', heading_number = 15, intro = 'Broader than Phase 10''s GDPR Consent Mode, which was scoped narrowly to analytics/tracking consent banners. This topic covers the wider regulatory picture that consent management is only one part of.' where id = 'topic-14-015';
update public.topics set stage_id = 'stage-15-01', heading_number = 1, intro = NULL where id = 'topic-15-001';
update public.topics set stage_id = 'stage-15-01', heading_number = 2, intro = 'Conceptually distinct from Vite (1) — Vite bundles applications, tsup bundles libraries/packages for publishing (e.g. to npm). Grouped here as the other half of the build-tooling picture.' where id = 'topic-15-002';
update public.topics set stage_id = 'stage-15-02', heading_number = 3, intro = 'Attaches to Next.js (Phase 02), already deeply familiar by this point in the curriculum — the most immediately applicable of the three analyzers.' where id = 'topic-15-003';
update public.topics set stage_id = 'stage-15-02', heading_number = 4, intro = 'Same category as @next/bundle-analyzer (3), attached to Vite (Stage 1, Topic 1\\) instead of Next.js.' where id = 'topic-15-004';
update public.topics set stage_id = 'stage-15-02', heading_number = 5, intro = 'The most general-purpose of the three — since Vite (Stage 1\\) uses Rollup for production builds, this tool can analyze the same output as vite-bundle-visualizer (4), and is also usable standalone for any Rollup-based build outside Vite entirely.' where id = 'topic-15-005';
update public.topics set stage_id = 'stage-15-03', heading_number = 6, intro = 'Requires Phase 06''s GitHub Actions to run in as an automated CI step, and bundle-size awareness from Stage 2 as one of the contributing factors to the performance scores Lighthouse measures.' where id = 'topic-15-006';
update public.topics set stage_id = 'stage-15-04', heading_number = 7, intro = 'The original and most widely-adopted CSS-in-JS library — foundational to this cluster.' where id = 'topic-15-007';
update public.topics set stage_id = 'stage-15-04', heading_number = 8, intro = 'Same category as styled-components (7) — a very similar API, placed immediately after for direct comparison.' where id = 'topic-15-008';
update public.topics set stage_id = 'stage-15-04', heading_number = 9, intro = 'Zero-runtime CSS-in-JS — placed last since it''s the response to the specific runtime-cost tradeoff flagged in styled-components (7). Conceptually the same category as Phase 03''s vanilla-extract, and framed here as a direct comparison to it, not a repeat.' where id = 'topic-15-009';
update public.topics set stage_id = 'stage-16-01', heading_number = 1, intro = 'The simplest standalone cloud primitive in this phase — independent of Terraform and Kubernetes, but a natural starting point since both later stages may reference it (Terraform provisioning a bucket, external-secrets pulling from AWS Secrets Manager in the same ecosystem).' where id = 'topic-16-001';
update public.topics set stage_id = 'stage-16-02', heading_number = 2, intro = NULL where id = 'topic-16-002';
update public.topics set stage_id = 'stage-16-02', heading_number = 3, intro = 'Directly depends on Terraform (2) — a hosted platform for running the same Terraform workflow with managed state and collaboration features.' where id = 'topic-16-003';
update public.topics set stage_id = 'stage-16-02', heading_number = 4, intro = 'Requires Terraform (2) to have configurations to scan — a security scanner for Infrastructure as Code, extending Phase 14''s security-scanning theme (OWASP ZAP, npm audit) into the IaC layer specifically.' where id = 'topic-16-004';
update public.topics set stage_id = 'stage-16-03', heading_number = 5, intro = 'The largest single topic in the phase (46h official) — genuine orchestration fundamentals, not just CLI commands.' where id = 'topic-16-005';
update public.topics set stage_id = 'stage-16-03', heading_number = 6, intro = 'Requires both Kubernetes concepts (5) and Docker (Phase 06\\) — kind runs an entire K8s cluster inside Docker containers, the practical way to actually practice the concepts just introduced without cloud costs or complex setup.' where id = 'topic-16-006';
update public.topics set stage_id = 'stage-16-03', heading_number = 7, intro = 'Requires Kubernetes concepts (5) to have something to control, and kind (6) or a real cluster to actually point at.' where id = 'topic-16-007';
update public.topics set stage_id = 'stage-16-04', heading_number = 8, intro = 'Requires kubectl and core K8s concepts (Stage 3\\) — Helm charts deploy the same underlying resources (Deployments, Services, ConfigMaps) that Topic 5 introduced, just packaged and templated.' where id = 'topic-16-008';
update public.topics set stage_id = 'stage-16-04', heading_number = 9, intro = 'A specific Kubernetes resource type — requires core K8s concepts and kubectl (Stage 3\\) to configure and observe it in action.' where id = 'topic-16-009';
update public.topics set stage_id = 'stage-16-04', heading_number = 10, intro = 'The most specialized, integration-heavy topic in the phase — requires core K8s and kubectl (Stage 3), and is typically installed via Helm (8), making it the natural capstone of this stage.' where id = 'topic-16-010';
update public.topics set stage_id = 'stage-17-01', heading_number = 1, intro = 'Phase 09 already introduced this pattern in practice ("check cache, miss, fetch from DB, populate cache") without naming it formally — this section gives it the formal treatment and contrasts it against the alternative strategy (Write-Through, 2).' where id = 'topic-17-001';
update public.topics set stage_id = 'stage-17-01', heading_number = 2, intro = 'Directly contrasted against Cache-Aside (1) — a different strategy for keeping cache and source of truth in sync.' where id = 'topic-17-002';
update public.topics set stage_id = 'stage-17-01', heading_number = 3, intro = 'Placed after the caching patterns since it''s most commonly paired with a client-side cache layer — Phase 04''s TanStack Query optimistic update support is the direct practical context for this pattern.' where id = 'topic-17-003';
update public.topics set stage_id = 'stage-17-02', heading_number = 4, intro = NULL where id = 'topic-17-004';
update public.topics set stage_id = 'stage-17-02', heading_number = 5, intro = 'Directly contrasted against Optimistic Locking (4) — the opposite assumption about how likely conflicts are.' where id = 'topic-17-005';
update public.topics set stage_id = 'stage-17-02', heading_number = 6, intro = 'Requires both locking strategies (4, 5\\) as context for why retries happen — but its real weight is as a prerequisite for everything in Stage 3: every distributed pattern that follows depends on operations being safely repeatable.' where id = 'topic-17-006';
update public.topics set stage_id = 'stage-17-03', heading_number = 7, intro = 'Foundational to this cluster — requires idempotency (Stage 2, Topic 6\\) since each saga step must be safely retryable if it fails partway.' where id = 'topic-17-007';
update public.topics set stage_id = 'stage-17-03', heading_number = 8, intro = 'Requires Saga (7) as the context it''s commonly used within, and Phase 05''s transaction fundamentals directly — the outbox pattern uses a real database transaction to solve a distributed reliability problem.' where id = 'topic-17-008';
update public.topics set stage_id = 'stage-17-03', heading_number = 9, intro = 'Requires Saga (7) and Outbox (8) as the messaging context that would actually produce messages worth routing to a DLQ.' where id = 'topic-17-009';
update public.topics set stage_id = 'stage-17-03', heading_number = 10, intro = 'Conceptually independent of Saga/Outbox/DLQ (7–9) but grouped in this resilience cluster — requires idempotency (Stage 2, Topic 6\\) for the retries that happen once a circuit recovers.' where id = 'topic-17-010';
update public.topics set stage_id = 'stage-17-04', heading_number = 11, intro = 'Requires Outbox (Stage 3, Topic 8\\) and DLQ (Stage 3, Topic 9\\) as the reliability mechanisms that make an event-driven system actually trustworthy in production, not just a diagram.' where id = 'topic-17-011';
update public.topics set stage_id = 'stage-17-04', heading_number = 12, intro = 'Requires event-driven architecture (11) as context — CQRS is frequently paired with an event-driven system, where commands produce events and a separate read model is built from consuming them.' where id = 'topic-17-012';
update public.topics set stage_id = 'stage-17-05', heading_number = 13, intro = 'Requires Phase 05''s database schema design fundamentals as the foundation for tenant isolation — independent of the distributed systems cluster in Stages 3–4, but needs solid relational modeling to be meaningful.' where id = 'topic-17-013';
update public.topics set stage_id = 'stage-17-06', heading_number = 14, intro = 'Requires Phase 06''s CI/CD pipeline and Phase 16''s Kubernetes/infrastructure context — a deployment strategy for whatever has been built so far.' where id = 'topic-17-014';
update public.topics set stage_id = 'stage-17-06', heading_number = 15, intro = 'Genuinely last in the phase — chaos engineering exists to deliberately break things and verify that the resilience mechanisms built throughout Stages 2–4 (idempotency, circuit breakers, DLQs, sagas) actually work under real failure conditions, not just in theory.' where id = 'topic-17-015';
update public.topics set stage_id = 'stage-18-01', heading_number = 1, intro = 'The one genuinely technical, tool-based topic in this phase — requires Phase 15''s tsup as the build step producing what Changesets actually versions and publishes.' where id = 'topic-18-001';
update public.topics set stage_id = 'stage-18-02', heading_number = 2, intro = NULL where id = 'topic-18-002';
update public.topics set stage_id = 'stage-18-02', heading_number = 3, intro = 'Requires ADR practice (2) as context — an RFC is the pre-decision version of the same discipline: proposing a change and inviting discussion before committing, whereas an ADR records a decision already made.' where id = 'topic-18-003';
update public.topics set stage_id = 'stage-18-03', heading_number = 4, intro = 'Requires Phase 06''s CI/CD pipeline as the thing these metrics actually measure.' where id = 'topic-18-004';
update public.topics set stage_id = 'stage-18-03', heading_number = 5, intro = 'Requires Phase 10''s monitoring/Sentry stack (something to have a real incident about) and ideally Phase 14/17''s chaos engineering work (deliberately-caused incidents are a safe first subject for practicing this).' where id = 'topic-18-005';
update public.topics set stage_id = 'stage-18-03', heading_number = 6, intro = 'Requires real accumulated project history — by Phase 18, ClientSync has enough history across 17 prior phases to have genuine, trackable debt, not hypothetical debt.' where id = 'topic-18-006';
update public.topics set stage_id = 'stage-18-03', heading_number = 7, intro = NULL where id = 'topic-18-007';
update public.topics set stage_id = 'stage-18-03', heading_number = 8, intro = NULL where id = 'topic-18-008';
update public.topics set stage_id = 'stage-18-03', heading_number = 9, intro = 'Conceptually points forward to Stage 4''s documentation artifacts — a ramp-up strategy is largely a curated reading path through exactly those files (ARCHITECTURE.md, DECISIONS.md, and the rest), even though it''s introduced here as a practice before those artifacts are built.' where id = 'topic-18-009';
update public.topics set stage_id = 'stage-18-04', heading_number = 10, intro = 'The literal folder structure for storing ADRs (Stage 2, Topic 2\\) — placed first in this stage since ADRs need somewhere to live before ARCHITECTURE.md (11) can meaningfully reference them.' where id = 'topic-18-010';
update public.topics set stage_id = 'stage-18-04', heading_number = 11, intro = 'Already introduced organically in Phase 17''s Build in Public section as a place to document architectural patterns used and why. This is the fuller, structured treatment — not a repeat, but likely building on a first draft that already exists.' where id = 'topic-18-011';
update public.topics set stage_id = 'stage-18-04', heading_number = 12, intro = 'Requires ADR practice (Stage 2, Topic 2\\) directly — effectively a running index or log view of the same decisions stored individually in docs/adr/ (10).' where id = 'topic-18-012';
update public.topics set stage_id = 'stage-18-05', heading_number = 13, intro = 'Draws directly on Phase 14''s k6 load test results and Phase 10''s monitoring stack as source material.' where id = 'topic-18-013';
update public.topics set stage_id = 'stage-18-05', heading_number = 14, intro = 'Already introduced organically in Phase 14''s Build in Public section ("add a SECURITY.md and note your OWASP Top 10 checks"). This is the fuller treatment, likely extending a file that already exists in some form from Phase 14\.' where id = 'topic-18-014';
update public.topics set stage_id = 'stage-18-05', heading_number = 15, intro = 'Draws on Phase 10''s full observability stack as source material.' where id = 'topic-18-015';
update public.topics set stage_id = 'stage-18-05', heading_number = 16, intro = 'Draws on Phase 16''s infrastructure and Phase 17''s deployment strategy work as source material.' where id = 'topic-18-016';
update public.topics set stage_id = 'stage-18-05', heading_number = 17, intro = 'The literal artifact form of Blameless Post-Mortems (Stage 3, Topic 5\\) — a folder holding the actual post-mortem documents.' where id = 'topic-18-017';
update public.topics set stage_id = 'stage-18-05', heading_number = 18, intro = 'The literal artifact form of Technical Debt Tracking (Stage 3, Topic 6).' where id = 'topic-18-018';
update public.topics set stage_id = 'stage-18-06', heading_number = 19, intro = NULL where id = 'topic-18-019';
update public.topics set stage_id = 'stage-18-06', heading_number = 20, intro = 'The most personal artifact in the phase — a running log of what was learned, not a project-facing document in the same sense as the rest of Stage 4–6.' where id = 'topic-18-020';
update public.topics set stage_id = 'stage-19-01', heading_number = 1, intro = 'A trivial fake REST API used for testing and prototyping — placed first as the simplest possible external API integration, a five-minute exercise rather than a real topic.' where id = 'topic-19-001';
update public.topics set stage_id = 'stage-19-01', heading_number = 2, intro = 'The substantive topic in this stage — placed after JSONPlaceholder (1) as the ''real'' API practice following the trivial one. Directly useful given Phase 18''s published npm package and Changesets workflow.' where id = 'topic-19-002';
update public.topics set stage_id = 'stage-19-02', heading_number = 3, intro = 'Explicitly called out at Exit E for founding engineer roles specifically.' where id = 'topic-19-003';
update public.topics set stage_id = 'stage-19-02', heading_number = 4, intro = 'Same category as Wellfound (3) — an India-focused tech hiring platform, placed immediately after.' where id = 'topic-19-004';
update public.topics set stage_id = 'stage-19-02', heading_number = 5, intro = 'Placed last in this stage deliberately — LinkedIn''s payoff depends on having real content behind the profile. By this phase, per Exit E''s own description, that content already exists: 16 months of Build in Public posts across every prior phase.' where id = 'topic-19-005';
update public.topics set stage_id = 'stage-19-03', heading_number = 6, intro = 'The largest single "launch moment" in this cluster — needs a real, complete product (all prior phases) to launch.' where id = 'topic-19-006';
update public.topics set stage_id = 'stage-19-03', heading_number = 7, intro = 'Requires Product Hunt (6) as the natural launch event to discuss, or stands alone as a place to share the broader building journey.' where id = 'topic-19-007';
update public.topics set stage_id = 'stage-19-03', heading_number = 8, intro = 'Independent of Product Hunt/Indie Hackers mechanically, but grouped here as another community/distribution channel — a niche, India-specific SaaS builder community.' where id = 'topic-19-008';
update public.topics set stage_id = 'stage-19-04', heading_number = 9, intro = 'By this phase, extremely familiar as a posting destination — this section covers deliberately building an audience on it, not just publishing individual posts as each phase''s Build in Public section has called for.' where id = 'topic-19-009';
update public.topics set stage_id = 'stage-19-04', heading_number = 10, intro = 'Same category as dev.to (9) — an alternative technical writing platform, placed after as a redundancy/comparison rather than a replacement.' where id = 'topic-19-010';


